function isAccountingRole(role?: string) {
  return role === "BUCHHALTUNG";
}

function isTabAllowedForRole(tab: AppTab, role?: string) {
  if (isAccountingRole(role)) return tab === "reports";
  if (
    role &&
    tab === "processAutomation" &&
    role !== "ADMIN" &&
    role !== "GESCHAEFTSFUEHRER" &&
    role !== "FUEHRUNGSKRAFT"
  ) {
    return false;
  }
  return true;
}

function getVisibleNavigationTabs(role?: string, hasSalesRole = false) {
  if (hasSalesRole && role !== "ADMIN" && role !== "GESCHAEFTSFUEHRER") {
    const allowedSalesTabs = new Set<AppTab>([
      "overview",
      "reports",
      "contacts",
      "newsFeed",
      "salesHub",
      "projectsSolutions",
      "projectsImmocare",
      "articles",
      "salesOpportunities",
      "dashboard",
      "personalData",
    ]);
    return navigationTabs.filter(([tab]) => allowedSalesTabs.has(tab));
  }

  return navigationTabs.filter(([tab]) => isTabAllowedForRole(tab, role));
}

function getVisibleNavigationActiveTabs(role?: string, hasSalesRole = false) {
  const tabs = getVisibleNavigationTabs(role, hasSalesRole);
  const allowedTabs = new Set<AppTab>();

  tabs.forEach(([tab]) => {
    allowedTabs.add(tab);
    (sidebarChildTabsByParent[tab] ?? []).forEach((childTab) => {
      if (CONTENT_MANAGEMENT_ENABLED || !isContentManagementTab(childTab)) {
        allowedTabs.add(childTab);
      }
    });
  });

  return allowedTabs;
}

function getVisibleReportTabs(role?: string, hasSalesRole = false) {
  const allowedTabsByRole: Record<string, ReportAnalyticsTab[]> = {
    ADMIN: allReportTabs.map((tab) => tab.id).filter((tab) => tab !== "employeeRevenue"),
    GESCHAEFTSFUEHRER: allReportTabs.map((tab) => tab.id).filter((tab) => tab !== "employeeRevenue"),
    FUEHRUNGSKRAFT: ["employeeRevenue", "projects", "svs", "kuzu", "employees", "map"],
    MITARBEITER: ["employeeRevenue", "employees"],
    VERTRIEB: ["forecast", "sales", "projects", "customers", "kuzu"],
    BUCHHALTUNG: ["forecast", "monthlyReport", "customers"],
    GAST: [],
  };
  const allowedTabs = new Set(allowedTabsByRole[role || ""] ?? []);
  if (hasSalesRole) {
    (["forecast", "sales", "projects", "customers", "kuzu"] as ReportAnalyticsTab[]).forEach((tab) => allowedTabs.add(tab));
  }
  return allReportTabs.filter((tab) => allowedTabs.has(tab.id));
}

