    activeUser?.role === "ADMIN" || activeUser?.role === "GESCHAEFTSFUEHRER";
  const canViewOperationalOverviewAnalytics =
    canViewFullOverviewAnalytics || activeUser?.role === "FUEHRUNGSKRAFT";
