    activeUser?.role === "ADMIN" ||
    activeUser?.role === "GESCHAEFTSFUEHRER" ||
    activeUser?.role === "BUCHHALTUNG" ||
    /geschäftsführer|gesch\u00c3\u00a4ftsf\u00c3\u00bchrer|geschaeftsfuehrer|ceo/i.test(activeUser?.roleLabel ?? "") ||
    /ceo/i.test(activeUser?.name ?? "");
  const canDeleteInvoices = activeUser?.role === "GESCHAEFTSFUEHRER";
  const canManageCompanyMasterData =
    activeUser?.role === "ADMIN" || activeUser?.role === "GESCHAEFTSFUEHRER";
  const canDeleteHistoryEntries = activeUser?.role === "GESCHAEFTSFUEHRER";
  const isLostOffer = (offer: Pick<OfferItem, "status">) => offer.status === "Verloren" || offer.status === "Angebot verloren";
  const isDeletedOffer = (offer: Pick<OfferItem, "status">) => isDeletedStatus(offer.status);
  const isDeletedInvoice = (invoice: InvoiceItem) => isDeletedStatus(invoice.status);
  const isFinanciallyActiveInvoice = (invoice: InvoiceItem) => {
    const status = invoice.status.toLowerCase();
    return (
      invoice.status !== "Entwurf" &&
      !isDeletedInvoice(invoice) &&
      !status.includes("storniert") &&
      !status.includes("storno")
    );
  };
  const isOfferWonByInvoice = (offer: Pick<OfferItem, "id" | "offerNumber">) =>
    invoices.some(
      (invoice) =>
        isFinanciallyActiveInvoice(invoice) &&
        (invoice.sourceOfferId === offer.id || invoice.sourceOfferNumber === offer.offerNumber)
    );
  const isWonOffer = (offer: OfferItem) => Boolean(offer.wonAt) || isOfferWonByInvoice(offer);
  const getOfferStatusLabel = (offer: OfferItem) => {
    if (isWonOffer(offer)) return "Angebot gewonnen";
    if (isLostOffer(offer)) return "Angebot verloren";
    return offer.status;
  };
  const isActiveFinalOffer = (offer: OfferItem) =>
    offer.status !== "Entwurf" && !isDeletedOffer(offer) && !isLostOffer(offer);
  const getInvoiceDisplayNumber = (invoice: InvoiceItem) =>
    invoice.status === "Entwurf" ? `${invoice.invoiceNumber} · Entwurf` : invoice.invoiceNumber;
  const renderInvoiceStatusChip = (status: string) => (
    <span className={styles.invoiceStatusChip} data-status={status}>
      {status}
    </span>
  );
  const renderOfferStatusChip = (offer: OfferItem) => (
    <span className={styles.invoiceStatusChip} data-status={isWonOffer(offer) ? "Gewonnen" : isLostOffer(offer) ? "Verloren" : offer.status}>
      {getOfferStatusLabel(offer)}
    </span>
  );
  const openOfferLostComment = (offer: OfferItem) => {
    const comment = offer.lostNote?.trim();
    if (!comment) return;
    window.alert(`Kommentar zu ${offer.offerNumber}:\n\n${comment}`);
  };
  const isAbsenceHandoverComplete =
    absenceType === "krank" ||
    absenceHandoverMode === "none" ||
    (absenceHandoverMode === "open" && absenceHandoverTaskIds.length > 0);

  const assignableUsers = canAssignOther(activeUser?.role)
    ? users.filter((user) => user.isActive)
    : users.filter((user) => user.id === activeUserId && user.isActive);

  const sortedNotifications = useMemo(
    () =>
      [...notifications].sort(
        (first, second) =>
          parseAppDateTime(second.createdAt).getTime() - parseAppDateTime(first.createdAt).getTime()
      ),
    [notifications]
  );
  const unreadNotifications = sortedNotifications.filter((notification) => !notification.readAt);
  const visibleNotifications = showNotificationHistory
    ? notificationHistory.filter((notification) => {
        const normalizedSearchTerm = notificationSearchTerm.trim().toLowerCase();
        if (!normalizedSearchTerm) return true;

        return [notification.subject, notification.body, notification.channel]
          .filter(Boolean)
          .some((value) => value.toLowerCase().includes(normalizedSearchTerm));
      })
    : unreadNotifications;

  async function loadTasks() {
    const res = await fetch("/api/tasks", { cache: "no-store" });

    if (!res.ok) {
      if (res.status !== 401) {
        setErrorMessage("Aufgaben konnten nicht geladen werden.");
      }
      return [];
    }

    const data = (await res.json()) as TaskItem[];
    setTasks(data);
    return data;
  }

  async function loadUsers() {
    const res = await fetch("/api/users", { cache: "no-store" });

    if (!res.ok) {
      if (res.status !== 401) {
        setErrorMessage("Benutzer konnten nicht geladen werden.");
      }
      setAuthChecked(true);
      return;
    }

    const data = await res.json();
    const sessionResponse = await fetch("/api/auth/session", {
      cache: "no-store",
      credentials: "same-origin",
    }).catch(() => null);
    const sessionData = sessionResponse?.ok
      ? ((await sessionResponse.json().catch(() => null)) as { user?: UserOption } | null)
      : null;
    const sessionUser = sessionData?.user ? data.find((demoUser: UserOption) => demoUser.id === sessionData.user?.id) : undefined;
    const storedUserId =
      typeof window !== "undefined" ? window.localStorage.getItem("workpilot-user-id") : null;
    const storedImpersonatedUserId =
      typeof window !== "undefined" ? window.localStorage.getItem("workpilot-impersonated-user-id") : null;
    const storedUser = sessionUser;
    const storedCanImpersonate =
      storedUser?.role === "ADMIN" || storedUser?.role === "GESCHAEFTSFUEHRER";
    const storedImpersonatedUser =
      storedCanImpersonate && storedImpersonatedUserId
        ? data.find((demoUser: UserOption) => demoUser.id === storedImpersonatedUserId && demoUser.isActive)
        : undefined;
    const effectiveUser = storedImpersonatedUser || storedUser;

    setUsers(data);
    setZustaendigId((current) => current || effectiveUser?.id || data[0]?.id || "");
    setAbsenceUserId((current) => current || effectiveUser?.id || data[0]?.id || "");

    if (storedUser) {
      window.localStorage.setItem("workpilot-user-id", storedUser.id);
      setAuthenticatedUserId(storedUser.id);
      setImpersonatedUserId(storedImpersonatedUser?.id || "");
      setActiveUserId(effectiveUser?.id || storedUser.id);
      setOwnerFilter((current) => current || effectiveUser?.id || storedUser.id);
      setKanbanOwnerFilter((current) => current || effectiveUser?.id || storedUser.id);
      setPlanningOwnerFilter((current) => current || effectiveUser?.id || storedUser.id);
      setIsAuthenticated(true);
    } else {
      if (storedUserId && typeof window !== "undefined") {
        window.localStorage.removeItem("workpilot-user-id");
        window.localStorage.removeItem("workpilot-impersonated-user-id");
      }
      setIsAuthenticated(false);
      setAuthenticatedUserId("");
      setImpersonatedUserId("");
      setActiveUserId("");
      setOwnerFilter("");
      setKanbanOwnerFilter("");
      setPlanningOwnerFilter("");
    }

    setAuthChecked(true);
  }

  async function loadEmployeeAssessment(userId: string) {
    if (!activeUserId || !userId) return;

    setIsAssessmentLoading(true);
    setAssessmentError("");

    try {
      const res = await fetch(`/api/employee-assessments?actorId=${activeUserId}&userId=${userId}`, {
        cache: "no-store",
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        setAssessmentError(data.error || "Einschätzung konnte nicht geladen werden.");
        setEmployeeAssessment(emptyEmployeeAssessment);
        return;
      }

      const data = await res.json();
      setEmployeeAssessment(normalizeEmployeeAssessment(data.assessment));
      setAssessmentLoadedUserId(userId);
    } finally {
      setIsAssessmentLoading(false);
    }
  }

  async function saveEmployeeAssessmentSection(
    section:
      | "self"
      | "manager"
      | "measures"
      | "conversation"
      | "unlock-self"
      | "disg-save"
      | "disg-complete"
      | "disg-unlock"
      | "disg-reset",
    data: unknown,
    message = "Einschätzung gespeichert."
  ) {
    if (!activeUserId || !personalAssessmentTargetUserId) return;

    setAssessmentError("");
    setAssessmentSaveMessage("");

    const res = await fetch("/api/employee-assessments", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        actorId: activeUserId,
        userId: personalAssessmentTargetUserId,
        section,
        data,
      }),
    });

    const result = await res.json().catch(() => ({}));
    if (!res.ok) {
      setAssessmentError(result.error || "Einschätzung konnte nicht gespeichert werden.");
      return;
    }

    setEmployeeAssessment(normalizeEmployeeAssessment(result.assessment));
    setAssessmentSaveMessage(message);
  }

  async function loadPlanningEntries() {
    if (!activeUserId) return null;

    const res = await fetch(`/api/planning-entries?actorUserId=${encodeURIComponent(activeUserId)}`, {
      cache: "no-store",
      credentials: "same-origin",
    });

    if (!res.ok) {
      setErrorMessage("Planungen konnten nicht geladen werden.");
      return null;
    }

    const data = (await res.json()) as PlanningEntry[];
    setPlanningEntries(data);
    setErrorMessage((currentMessage) =>
      currentMessage === "Planungen konnten nicht geladen werden." ? "" : currentMessage
    );
    return data;
  }

  async function loadProjectHistoryPlanningEntries(projectId: string) {
    if (!activeUserId || !projectId) return;

    const params = new URLSearchParams({
      actorUserId: activeUserId,
      projectId,
      includeDeleted: "1",
    });
    const res = await fetch(`/api/planning-entries?${params.toString()}`, {
      cache: "no-store",
      credentials: "same-origin",
    });

    if (!res.ok) return;

    const data = (await res.json()) as PlanningEntry[];
    setProjectHistoryPlanningEntries((currentEntries) => [
      ...data,
      ...currentEntries.filter((entry) => String(entry.projectId) !== String(projectId)),
    ]);
  }

  async function loadContentItems() {
    if (!activeUserId) return [];

    const res = await fetch(`/api/content-items?actorId=${encodeURIComponent(activeUserId)}`, { cache: "no-store" });

    if (!res.ok) {
      setErrorMessage("Content-Inhalte konnten nicht geladen werden.");
      return [];
    }

    const data = (await res.json()) as ContentItem[];
    setContentItems(data);
    return data;
  }

  async function loadIdeaPosts(showNotifications = false) {
    if (!activeUserId) return [];
    const res = await fetch(`/api/idea-store?userId=${activeUserId}`, { cache: "no-store" });
    if (!res.ok) {
      setIdeaStoreError("Ideen-Feed konnte nicht geladen werden.");
      return [];
    }
    const data = (await res.json()) as IdeaStorePost[];
    setIdeaPosts(data);
    if (showNotifications) await loadNotifications(true);
    return data;
  }

  async function loadNewsFeed() {
    if (!activeUserId) {
      setIsNewsFeedLoading(false);
      return [];
    }

    setIsNewsFeedLoading(true);
    try {
      const res = await fetch(`/api/news-feed?actorId=${encodeURIComponent(activeUserId)}`, {
        cache: "no-store",
        credentials: "same-origin",
      });

      if (!res.ok) {
        setNewsFeedError("News-Feed konnte nicht geladen werden.");
        return [];
      }

      const data = (await res.json()) as NewsFeedPost[];
      setNewsFeedPosts(data);
      setNewsFeedError("");
      return data;
    } catch {
      setNewsFeedError("News-Feed konnte nicht geladen werden.");
      return [];
    } finally {
      setIsNewsFeedLoading(false);
    }
  }

  async function loadEmployeeDocuments(userId = personalAssessmentTargetUserId) {
    if (!userId) return;
    setEmployeeDocumentsLoading(true);
    setEmployeeDocumentError("");
    const response = await fetch(`/api/employee-documents?userId=${encodeURIComponent(userId)}`, {
      cache: "no-store",
      credentials: "same-origin",
    }).catch(() => null);
    if (!response?.ok) {
      const payload = response ? await response.json().catch(() => null) : null;
      setEmployeeDocumentError(payload?.error || "Personalunterlagen konnten nicht geladen werden.");
      setEmployeeDocuments([]);
      setEmployeeDocumentsLoading(false);
      return;
    }
    const payload = (await response.json()) as { documents?: EmployeeDocumentItem[] };
    setEmployeeDocuments(Array.isArray(payload.documents) ? payload.documents : []);
    setEmployeeDocumentsLoading(false);
  }

  async function uploadEmployeeDocument(category: EmployeeDocumentCategory, file: File | undefined) {
    if (!file || !personalAssessmentTargetUserId) return;
    setEmployeeDocumentBusyCategory(category);
    setEmployeeDocumentError("");
    setEmployeeDocumentMessage("");
    const formData = new FormData();
    formData.set("userId", personalAssessmentTargetUserId);
    formData.set("category", category);
    formData.set("file", file);
    const response = await fetch("/api/employee-documents", {
      method: "POST",
      body: formData,
      credentials: "same-origin",
    }).catch(() => null);
    if (!response?.ok) {
      const payload = response ? await response.json().catch(() => null) : null;
      setEmployeeDocumentError(payload?.error || "Dokument konnte nicht hochgeladen werden.");
      setEmployeeDocumentBusyCategory("");
      return;
    }
    setEmployeeDocumentMessage("Dokument wurde sicher hinterlegt.");
    await loadEmployeeDocuments(personalAssessmentTargetUserId);
    setEmployeeDocumentBusyCategory("");
  }

  async function deleteEmployeeDocument(document: EmployeeDocumentItem) {
    if (!window.confirm(`„${document.originalFileName}“ wirklich aus der aktiven Personalakte entfernen?`)) return;
    setEmployeeDocumentError("");
    setEmployeeDocumentMessage("");
    const response = await fetch(`/api/employee-documents/${encodeURIComponent(document.id)}`, {
      method: "DELETE",
      credentials: "same-origin",
    }).catch(() => null);
    if (!response?.ok) {
      const payload = response ? await response.json().catch(() => null) : null;
      setEmployeeDocumentError(payload?.error || "Dokument konnte nicht entfernt werden.");
      return;
    }
    setEmployeeDocumentMessage("Dokument wurde aus der aktiven Personalakte entfernt.");
    await loadEmployeeDocuments(personalAssessmentTargetUserId);
  }

  function resetNewsComposer() {
    setEditingNewsPostId("");
    setNewsDraftTitle("");
    setNewsDraftBody("");
    setNewsDraftAttachments([]);
    setNewsDraftPollQuestion("");
    setNewsDraftPollOptions(["", ""]);
    setNewsFeedError("");
  }

  function openNewsComposer() {
    resetNewsComposer();
    setIsNewsComposerOpen(true);
  }

  function openEditNewsComposer(post: NewsFeedPost) {
    setEditingNewsPostId(post.id);
    setNewsDraftTitle(post.title);
    setNewsDraftBody(post.body);
    setNewsDraftAttachments(post.attachments);
    setNewsDraftPollQuestion(post.pollQuestion);
    setNewsDraftPollOptions(
      post.pollOptions.length > 0 ? post.pollOptions.map((option) => option.label) : ["", ""]
    );
    setNewsFeedError("");
    setIsNewsComposerOpen(true);
  }

  async function addNewsAttachments(files: FileList | null) {
    if (!files) return;

    try {
      const nextAttachments = await Promise.all(
        Array.from(files).map(async (file, index) => {
          const attachment = await readProjectImageAttachment(file, `news-${Date.now()}-${index}`);
          if (!attachment.dataUrl) {
            throw new Error(`Bild "${file.name}" konnte nicht vorbereitet werden.`);
          }
          return {
            id: `${Date.now()}-${index}-${file.name}`,
            name: attachment.name,
            dataUrl: attachment.dataUrl,
            contentType: attachment.mimeType || file.type || "image/jpeg",
          };
        })
      );

      setNewsDraftAttachments((currentAttachments) => [...currentAttachments, ...nextAttachments]);
      setNewsFeedError("");
    } catch (error) {
      setNewsFeedError(error instanceof Error ? error.message : "Bild konnte nicht hochgeladen werden.");
    }
  }

  async function saveNewsPost() {
    if (!activeUserId) {
      setNewsFeedError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }

    if (!newsDraftTitle.trim()) {
      setNewsFeedError("Bitte einen Titel angeben.");
      return;
    }

    const pollOptions = newsDraftPollOptions.map((option) => option.trim()).filter(Boolean);
    if (newsDraftPollQuestion.trim() && pollOptions.length < 2) {
      setNewsFeedError("Eine Umfrage benötigt mindestens zwei Antwortoptionen.");
      return;
    }

    setIsNewsFeedSaving(true);
    setNewsFeedError("");

    try {
      const res = await fetch("/api/news-feed", {
        method: editingNewsPostId ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify({
          actorId: activeUserId,
          action: editingNewsPostId ? "update" : undefined,
          postId: editingNewsPostId || undefined,
          title: newsDraftTitle,
          body: newsDraftBody,
          visibility: "all",
          attachments: newsDraftAttachments,
          pollQuestion: newsDraftPollQuestion,
          pollOptions,
        }),
      });
      const data = await res.json().catch(() => null);

      if (!res.ok) {
        setNewsFeedError(data?.error ?? "Beitrag konnte nicht gespeichert werden.");
        return;
      }

      await loadNewsFeed();
      resetNewsComposer();
      setIsNewsComposerOpen(false);
    } finally {
      setIsNewsFeedSaving(false);
    }
  }

