  function getCatalogPackageSalesPrice(item: CatalogItem) {
    if (item.type !== "package") return item.salesPrice;
    if (item.salesPrice > 0) return item.salesPrice;
    return item.packageItems.reduce(
      (sum, packageItem) => sum + getPackageComponentSalesTotal(packageItem),
      0
    );
  }

  function getCatalogPackagePurchasePrice(item: CatalogItem) {
    if (item.type === "service") return (item.purchasePrice * item.planningMinutesPerUnit) / 60;
    if (item.type !== "package") return item.purchasePrice;
    return item.packageItems.reduce(
      (sum, packageItem) => sum + getPackageComponentPurchaseTotal(packageItem),
      0
    );
  }

  function getCatalogMaterialPurchasePrice(item: CatalogItem) {
    if (item.type === "service") return 0;
    if (item.type !== "package") return item.purchasePrice;
    return item.packageItems
      .filter((packageItem) => packageItem.componentType === "article")
      .reduce((sum, packageItem) => sum + getPackageComponentPurchaseTotal(packageItem), 0);
  }

  function getCatalogLaborPurchasePrice(item: CatalogItem) {
    if (item.type === "service") return (item.purchasePrice * item.planningMinutesPerUnit) / 60;
    if (item.type !== "package") return 0;
    return item.packageItems
      .filter((packageItem) => packageItem.componentType === "service")
      .reduce((sum, packageItem) => sum + getPackageComponentPurchaseTotal(packageItem), 0);
  }

  function getDefaultLaborCostRateKeyForCatalogItem(item: Pick<CatalogItem, "type" | "defaultPlanningBoard" | "defaultPlanningGroup">) {
    if (item.type !== "service") return "";
    if (item.defaultPlanningBoard === "OK immocare") {
      return item.defaultPlanningGroup === "TZK" ? "ok-immocare-tzk" : "ok-immocare-vzk";
    }
    return "ok-solutions";
  }

  function createOfferLineFromCatalogItem(item: CatalogItem): OfferLineDraft {
    return {
      id: crypto.randomUUID(),
      catalogItemId: item.id,
      catalogType: item.type,
      isLaborPosition: item.isLaborPosition,
      quantity: 1,
      unit: item.unit || "Stk",
      title: item.name,
      description: item.description || item.category || "",
      unitPrice: getCatalogPackageSalesPrice(item),
      discountPercent: 0,
      laborCostRateKey: item.laborCostRateKey || getDefaultLaborCostRateKeyForCatalogItem(item),
      laborCostRate: roundCurrencyValue(getCatalogLaborPurchasePrice(item)),
      vatRate: item.vatRate || 19,
      laborItems: [],
    };
  }

  function createEmptyOfferLine(vatRate = 19): OfferLineDraft {
    return {
      id: crypto.randomUUID(),
      catalogItemId: "",
      catalogType: "",
      quantity: 1,
      unit: "Stk",
      title: "",
      description: "",
      unitPrice: 0,
      discountPercent: 0,
      laborCostRateKey: "",
      laborCostRate: 0,
      vatRate,
      laborItems: [],
    };
  }

  function getOfferLineTypeLabel(type: CatalogItemType | "") {
    if (type === "service") return "Leistung";
    if (type === "package") return "Paket";
    if (type === "article") return "Material";
    return "Freie Position";
  }

  function canPlanOfferLineLabor(line: OfferLineDraft) {
    return line.catalogType === "service" || line.catalogType === "package";
  }

  function getDefaultBranchAllocations(board: PlanningBoardCompany = "OK solutions"): BranchAllocations {
    return board === "OK immocare"
      ? { okSolutions: 0, okImmocare: 100, okImmocareVzk: 100, okImmocareTzk: 0 }
      : { okSolutions: 100, okImmocare: 0, okImmocareVzk: 0, okImmocareTzk: 0 };
  }

  function normalizeBranchAllocations(
    value?: Partial<BranchAllocations> | null,
    fallbackBoard: PlanningBoardCompany = "OK solutions"
  ): BranchAllocations {
    const fallback = getDefaultBranchAllocations(fallbackBoard);
    const legacyImmocare = Number(value?.okImmocare ?? fallback.okImmocare) || 0;
    const rawVzk =
      value?.okImmocareVzk !== undefined
        ? Number(value.okImmocareVzk) || 0
        : fallbackBoard === "OK immocare"
          ? legacyImmocare
          : 0;
    const rawTzk = value?.okImmocareTzk !== undefined ? Number(value.okImmocareTzk) || 0 : 0;
    const okImmocareVzk = clampPercent(rawVzk);
    const okImmocareTzk = clampPercent(rawTzk);
    const okImmocare = clampPercent(okImmocareVzk + okImmocareTzk);
    return {
      okSolutions: clampPercent(Number(value?.okSolutions ?? fallback.okSolutions) || 0),
      okImmocare,
      okImmocareVzk,
      okImmocareTzk,
    };
  }

  function getBranchAllocationTotal(allocations: BranchAllocations) {
    return (
      Number(allocations.okSolutions || 0) +
      Number(allocations.okImmocareVzk || 0) +
      Number(allocations.okImmocareTzk || 0)
    );
  }

  function createBoundedBranchAllocations(
    current: BranchAllocations,
    key: "okSolutions" | "okImmocareVzk" | "okImmocareTzk",
    rawValue: number
  ): BranchAllocations {
    const value = clampPercent(rawValue);
    const next = normalizeBranchAllocations(current);
    const otherKeys = (["okSolutions", "okImmocareVzk", "okImmocareTzk"] as const).filter((item) => item !== key);

    next[key] = value;
    let overflow = getBranchAllocationTotal(next) - 100;
    if (overflow > 0) {
      [...otherKeys].reverse().forEach((item) => {
        if (overflow <= 0) return;
        const currentValue = Number(next[item] || 0);
        const reduction = Math.min(currentValue, overflow);
        next[item] = clampPercent(currentValue - reduction);
        overflow -= reduction;
      });
    }

    next.okImmocare = clampPercent(Number(next.okImmocareVzk || 0) + Number(next.okImmocareTzk || 0));
    return next;
  }

  function getUserPlanningBoard(user: UserOption) {
    return user.planningBoard === "OK immocare" ? "OK immocare" : "OK solutions";
  }

  function getUserBranchAllocations(user: UserOption) {
    return normalizeBranchAllocations(user.branchAllocations, getUserPlanningBoard(user));
  }

  function getBranchAllocationShare(user: UserOption, board: PlanningBoardCompany) {
    const allocations = getUserBranchAllocations(user);
    return (board === "OK immocare" ? allocations.okImmocare : allocations.okSolutions) / 100;
  }

  function getLaborCostAllocationShare(user: UserOption, board: PlanningBoardCompany, planningGroup = "") {
    const allocations = getUserBranchAllocations(user);
    if (board === "OK solutions") return allocations.okSolutions / 100;
    if (planningGroup === "TZK") return (allocations.okImmocareTzk ?? 0) / 100;
    if (planningGroup === "VZK") return (allocations.okImmocareVzk ?? allocations.okImmocare) / 100;
    return allocations.okImmocare / 100;
  }

  function getPrimaryBranchFromAllocations(allocations: BranchAllocations): PlanningBoardCompany {
    return allocations.okImmocare > allocations.okSolutions ? "OK immocare" : "OK solutions";
  }

  function formatBranchAllocations(user: UserOption) {
    const allocations = getUserBranchAllocations(user);
    const parts = [
      allocations.okSolutions > 0 ? `OK solutions ${formatHours(allocations.okSolutions)}%` : "",
      (allocations.okImmocareVzk ?? 0) > 0 ? `OK immocare VZK ${formatHours(allocations.okImmocareVzk ?? 0)}%` : "",
      (allocations.okImmocareTzk ?? 0) > 0 ? `OK immocare TZK ${formatHours(allocations.okImmocareTzk ?? 0)}%` : "",
    ].filter(Boolean);
    return parts.join(" / ") || "-";
  }

  function getEmployeeHourlyCostRate(userId: string) {
    const cost = employeeCostCalculations[userId];
    return cost ? getEmployeeCostMetrics(cost).hourlyCost : 0;
  }

  function getAverageLaborCostRate(board: PlanningBoardCompany, planningGroup = "") {
    const boardUsers = users.filter(
      (user) =>
        user.isActive &&
        user.includeInLaborCostRate !== false &&
        getLaborCostAllocationShare(user, board, planningGroup) > 0
    );
    const allocationTotal = boardUsers.reduce((sum, user) => sum + getLaborCostAllocationShare(user, board, planningGroup), 0);
    const total = boardUsers.reduce(
      (sum, user) => sum + getEmployeeHourlyCostRate(user.id) * getLaborCostAllocationShare(user, board, planningGroup),
      0
    );
    return {
      board,
      planningGroup,
      label: planningGroup ? `${board} ${planningGroup}` : board,
      users: boardUsers,
      total,
      allocationTotal,
      average: boardUsers.length > 0 ? total / boardUsers.length : 0,
      count: boardUsers.length,
    };
  }

  function getLaborCostRateOptions() {
    return [
      { key: "ok-solutions", label: "OK solutions", rate: getAverageLaborCostRate("OK solutions").average },
      { key: "ok-immocare-vzk", label: "OK immocare VZK", rate: getAverageLaborCostRate("OK immocare", "VZK").average },
      { key: "ok-immocare-tzk", label: "OK immocare TZK", rate: getAverageLaborCostRate("OK immocare", "TZK").average },
    ];
  }

  function getLaborCostRateOption(key: string) {
    return getLaborCostRateOptions().find((option) => option.key === key) ?? null;
  }

  function getProjectLaborCostBoard(project?: HeroProjectPreview | null): PlanningBoardCompany {
    return getProjectCompany(project);
  }

  function getOfferDraftLaborCostRate() {
    const selectedProject =
      selectedProjectFile || heroProjects.find((project) => project.id === upsellOfferProjectId) || null;
    const board = getProjectLaborCostBoard(selectedProject);
    return getAverageLaborCostRate(board);
  }

  function createOfferLaborItem(user?: UserOption): OfferLineLaborDraft {
    const targetUser = user ?? users.find((item) => item.isActive);
    const hourlyCostRate = targetUser ? getEmployeeHourlyCostRate(targetUser.id) : 0;
    return {
      id: crypto.randomUUID(),
      userId: targetUser?.id ?? "",
      employeeName: targetUser?.name ?? "",
      plannedHours: 0,
      hourlyCostRate,
      totalCost: 0,
    };
  }

  function getOfferLineLaborHours(line: OfferLineDraft) {
    return line.laborItems.reduce((sum, labor) => sum + Number(labor.plannedHours || 0), 0);
  }

  function clampOfferLaborItems(
    laborItems: OfferLineLaborDraft[],
    maxHours: number
  ): OfferLineLaborDraft[] {
    let remainingHours = Math.max(Number(maxHours || 0), 0);
    return laborItems.map((labor) => {
      const plannedHours = Math.min(Math.max(Number(labor.plannedHours || 0), 0), remainingHours);
      remainingHours -= plannedHours;
      return {
        ...labor,
        plannedHours,
        totalCost: plannedHours * Number(labor.hourlyCostRate || 0),
      };
    });
  }

  function updateOfferLine(index: number, patch: Partial<OfferLineDraft>) {
    setOfferDraft((current) => ({
      ...current,
      lines: current.lines.map((line, lineIndex) => {
        if (lineIndex !== index) return line;
        const selectedItem = patch.catalogItemId
          ? catalogItems.find((item) => item.id === patch.catalogItemId)
          : null;
        if (selectedItem) {
          const nextQuantity = patch.quantity ?? line.quantity;
          const nextLine = createOfferLineFromCatalogItem(selectedItem);
          return {
            ...line,
            ...nextLine,
            id: line.id,
            quantity: nextQuantity,
            laborItems:
              nextLine.catalogType === "service" || nextLine.catalogType === "package"
                ? clampOfferLaborItems(line.laborItems, nextQuantity)
                : [],
          };
        }
      const nextLine = { ...line, ...patch };
        if (Object.prototype.hasOwnProperty.call(patch, "unit")) {
          nextLine.unit = normalizeUnit(String(patch.unit ?? ""));
        }
        if (Object.prototype.hasOwnProperty.call(patch, "quantity")) {
          return {
            ...nextLine,
            laborItems: canPlanOfferLineLabor(nextLine)
              ? clampOfferLaborItems(nextLine.laborItems, nextLine.quantity)
              : [],
          };
        }
        return nextLine;
      }),
    }));
  }

  function updateOfferLineLabor(
    lineIndex: number,
    laborId: string,
    patch: Partial<OfferLineLaborDraft>
  ) {
    setOfferDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) => {
        if (currentLineIndex !== lineIndex) return line;
        const maxHours = Math.max(Number(line.quantity || 0), 0);

        return {
          ...line,
          laborItems: line.laborItems.map((labor) => {
            if (labor.id !== laborId) return labor;
            const selectedUser = patch.userId
              ? users.find((user) => user.id === patch.userId)
              : null;
            const otherHours = line.laborItems
              .filter((item) => item.id !== laborId)
              .reduce((sum, item) => sum + Number(item.plannedHours || 0), 0);
            const availableHours = Math.max(maxHours - otherHours, 0);
            const plannedHours = Math.min(
              Math.max(Number(patch.plannedHours ?? labor.plannedHours), 0),
              availableHours
            );
            const hourlyCostRate = patch.userId
              ? getEmployeeHourlyCostRate(patch.userId)
              : patch.hourlyCostRate ?? labor.hourlyCostRate;

            return {
              ...labor,
              ...patch,
              employeeName: selectedUser?.name ?? patch.employeeName ?? labor.employeeName,
              plannedHours,
              hourlyCostRate,
              totalCost: plannedHours * hourlyCostRate,
            };
          }),
        };
      }),
    }));
  }

  function addOfferLineLabor(lineIndex: number) {
    setOfferDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) =>
        currentLineIndex === lineIndex && getOfferLineLaborHours(line) < Number(line.quantity || 0)
          ? { ...line, laborItems: [...line.laborItems, createOfferLaborItem()] }
          : line
      ),
    }));
  }

  function removeOfferLineLabor(lineIndex: number, laborId: string) {
    setOfferDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) =>
        currentLineIndex === lineIndex
          ? { ...line, laborItems: line.laborItems.filter((labor) => labor.id !== laborId) }
          : line
      ),
    }));
  }

  function selectOfferCatalogItem(index: number, itemId: string) {
    updateOfferLine(index, { catalogItemId: itemId });
    const lineId = offerDraft.lines[index]?.id;
    if (lineId) {
      setOfferLineSearchTerms((current) => ({ ...current, [lineId]: "" }));
    }
    setOpenOfferLinePickerId("");
  }

  function removeOfferLine(index: number) {
    setOfferDraft((current) => ({
      ...current,
      lines: current.lines.filter((_, lineIndex) => lineIndex !== index),
    }));
    const lineId = offerDraft.lines[index]?.id;
    if (lineId) {
      setOfferLineSearchTerms((current) => {
        const next = { ...current };
        delete next[lineId];
        return next;
      });
    }
  }

  function addOfferLine() {
    setOfferDraft((current) => ({
      ...current,
      lines: [...current.lines, createEmptyOfferLine(current.vatRate)],
    }));
  }

  function closeOfferModal() {
    setIsOfferModalOpen(false);
    setEditingOfferId("");
    setUpsellOfferProjectId("");
    setIsOfferExecutionMonthPickerOpen(false);
    setIsOfferExecutionEndMonthPickerOpen(false);
  }

  function openOfferModal(project: HeroProjectPreview, options: { fromUpsell?: boolean; asAddendum?: boolean } = {}) {
    const isImmocare =
      (project.projectType ?? "").toLowerCase().includes("immocare") ||
      (project.projectNumber ?? "").toLowerCase().startsWith("oki");
    const addressParts = (project.address || "").split(",").map((part) => part.trim()).filter(Boolean);
    const isRecurringProject = getProjectKind(project).startsWith("Dauer");
    const recurringStartMonth = options.asAddendum
      ? `${reportNow.getFullYear()}-${String(reportNow.getMonth() + 1).padStart(2, "0")}`
      : project.projectRuntimeFrom
        ? project.projectRuntimeFrom.slice(0, 7)
        : "";
    const recurringEndMonth = project.projectRuntimeUntil ? project.projectRuntimeUntil.slice(0, 7) : "";
    setOfferDraft({
      ...emptyOfferDraft,
      offerType: options.asAddendum ? "addendum" : "base",
      plannedExecutionMonth: isRecurringProject ? recurringStartMonth : "",
      plannedExecutionEndMonth: isRecurringProject ? recurringEndMonth : "",
      company: isImmocare ? "OK immocare" : "OK solutions",
      customerName: project.customer || "",
      customerStreet: addressParts[0] || project.address || "",
      customerCity: addressParts.slice(1).join(", "),
      internalContactName: activeUser?.name || "Christian Eid",
      internalEmail: activeUser?.email || "",
      lines: [createEmptyOfferLine(emptyOfferDraft.vatRate)],
    });
    setOfferError("");
    setEditingOfferId("");
    setOfferPreviewDataUrl("");
    setOfferLineSearchTerms({});
    setOpenOfferLinePickerId("");
    setIsOfferExecutionMonthPickerOpen(false);
    setIsOfferExecutionEndMonthPickerOpen(false);
    setOfferExecutionMonthPickerYear(
      recurringStartMonth ? Number(recurringStartMonth.slice(0, 4)) : reportNow.getFullYear()
    );
    setOfferExecutionEndMonthPickerYear(
      recurringEndMonth ? Number(recurringEndMonth.slice(0, 4)) : reportNow.getFullYear()
    );
    setUpsellOfferProjectId(options.fromUpsell ? project.id : "");
    setIsOfferModalOpen(true);
  }

  function openEditOfferModal(offer: OfferItem) {
    const offerExecutionYear = Number((offer.plannedExecutionMonth || "").slice(0, 4));
    const isRecurringProject = selectedProjectFile ? getProjectKind(selectedProjectFile).startsWith("Dauer") : false;
    setOfferDraft({
      company: offer.company,
      offerType: offer.offerType === "addendum" ? "addendum" : "base",
      addendumMode:
        offer.addendumMode === "replacement" || offer.addendumMode === "reduction"
          ? offer.addendumMode
          : "addition",
      plannedExecutionEndMonth:
        offer.plannedExecutionEndMonth ||
        (isRecurringProject && selectedProjectFile?.projectRuntimeUntil
          ? selectedProjectFile.projectRuntimeUntil.slice(0, 7)
          : ""),
      parentOfferId: offer.parentOfferId || "",
      customerName: offer.customerName,
      customerStreet: offer.customerStreet,
      customerCity: offer.customerCity,
      contactName: offer.contactName,
      internalContactName: offer.internalContactName,
      internalPhone: offer.internalPhone,
      internalEmail: offer.internalEmail,
      plannedExecutionMonth: offer.plannedExecutionMonth || "",
      introText: offer.introText || emptyOfferDraft.introText,
      closingText: offer.closingText || emptyOfferDraft.closingText,
      vatRate: offer.vatRate || 19,
      discountPercent: offer.discountPercent ?? 0,
      lines:
        offer.lines.length > 0
          ? offer.lines.map((line) => ({
              id: line.id || crypto.randomUUID(),
              catalogItemId: line.catalogItemId,
              catalogType: line.catalogType,
              quantity: line.quantity,
              unit: line.unit,
              title: line.title,
              description: line.description,
              unitPrice: line.unitPrice,
              discountPercent: line.discountPercent ?? 0,
              laborCostRateKey: line.laborCostRateKey || "",
              laborCostRate: roundCurrencyValue(line.laborCostRate || 0),
              vatRate: line.vatRate,
              laborItems: (line.laborItems ?? []).map((labor) => ({
                id: labor.id || crypto.randomUUID(),
                userId: labor.userId,
                employeeName: labor.employeeName,
                plannedHours: labor.plannedHours,
                hourlyCostRate: labor.hourlyCostRate,
                totalCost: labor.totalCost,
              })),
            }))
          : [createEmptyOfferLine(offer.vatRate || 19)],
    });
    setEditingOfferId(offer.id);
    setOfferError("");
    setOfferPreviewDataUrl(offer.pdfAvailable ? getOfferPdfUrl(offer.id) : "");
    setOfferLineSearchTerms({});
    setOpenOfferLinePickerId("");
    setIsOfferExecutionMonthPickerOpen(false);
    setIsOfferExecutionEndMonthPickerOpen(false);
    setOfferExecutionMonthPickerYear(Number.isFinite(offerExecutionYear) ? offerExecutionYear : reportNow.getFullYear());
    setOfferExecutionEndMonthPickerYear(
      Number.isFinite(Number((offer.plannedExecutionEndMonth || selectedProjectFile?.projectRuntimeUntil || "").slice(0, 4)))
        ? Number((offer.plannedExecutionEndMonth || selectedProjectFile?.projectRuntimeUntil || "").slice(0, 4))
        : reportNow.getFullYear()
    );
    setUpsellOfferProjectId("");
    setIsOfferModalOpen(true);
  }

  async function generateOfferPreview() {
    if (!selectedProjectFile) return;
    setIsGeneratingOfferPreview(true);
    setOfferError("");

    const editingOffer = offers.find((offer) => offer.id === editingOfferId);
    const offerPayload = {
      ...offerDraft,
      lines: offerDraft.lines.map((line) => ({
        ...line,
        laborCostRate: roundCurrencyValue(line.laborCostRate || 0),
        laborItems: [],
      })),
    };
    const res = await fetch("/api/offers", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        ...offerPayload,
        offerNumber: editingOffer?.offerNumber || "VORSCHAU",
        projectId: selectedProjectFile.id,
        projectNumber: selectedProjectFile.projectNumber || selectedProjectFile.id,
        projectTitle: selectedProjectFile.title,
      }),
    });

    setIsGeneratingOfferPreview(false);

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setOfferError(data?.error ?? "Vorschau konnte nicht erstellt werden.");
      return;
    }

    const data = (await res.json()) as { pdfDataUrl: string };
    setOfferPreviewDataUrl(data.pdfDataUrl);
  }

  async function saveOffer(options: { asDraft?: boolean } = {}) {
    if (!selectedProjectFile) return;
    const saveAsDraft = Boolean(options.asDraft);
    const validationMessage = saveAsDraft ? "" : getOfferSaveValidationMessage();
    if (validationMessage) {
      setOfferError(validationMessage);
      return;
    }
    setIsSavingOffer(true);
    setOfferError("");
    const editingOfferBeforeSave = offers.find((offer) => offer.id === editingOfferId);
    const shouldCreateFinalOfferFollowUp =
      !saveAsDraft && (!editingOfferId || editingOfferBeforeSave?.status === "Entwurf");
    const offerPayload = {
      ...offerDraft,
      lines: offerDraft.lines.map((line) => ({
        ...line,
        laborCostRate: roundCurrencyValue(line.laborCostRate || 0),
        laborItems: [],
      })),
    };

    const res = await fetch("/api/offers", {
      method: editingOfferId ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: editingOfferId,
        actorId: activeUserId,
        ...offerPayload,
        saveAsDraft,
        projectId: selectedProjectFile.id,
        projectNumber: selectedProjectFile.projectNumber || selectedProjectFile.id,
        projectTitle: selectedProjectFile.title,
      }),
    });

    setIsSavingOffer(false);

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setOfferError(data?.error ?? "Angebot konnte nicht erstellt werden.");
      return;
    }

    const savedOffer = (await res.json()) as OfferItem;
    setOffers((currentOffers) => [savedOffer, ...currentOffers.filter((offer) => offer.id !== savedOffer.id)]);
    await loadOfferHistory(selectedProjectFile.id);
    await addProjectLogbookEntry(
      selectedProjectFile.id,
      "Angebot",
      `${saveAsDraft ? "Angebotsentwurf gespeichert" : editingOfferId ? "Angebot geändert" : "Angebot erstellt"}: ${savedOffer.offerNumber} (${formatMoney(
        savedOffer.grossTotal
      )} brutto).`
    );
    const linkedPotential =
      shouldCreateFinalOfferFollowUp && upsellOfferProjectId === selectedProjectFile.id
        ? projectPotentials.find(
        (item) => item.projectId === selectedProjectFile.id && ["open", "follow_up"].includes(item.status)
          ) ?? null
        : null;

    if (shouldCreateFinalOfferFollowUp) {
      await createOfferFollowUpTask(savedOffer, selectedProjectFile, linkedPotential);
    }

    if (saveAsDraft) {
      await confirmAndApplyProjectStatus({
        project: selectedProjectFile,
        nextStatus: "Angebot",
        reason: `Angebotsentwurf ${savedOffer.offerNumber} gespeichert`,
        question: `Angebotsentwurf ${savedOffer.offerNumber} wurde gespeichert. Soll der Projektstatus auf „Angebotserstellung“ gesetzt werden?`,
      });
    } else if (shouldCreateFinalOfferFollowUp) {
      await confirmAndApplyProjectStatus({
        project: selectedProjectFile,
        nextStatus: "Warten auf Kunde",
        reason: `Finales Angebot ${savedOffer.offerNumber} erstellt`,
        question: `Finales Angebot ${savedOffer.offerNumber} wurde erstellt. Soll der Projektstatus auf „Warten auf Kunde“ gesetzt werden?`,
      });
    }

    if (linkedPotential) {
      await addProjectLogbookEntry(
        selectedProjectFile.id,
        "Zusatzverkauf: Angebot erstellt",
        `Aus dem erkannten Zusatzverkauf wurde Angebot ${savedOffer.offerNumber} erstellt.`
      );
      setUpsellOfferProjectId("");
    }
    setSelectedProjectDocumentType(savedOffer.offerType === "addendum" ? "Angebote: Nachtragsangebote" : "Angebote");
    setProjectFileTab("documents");
    setIsOfferModalOpen(false);
    setEditingOfferId("");
    if (!saveAsDraft && savedOffer.pdfAvailable) {
      window.open(getOfferPdfUrl(savedOffer.id), "_blank");
    }
  }

  function getOfferSaveValidationMessage() {
    if (!offerDraft.plannedExecutionMonth) {
      return "Bitte geplanten Ausführungsmonat auswählen.";
    }
    const isRecurringOfferProject = selectedProjectFile ? getProjectKind(selectedProjectFile).startsWith("Dauer") : false;
    if (isRecurringOfferProject && !offerDraft.plannedExecutionEndMonth) {
      return "Bitte beim Dauerläufer den Ausführungszeitraum bis auswählen.";
    }
    if (
      offerDraft.plannedExecutionEndMonth &&
      offerDraft.plannedExecutionEndMonth < offerDraft.plannedExecutionMonth
    ) {
      return "Bitte beim Ausfuehrungszeitraum ein Enddatum nach dem Startmonat waehlen.";
    }
    if (offerDraft.lines.length === 0) {
      return "Bitte mindestens eine Position hinzufügen.";
    }
    const incompleteLineIndex = offerDraft.lines.findIndex((line) => !line.title.trim() && !line.catalogItemId);
    if (incompleteLineIndex >= 0) {
      return `Bitte Position ${incompleteLineIndex + 1} auswählen oder eine Bezeichnung eintragen.`;
    }
    const invalidQuantityIndex = offerDraft.lines.findIndex((line) => Number(line.quantity || 0) <= 0);
    if (invalidQuantityIndex >= 0) {
      return `Bitte bei Position ${invalidQuantityIndex + 1} eine Menge größer 0 eintragen.`;
    }
    const invalidPriceIndex = offerDraft.lines.findIndex((line) => Number(line.unitPrice || 0) < 0);
    if (invalidPriceIndex >= 0) {
      return `Bitte bei Position ${invalidPriceIndex + 1} keinen negativen Einzelpreis eintragen.`;
    }
    return "";
  }

  async function deleteOffer(offer: OfferItem) {
    if (!selectedProjectFile) return;
    const confirmed = window.confirm(`Angebot ${offer.offerNumber} wirklich löschen?`);
    if (!confirmed) return;

    const res = await fetch("/api/offers", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: offer.id,
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Angebot konnte nicht gelöscht werden.");
      return;
    }

    setOffers((currentOffers) => currentOffers.filter((currentOffer) => currentOffer.id !== offer.id));
    await loadOfferHistory(selectedProjectFile.id);
    await addProjectLogbookEntry(
      selectedProjectFile.id,
      "Angebot",
      `Angebot gelöscht: ${offer.offerNumber}.`
    );
  }

  function openMarkOfferLostDialog(offer: OfferItem) {
    if (isLostOffer(offer) || offer.status === "Entwurf") return;
    if (isWonOffer(offer)) {
      setErrorMessage(`Angebot ${offer.offerNumber} ist bereits gewonnen und kann nicht als verloren markiert werden.`);
      return;
    }
    const linkedInvoice = invoices.find(
      (invoice) =>
        !isDeletedInvoice(invoice) &&
        invoice.status !== "Entwurf" &&
        (invoice.sourceOfferId === offer.id || invoice.sourceOfferNumber === offer.offerNumber)
    );
    if (linkedInvoice) {
      setErrorMessage(
        `Angebot ${offer.offerNumber} ist bereits mit Rechnung ${getInvoiceDisplayNumber(linkedInvoice)} verknüpft und kann nicht als verloren markiert werden.`
      );
      return;
    }
    setLostOfferDraft({
      offerId: offer.id,
      reason: "",
      note: "",
      error: "",
      isSaving: false,
    });
  }

  async function saveLostOfferStatus() {
    if (!selectedProjectFile || !lostOfferDraft) return;
    const offer = offers.find((item) => item.id === lostOfferDraft.offerId);
    if (!offer) return;
    const reason = lostOfferDraft.reason.trim();
    const note = lostOfferDraft.note.trim();

    if (!reason) {
      setLostOfferDraft((current) =>
        current ? { ...current, error: "Bitte einen Grund angeben, warum das Angebot verloren ist." } : current
      );
      return;
    }
    if (!note) {
      setLostOfferDraft((current) =>
        current ? { ...current, error: "Bitte einen Kommentar zum verlorenen Angebot angeben." } : current
      );
      return;
    }

    setLostOfferDraft((current) => (current ? { ...current, error: "", isSaving: true } : current));
    const success = await markOfferLost(offer, reason, note, selectedProjectFile.id, (message) => {
      setLostOfferDraft((current) =>
        current ? { ...current, isSaving: false, error: message } : current
      );
    });
    if (success) setLostOfferDraft(null);
  }

  async function markOfferLost(
    offer: OfferItem,
    reason: string,
    note: string,
    projectId = offer.projectId,
    onError?: (message: string) => void
  ) {
    const res = await fetch("/api/offers", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: offer.id,
        action: "markLost",
        lostReason: reason,
        lostNote: note,
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      const message = data?.error ?? "Angebot konnte nicht als verloren markiert werden.";
      if (onError) onError(message);
      else setErrorMessage(message);
      return false;
    }

    const savedOffer = (await res.json()) as OfferItem;
    setOffers((currentOffers) => [savedOffer, ...currentOffers.filter((currentOffer) => currentOffer.id !== savedOffer.id)]);
    if (projectId) {
      await loadOfferHistory(projectId);
      await addProjectLogbookEntry(
        projectId,
        "Angebot verloren",
        `Angebot ${savedOffer.offerNumber} wurde als verloren markiert. Grund: ${reason}. Kommentar: ${note}.`
      );
    }
    return true;
  }

  async function markOfferWon(offer: OfferItem, reason: string, projectId = offer.projectId) {
    const res = await fetch("/api/offers", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: offer.id,
        action: "markWon",
        wonReason: reason,
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Angebot konnte nicht als gewonnen markiert werden.");
      return false;
    }

    const savedOffer = (await res.json()) as OfferItem;
    setOffers((currentOffers) => [savedOffer, ...currentOffers.filter((currentOffer) => currentOffer.id !== savedOffer.id)]);
    if (projectId) {
      await loadOfferHistory(projectId);
      await addProjectLogbookEntry(
        projectId,
        "Angebot gewonnen",
        `Angebot ${savedOffer.offerNumber} wurde als gewonnen markiert. Grund: ${reason}.`
      );
    }
    return true;
  }

  async function restoreLostOfferStatus(offer: OfferItem) {
    if (!selectedProjectFile || !isLostOffer(offer)) return;
    const confirmed = window.confirm(
      `Angebot ${offer.offerNumber} wieder aktivieren? Es erscheint danach wieder in Planung und Forecast.`
    );
    if (!confirmed) return;

    const res = await fetch("/api/offers", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: offer.id,
        action: "restoreLost",
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Angebot konnte nicht wieder aktiviert werden.");
      return;
    }

    const savedOffer = (await res.json()) as OfferItem;
    setOffers((currentOffers) => [savedOffer, ...currentOffers.filter((currentOffer) => currentOffer.id !== savedOffer.id)]);
    await loadOfferHistory(selectedProjectFile.id);
    await addProjectLogbookEntry(
      selectedProjectFile.id,
      "Angebot wieder aktiviert",
      `Angebot ${savedOffer.offerNumber} wurde wieder als aktives Angebot markiert.`
    );
  }

  function openFreeInvoiceModal(project: HeroProjectPreview) {
    const isImmocare = getProjectCompany(project) === "OK immocare";
    const addressParts = (project.address || "").split(",").map((part) => part.trim()).filter(Boolean);
    const firstItem = catalogItems.find((item) => item.isActive);
    const serviceDate = getProjectServiceDateSuggestion(project);
    const paymentTermDays = getInvoicePaymentTermDaysForProject(project);
    setInvoiceDraft({
      ...emptyInvoiceDraft,
      company: isImmocare ? "OK immocare" : "OK solutions",
      customerName: project.customer || "",
      customerStreet: addressParts[0] || project.address || "",
      customerCity: addressParts.slice(1).join(", "),
      internalContactName: activeUser?.name || "Christian Eid",
      internalEmail: activeUser?.email || "",
      plannedExecutionMonth: serviceDate.slice(0, 7),
      serviceDate,
      paymentTermDays,
      dueDate: getInvoiceDueDate(serviceDate, paymentTermDays),
      introText: "wir stellen Ihnen folgende Leistungen in Rechnung.",
      closingText: "Bitte überweisen Sie den Rechnungsbetrag innerhalb der vereinbarten Zahlungsfrist.",
      lines: firstItem ? [createOfferLineFromCatalogItem(firstItem)] : [],
    });
    setEditingInvoiceId("");
    setInvoicePreviewDataUrl("");
    setInvoiceError("");
    setInvoiceLineSearchTerms({});
    setOpenInvoiceLinePickerId("");
    setInvoiceStampEntryIds([]);
    setInvoiceBillableStampEntryIds([]);
    setIsInvoiceSourcePickerOpen(false);
    setIsInvoiceModalOpen(true);
  }

  function invoiceToAutoBillingTemplate(invoice: InvoiceItem): AutoBillingTemplate {
    return {
      company: invoice.company,
      customerName: invoice.customerName,
      customerStreet: invoice.customerStreet,
      customerCity: invoice.customerCity,
      contactName: invoice.contactName,
      internalContactName: invoice.internalContactName || activeUser?.name || "",
      internalPhone: invoice.internalPhone,
      internalEmail: invoice.internalEmail,
      introText: invoice.introText,
      closingText: invoice.closingText,
      vatRate: invoice.vatRate || 19,
      discountPercent: invoice.discountPercent || 0,
      lines: invoice.lines.map((line) => ({
        ...line,
        id: crypto.randomUUID(),
        laborItems: (line.laborItems ?? []).map((labor) => ({ ...labor, id: crypto.randomUUID() })),
      })),
    };
  }

  function isUsableAutoBillingInvoice(invoice: InvoiceItem) {
    return !isDeletedInvoice(invoice) && !["Entwurf", "Storniert", "Stornorechnung"].includes(invoice.status);
  }

  function getProjectInvoicesSorted(projectId: string) {
    return invoices
      .filter((invoice) => invoice.projectId === projectId && isUsableAutoBillingInvoice(invoice))
      .sort((first, second) => parseAppDateTime(second.createdAt).getTime() - parseAppDateTime(first.createdAt).getTime());
  }

  function saveAutoBillingProjectPatch(project: HeroProjectPreview, patch: Partial<HeroProjectPreview>) {
    const nextProject = { ...project, ...patch };
    setHeroProjects((currentProjects) =>
      currentProjects.map((currentProject) => (currentProject.id === project.id ? nextProject : currentProject))
    );
    if (selectedProjectFileId === project.id) {
      setSelectedProjectFileId(project.id);
    }
    return persistProject(nextProject).then((savedProject) => {
      setHeroProjects((currentProjects) =>
        currentProjects.map((currentProject) => (currentProject.id === savedProject.id ? savedProject : currentProject))
      );
      setBatchBillingMessage("Automatische Abrechnung gespeichert.");
      return savedProject;
    });
  }

  async function saveProjectForecastSettings(project: HeroProjectPreview) {
    if (!isRecurringProject(project)) return;
    const forecastNetAmount = projectForecastDraft.forecastNetAmount.trim();
    const forecastBillingType = projectForecastDraft.forecastBillingType;
    const parsedAmount = parseReportAmount(forecastNetAmount);

    if (forecastNetAmount && parsedAmount <= 0) {
      setProjectForecastError("Bitte einen gültigen Forecastbetrag netto eintragen.");
      return;
    }

    const nextProject = {
      ...project,
      forecastBillingType: forecastNetAmount ? forecastBillingType : "",
      forecastNetAmount,
    };

    setIsSavingProjectForecast(true);
    setProjectForecastError("");
    setProjectForecastMessage("");

    try {
      const savedProject = await persistProject(nextProject);
      setHeroProjects((currentProjects) =>
        currentProjects.map((currentProject) => (currentProject.id === savedProject.id ? savedProject : currentProject))
      );
      await addProjectLogbookEntry(
        savedProject.id,
        "Forecast",
        forecastNetAmount
          ? `Forecast-Einstellung gespeichert: ${forecastNetAmount} EUR netto (${forecastBillingType}).`
          : "Forecast-Einstellung entfernt."
      );
      setProjectForecastMessage("Forecast-Einstellung gespeichert.");
    } catch (error) {
      setProjectForecastError(error instanceof Error ? error.message : "Forecast-Einstellung konnte nicht gespeichert werden.");
    } finally {
      setIsSavingProjectForecast(false);
    }
  }

  function getProjectInvoiceMonth(invoice: InvoiceItem) {
    return (invoice.serviceDate || "").slice(0, 7) || invoice.plannedExecutionMonth || getReportMonthKey(invoice.createdAt);
  }

  function getPreviousMonthKey(monthKey: string) {
    const [year, month] = monthKey.split("-").map(Number);
    if (!year || !month) return "";
    const previousMonthDate = new Date(year, month - 2, 1, 12);
    return `${previousMonthDate.getFullYear()}-${String(previousMonthDate.getMonth() + 1).padStart(2, "0")}`;
  }

  function getNextMonthKey(monthKey: string) {
    const [year, month] = monthKey.split("-").map(Number);
    if (!year || !month) return "";
    const nextMonthDate = new Date(year, month, 1, 12);
    return `${nextMonthDate.getFullYear()}-${String(nextMonthDate.getMonth() + 1).padStart(2, "0")}`;
  }

  function getLastDayOfMonthKey(monthKey: string) {
    const [year, month] = monthKey.split("-").map(Number);
    if (!year || !month) return formatDateKey(new Date());
    return formatDateKey(new Date(year, month, 0, 12));
  }

  function getProjectServiceDateSuggestion(project: HeroProjectPreview, monthKey?: string) {
    const isRecurringProject = getProjectKind(project).startsWith("Dauer");
    if (isRecurringProject) {
      return getLastDayOfMonthKey(monthKey || projectComparisonMonth || formatDateKey(new Date()).slice(0, 7));
    }

    const projectStampDates = stampEntries
      .filter((entry) => entry.mode === "project" && entry.projectId === project.id && !entry.deletedAt)
      .map((entry) => normalizeDateKeyValue(entry.date))
      .filter(Boolean)
      .sort();
    const lastStampDate = projectStampDates.at(-1);
    if (lastStampDate) return lastStampDate;

    const projectPlanningDates = planningEntries
      .filter((entry) => entry.projectId === project.id && !entry.deletedAt)
      .map((entry) => normalizeDateKeyValue(entry.date))
      .filter(Boolean)
      .sort();
    return projectPlanningDates.at(-1) || formatDateKey(new Date());
  }

  function getInvoiceServiceDateLabel(value: string) {
    return formatProjectDate(value);
  }

  function getInvoicePaymentTermDaysForProject(project: HeroProjectPreview) {
    const relatedContact = contacts.find((contact) => contact.id === project.contactId || contact.id === project.addressContactId);
    const paymentTermDays = Number(relatedContact?.paymentTermDays ?? 14);
    return Number.isFinite(paymentTermDays) ? Math.min(Math.max(Math.round(paymentTermDays), 0), 365) : 14;
  }

  function getInvoiceDueDate(serviceDate: string, paymentTermDays: number) {
    const dateKey = normalizeDateKeyValue(serviceDate);
    if (!dateKey) return "";
    const [year, month, day] = dateKey.split("-").map(Number);
    const date = new Date(year, month - 1, day, 12);
    date.setDate(date.getDate() + paymentTermDays);
    return formatDateKey(date);
  }

  function getProjectLogEntryMonthForProcess(entry: ProjectLogbookEntry) {
    if (/^\d{4}-\d{2}$/.test(entry.projectMonth || "")) return entry.projectMonth || "";
    const rawDate = entry.date || "";
    const isoMatch = rawDate.match(/^(\d{4})-(\d{2})/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}`;
    const germanMatch = rawDate.match(/^(\d{2})\.(\d{2})\.(\d{4}|\d{2})/);
    if (germanMatch) {
      const year = germanMatch[3].length === 2 ? `20${germanMatch[3]}` : germanMatch[3];
      return `${year}-${germanMatch[2]}`;
    }

    const parsedDate = parseAppDateTime(rawDate);
    return Number.isNaN(parsedDate.getTime()) ? "" : formatDateKey(parsedDate).slice(0, 7);
  }

  function getProjectLogEntryDayForProcess(entry: Pick<ProjectLogbookEntry, "date">) {
    const rawDate = entry.date || "";
    const isoMatch = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    const germanMatch = rawDate.match(/^(\d{2})\.(\d{2})\.(\d{4}|\d{2})/);
    if (germanMatch) {
      const year = germanMatch[3].length === 2 ? `20${germanMatch[3]}` : germanMatch[3];
      return `${year}-${germanMatch[2]}-${germanMatch[1]}`;
    }

    const parsedDate = parseAppDateTime(rawDate);
    return Number.isNaN(parsedDate.getTime()) ? "" : formatDateKey(parsedDate);
  }

  function shouldUseProjectMonthForProcess(project: HeroProjectPreview) {
    return isRecurringProjectKindValue(getProjectKind(project));
  }

  function getProjectProcessLogEntries(project: HeroProjectPreview, category: string, monthKey: string, dayKey = "") {
    const useMonth = shouldUseProjectMonthForProcess(project);
    const monthEntries = projectLogbookEntries.filter((entry) => {
      if (String(entry.projectId) !== String(project.id)) return false;
      if (entry.title !== category) return false;
      return !useMonth || getProjectLogEntryMonthForProcess(entry) === monthKey;
    });
    if (!dayKey || !isWinterServiceProject(project)) return monthEntries;

    const dayEntries = monthEntries.filter((entry) => getProjectLogEntryDayForProcess(entry) === dayKey);
    const hasDayAttachments = dayEntries.some((entry) => entry.attachments.length > 0);
    return hasDayAttachments ? dayEntries : monthEntries;
  }

  function getProjectProcessAttachmentCount(
    project: HeroProjectPreview,
    title: string,
    attachmentType: LogbookAttachment["type"],
    monthKey: string,
    dayKey = ""
  ) {
    return getProjectProcessLogEntries(project, title, monthKey, dayKey).reduce(
      (sum, entry) => sum + entry.attachments.filter((attachment) => attachment.type === attachmentType).length,
      0
    );
  }

  function getActivityReportProcessEntries(project: HeroProjectPreview, monthKey: string, dayKey = "") {
    return getProjectProcessLogEntries(project, "Dokumente: Tätigkeitsberichte", monthKey, dayKey).filter((entry) =>
      entry.attachments.some((attachment) => attachment.type === "Dokument")
    );
  }

  function getActivityReportLinkText(entry: ProjectLogbookEntry) {
    return [
      entry.text,
      ...entry.attachments.map((attachment) => attachment.name),
    ]
      .join(" ")
      .toLowerCase();
  }

  function getMatchingActivityReportCount(project: HeroProjectPreview, monthKey: string, sourceOfferNumber?: string, contextKey?: string, dayKey = "") {
    const reportEntries = getActivityReportProcessEntries(project, monthKey, dayKey);
    if (contextKey) {
      const contextToken = contextKey.trim().toLowerCase();
      return reportEntries
        .filter((entry) => getActivityReportLinkText(entry).includes(contextToken))
        .reduce(
          (sum, entry) => sum + entry.attachments.filter((attachment) => attachment.type === "Dokument").length,
          0
        );
    }

    if (shouldUseProjectMonthForProcess(project) || !sourceOfferNumber) {
      return reportEntries.reduce(
        (sum, entry) => sum + entry.attachments.filter((attachment) => attachment.type === "Dokument").length,
        0
      );
    }

    const sourceToken = sourceOfferNumber.trim().toLowerCase();
    const linkedReportEntries = reportEntries.filter((entry) => getActivityReportLinkText(entry).includes(sourceToken));
    const fallbackEntries = linkedReportEntries.length > 0 ? linkedReportEntries : reportEntries.length === 1 ? reportEntries : [];

    return fallbackEntries.reduce(
      (sum, entry) => sum + entry.attachments.filter((attachment) => attachment.type === "Dokument").length,
      0
    );
  }

  function getActivityReportImageKeys(project: HeroProjectPreview, category: "Vorherbilder" | "Nachherbilder", monthKey: string, dayKey = "") {
    return getProjectProcessLogEntries(project, `Bilder: ${category}`, monthKey, dayKey).flatMap((entry) =>
      entry.attachments.flatMap((attachment, attachmentIndex) =>
        attachment.type === "Bild" && attachment.dataUrl
          ? [`${entry.id}:${attachmentIndex}:${attachment.name}`]
          : []
      )
    );
  }

  async function createActivityReportForProject(
    project: HeroProjectPreview,
    monthKey: string,
    options: { sourceOfferNumber?: string; contextKey?: string; contextLabel?: string; dayKey?: string } = {}
  ) {
    const reportContextKey = options.contextKey || (options.sourceOfferNumber ? `Angebot:${options.sourceOfferNumber}` : "");
    const reportContextLabel = options.contextLabel || (options.sourceOfferNumber ? `Angebot ${options.sourceOfferNumber}` : "");
    const res = await fetch("/api/activity-reports", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        actorId: activeUserId,
        projectId: project.id,
        month: shouldUseProjectMonthForProcess(project) ? monthKey : "",
        beforeImageKeys: getActivityReportImageKeys(project, "Vorherbilder", monthKey, options.dayKey),
        afterImageKeys: getActivityReportImageKeys(project, "Nachherbilder", monthKey, options.dayKey),
        reportContextKey,
        reportContextLabel,
      }),
    });

    const data = await res.json().catch(() => null);
    if (!res.ok) {
      throw new Error(data?.error ?? "Tätigkeitsbericht konnte nicht erstellt werden.");
    }

    const savedEntry = data as ProjectLogbookEntry;
    setProjectLogbookEntries((currentEntries) => [
      savedEntry,
      ...currentEntries.filter((entry) => entry.id !== savedEntry.id),
    ]);
    void notifyProjectBillingReady(project, monthKey);
    return savedEntry;
  }

  function getProjectBillingReadyRecipients(project: HeroProjectPreview) {
    const responsibility = getEffectiveProjectResponsibility(project);
    const responsibleUser = getUserByDisplayName(responsibility.name);
    if (responsibleUser) return [responsibleUser.id];

    return users
      .filter((user) => user.isActive && (user.role === "ADMIN" || user.role === "GESCHAEFTSFUEHRER"))
      .map((user) => user.id);
  }

  function getActiveProjectDeputyName(project?: HeroProjectPreview | null, dateKey = formatDateKey(new Date())) {
    if (!project?.deputyName) return "";
    const fromKey = normalizeDateKeyValue(project.deputyFrom || "");
    const untilKey = normalizeDateKeyValue(project.deputyUntil || "");
    if (fromKey && dateKey < fromKey) return "";
    if (untilKey && dateKey > untilKey) return "";
    return project.deputyName;
  }

  function getActiveAbsenceDeputyName(project?: HeroProjectPreview | null, dateKey = formatDateKey(new Date())) {
    if (!project?.responsibleName) return "";
    const responsibleName = normalizeReportPersonValue(project.responsibleName);
    const responsibleUser = users.find((user) => user.isActive && normalizeReportPersonValue(user.name) === responsibleName);
    if (!responsibleUser) return "";

    const activeAbsence = absences.find(
      (absence) =>
        absence.userId === responsibleUser.id &&
        absence.status === "genehmigt" &&
        absence.date === dateKey &&
        Boolean(absence.representativeUserId)
    );
    if (!activeAbsence) return "";

    const representativeUser = users.find((user) => user.id === activeAbsence.representativeUserId && user.isActive);
    return representativeUser?.name || activeAbsence.representativeName || "";
  }

  function getEffectiveProjectResponsibility(project?: HeroProjectPreview | null, dateKey = formatDateKey(new Date())) {
    const absenceDeputyName = getActiveAbsenceDeputyName(project, dateKey);
    if (absenceDeputyName) {
      return {
        label: "Abwesenheitsvertretung aktiv",
        name: absenceDeputyName,
        state: "absenceDeputy" as const,
      };
    }

    const projectDeputyName = getActiveProjectDeputyName(project, dateKey);
    if (projectDeputyName) {
      return {
        label: "Vertretung aktiv",
        name: projectDeputyName,
        state: "projectDeputy" as const,
      };
    }

    return {
      label: "Projektverantwortlicher",
      name: project?.responsibleName || activeUser?.name || "Christian Eid",
      state: "responsible" as const,
    };
  }

  function getUserByDisplayName(name?: string | null) {
    const normalizedName = normalizeReportPersonValue(name || "");
    if (!normalizedName) return null;
    return users.find((user) => user.isActive && normalizeReportPersonValue(user.name) === normalizedName) ?? null;
  }

  function getBillingReadyEscalationRecipients(project: HeroProjectPreview) {
    const responsibility = getEffectiveProjectResponsibility(project);
    const responsibleUser = getUserByDisplayName(responsibility.name);
    const planningGroup = normalizeReportPersonValue(responsibleUser?.planningGroup || "");
    const managementUserIds = users
      .filter((user) => user.isActive && (user.role === "ADMIN" || user.role === "GESCHAEFTSFUEHRER"))
      .map((user) => user.id);
    const leadershipUserIds = users
      .filter((user) => {
        if (!user.isActive || user.role !== "FUEHRUNGSKRAFT") return false;
        if (responsibleUser && user.id === responsibleUser.id) return false;
        if (!planningGroup) return true;
        return normalizeReportPersonValue(user.planningGroup || "") === planningGroup;
      })
      .map((user) => user.id);

    return {
      leadershipUserIds: leadershipUserIds.length > 0 ? leadershipUserIds : managementUserIds,
      managementUserIds,
    };
  }

  function getOneTimeProjectBillingReadyState(
    project: HeroProjectPreview,
    monthKey: string,
    options: { assumeFinalInspection?: boolean } = {}
  ) {
    if (isRecurringProjectKindValue(getProjectKind(project))) {
      return { ready: false, reason: "Dauerlaeufer werden monatsbezogen bewertet." };
    }

    const hasFinalInvoice = invoices.some(
      (invoice) =>
        String(invoice.projectId) === String(project.id) &&
        !isDeletedInvoice(invoice) &&
        invoice.status !== "Entwurf"
    );
    if (hasFinalInvoice) return { ready: false, reason: "Rechnung ist bereits erstellt." };

    const finalInspectionCount = options.assumeFinalInspection
      ? Math.max(1, getProjectProcessAttachmentCount(project, "Dokumente: Endkontrolle", "Dokument", monthKey))
      : getProjectProcessAttachmentCount(project, "Dokumente: Endkontrolle", "Dokument", monthKey);
    if (finalInspectionCount === 0) return { ready: false, reason: "Endkontrolle fehlt." };

    if (!isImmocareProject(project)) return { ready: true, reason: "" };

    const beforeImageCount = getProjectProcessAttachmentCount(project, "Bilder: Vorherbilder", "Bild", monthKey);
    const afterImageCount = getProjectProcessAttachmentCount(project, "Bilder: Nachherbilder", "Bild", monthKey);
    if (beforeImageCount === 0) return { ready: false, reason: "Vorherbild fehlt." };
    if (afterImageCount === 0) return { ready: false, reason: "Nachherbild fehlt." };

    return { ready: true, reason: "" };
  }

  function getRecurringProjectBillingReadyState(
    project: HeroProjectPreview,
    monthKey: string,
    options: { assumeFinalInspection?: boolean } = {}
  ) {
    if (!isRecurringProjectKindValue(getProjectKind(project))) {
      return { ready: false, reason: "Einmalprojekte werden projektbezogen bewertet." };
    }
    if (isWinterServiceProject(project)) {
      return { ready: false, reason: "Winterdienst laeuft einsatzbezogen." };
    }
    if (!isProjectActiveInBillingMonth(project, monthKey)) {
      return { ready: false, reason: "Projekt ist in diesem Monat nicht aktiv." };
    }

    const hasFinalMonthlyInvoice = invoices.some(
      (invoice) =>
        String(invoice.projectId) === String(project.id) &&
        !isDeletedInvoice(invoice) &&
        invoice.status !== "Entwurf" &&
        getProjectInvoiceMonth(invoice) === monthKey
    );
    if (hasFinalMonthlyInvoice) return { ready: false, reason: "Monatsrechnung ist bereits erstellt." };

    const finalInspectionCount = options.assumeFinalInspection
      ? Math.max(1, getProjectProcessAttachmentCount(project, "Dokumente: Endkontrolle", "Dokument", monthKey))
      : getProjectProcessAttachmentCount(project, "Dokumente: Endkontrolle", "Dokument", monthKey);
    if (finalInspectionCount === 0) return { ready: false, reason: "Endkontrolle fehlt." };

    if (!isImmocareProject(project)) return { ready: true, reason: "" };

    const beforeImageCount = getProjectProcessAttachmentCount(project, "Bilder: Vorherbilder", "Bild", monthKey);
    const afterImageCount = getProjectProcessAttachmentCount(project, "Bilder: Nachherbilder", "Bild", monthKey);
    if (beforeImageCount === 0) return { ready: false, reason: "Vorherbild fehlt." };
    if (afterImageCount === 0) return { ready: false, reason: "Nachherbild fehlt." };

    return { ready: true, reason: "" };
  }

  function getProjectBillingReadyState(
    project: HeroProjectPreview,
    monthKey: string,
    options: { assumeFinalInspection?: boolean } = {}
  ) {
    return isRecurringProjectKindValue(getProjectKind(project))
      ? getRecurringProjectBillingReadyState(project, monthKey, options)
      : getOneTimeProjectBillingReadyState(project, monthKey, options);
  }

  function getProjectBillingEvidenceIssues(project: HeroProjectPreview, monthKey: string, invoice?: InvoiceItem) {
    const issues: string[] = [];
    const finalInspectionCount = getProjectProcessAttachmentCount(project, "Dokumente: Endkontrolle", "Dokument", monthKey);
    if (finalInspectionCount === 0) issues.push("Endkontrolle");

    if (isImmocareProject(project)) {
      const beforeImageCount = getProjectProcessAttachmentCount(project, "Bilder: Vorherbilder", "Bild", monthKey);
      const afterImageCount = getProjectProcessAttachmentCount(project, "Bilder: Nachherbilder", "Bild", monthKey);
      if (beforeImageCount === 0) issues.push("Vorherbild");
      if (afterImageCount === 0) issues.push("Nachherbild");
    }

    if (invoice) {
      const activityReportCount = getMatchingActivityReportCount(project, monthKey, invoice.sourceOfferNumber);
      if (activityReportCount === 0) issues.push("Tätigkeitsbericht");
    }

    return issues;
  }

  function getProjectFinalInvoices(project: HeroProjectPreview) {
    return invoices
      .filter((invoice) => String(invoice.projectId) === String(project.id) && isFinanciallyActiveInvoice(invoice))
      .sort((first, second) => parseAppDateTime(second.createdAt).getTime() - parseAppDateTime(first.createdAt).getTime());
  }

  function getProjectPipelineNextBillingStep(project: HeroProjectPreview) {
    const normalizedStatus = normalizeProjectPipelineStatus(project.status);
    if (
      normalizedStatus !== "Abrechnungsprüfung" &&
      normalizedStatus !== "Zur Abrechnung bereit" &&
      normalizedStatus !== "Abgeschlossen"
    ) {
      return "";
    }

    const monthKey = projectComparisonMonth || getCurrentMonthKey();
    const finalInvoice = getProjectFinalInvoices(project)[0];
    const evidenceIssues = getProjectBillingEvidenceIssues(
      project,
      finalInvoice ? getProjectInvoiceMonth(finalInvoice) : monthKey,
      finalInvoice
    );
    if (finalInvoice && evidenceIssues.length > 0) {
      return `Rechnung vorhanden - Nachweise fehlen: ${evidenceIssues.join(", ")}.`;
    }

    const state = getProjectBillingReadyState(project, monthKey);
    if (state.ready) return "Rechnung erstellen.";

    if (state.reason === "Rechnung ist bereits erstellt.") {
      return isRecurringProjectKindValue(getProjectKind(project))
        ? "Rechnung vorhanden - Folgemonatsstatus prüfen."
        : "Rechnung vorhanden - Projekt abschließen.";
    }
    if (state.reason === "Endkontrolle fehlt.") return "Endkontrolle erfassen.";
    if (state.reason === "Vorherbild fehlt.") return "Vorherbild hochladen.";
    if (state.reason === "Nachherbild fehlt.") return "Nachherbild hochladen.";

    return state.reason || "Prüfung offen.";
  }

  function getConfirmedProjectPlannedHoursForMonth(projectId: string, monthKey: string) {
    return planningEntries
      .filter(
        (entry) =>
          !entry.deletedAt &&
          entry.projectId === projectId &&
          entry.approvalStatus === "confirmed" &&
          entry.date.startsWith(monthKey)
      )
      .reduce((sum, entry) => sum + Number(entry.durationMinutes || 0) / 60, 0);
  }

  function getProjectRequiredPlanningHoursForMonth(project: HeroProjectPreview, monthKey: string) {
    if (!isProjectBudgetDueForPlanningMonth(project, monthKey)) return 0;
    const allocatedHours = getProjectBudgetAllocationHours(project, monthKey);
    if (allocatedHours > 0) return allocatedHours;
    return project.timeBudgetEnabled ? parseHoursInput(project.timeBudgetHours) : 0;
  }

  function getProjectPostInvoiceStatus(project: HeroProjectPreview, invoiceMonth: string) {
    if (!isRecurringProjectKindValue(getProjectKind(project))) return "Abgeschlossen";

    const nextMonthKey = getNextMonthKey(invoiceMonth);
    if (!nextMonthKey) return "Zur Planung bereit";

    const requiredPlanningHours = getProjectRequiredPlanningHoursForMonth(project, nextMonthKey);
    const confirmedPlannedHours = getConfirmedProjectPlannedHoursForMonth(project.id, nextMonthKey);
    if (requiredPlanningHours > 0) {
      return confirmedPlannedHours + 0.01 >= requiredPlanningHours ? "Umsetzung" : "Zur Planung bereit";
    }

    return confirmedPlannedHours > 0 ? "Umsetzung" : "Zur Planung bereit";
  }

  async function applyProjectStatusAfterInvoice(project: HeroProjectPreview, invoice: InvoiceItem) {
    const invoiceMonth =
      getProjectInvoiceMonth(invoice) ||
      invoice.serviceDate.slice(0, 7) ||
      invoice.plannedExecutionMonth ||
      getCurrentMonthKey();
    const nextStatus = getProjectPostInvoiceStatus(project, invoiceMonth);
    const isRecurring = isRecurringProjectKindValue(getProjectKind(project));
    const reason = isRecurring
      ? `Rechnung ${invoice.invoiceNumber} für ${formatMonthLabel(invoiceMonth)} fakturiert; Folgemonat ${formatMonthLabel(
          getNextMonthKey(invoiceMonth) || invoiceMonth
        )} geprüft.`
      : `Rechnung ${invoice.invoiceNumber} fakturiert.`;

    return applyProjectStatus({
      project,
      nextStatus,
      reason,
      logPrefix: "Projektstatus nach Rechnung geändert",
    });
  }

  async function syncProjectStatusesAfterExistingInvoices() {
    if (!activeUserId) return;

    const projectsToSync = heroProjects
      .map((project) => {
        const normalizedStatus = normalizeProjectPipelineStatus(project.status);
        if (normalizedStatus !== "Abrechnungsprüfung" && normalizedStatus !== "Zur Abrechnung bereit") {
          return null;
        }

        const finalInvoice = getProjectFinalInvoices(project)[0];
        if (!finalInvoice) return null;

        const syncKey = `${project.id}:${finalInvoice.id}:${project.status}`;
        if (syncedPostInvoiceProjectKeysRef.current.has(syncKey)) return null;

        return { finalInvoice, project, syncKey };
      })
      .filter((entry): entry is { finalInvoice: InvoiceItem; project: HeroProjectPreview; syncKey: string } =>
        Boolean(entry)
      );

    for (const entry of projectsToSync) {
      syncedPostInvoiceProjectKeysRef.current.add(entry.syncKey);
      await applyProjectStatusAfterInvoice(entry.project, entry.finalInvoice);
    }
  }

  async function notifyProjectBillingReady(
    project?: HeroProjectPreview | null,
    monthKey = getCurrentMonthKey(),
    options: { assumeFinalInspection?: boolean } = {}
  ) {
    if (!activeUserId) return false;
    if (!project) return false;

    const isRecurring = isRecurringProjectKindValue(getProjectKind(project));
    const state = getProjectBillingReadyState(project, monthKey, options);
    if (!state.ready) return false;

    const recipientUserIds = getProjectBillingReadyRecipients(project);
    if (recipientUserIds.length === 0) return false;
    const escalationRecipients = getBillingReadyEscalationRecipients(project);

    const projectLabel = [project.projectNumber, project.title].filter(Boolean).join(" | ") || "Projekt ohne Nummer";
    const subject = isRecurring
      ? `Dauerläufer abrechnungsbereit: ${formatMonthLabel(monthKey)}`
      : "Projekt abrechnungsbereit";
    const body = isRecurring
      ? `${projectLabel}: Für ${formatMonthLabel(monthKey)} sind die Pflichtnachweise vorhanden. Bitte Monatsrechnung erstellen oder prüfen.`
      : `${projectLabel}: Alle Pflichtnachweise sind vorhanden. Bitte Rechnung erstellen oder prüfen.`;
    const res = await fetch("/api/notifications", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        userIds: recipientUserIds,
        subject,
        body,
        linkTarget: "project",
        linkTargetId: project.id,
        linkLabel: "Projekt öffnen",
        escalations: [
          {
            afterBusinessDays: 1.5,
            userIds: escalationRecipients.leadershipUserIds,
            subjectPrefix: "Führungskraft",
            bodySuffix: "Der Hinweis ist seit mindestens 1,5 Arbeitstagen offen.",
          },
          {
            afterBusinessDays: 2.5,
            userIds: escalationRecipients.managementUserIds,
            subjectPrefix: "Geschäftsführung",
            bodySuffix: "Der Hinweis ist nach der Führungskraft-Eskalation weiterhin offen.",
          },
        ],
      }),
    });

    if (!res.ok) return false;
    await loadNotifications(true);
    return true;
  }

  async function scanBillingReadyNotifications(monthKey = getCurrentMonthKey()) {
    const candidates = heroProjects.filter((project) => {
      if (isRecurringProjectKindValue(getProjectKind(project))) {
        return getRecurringProjectBillingReadyState(project, monthKey).ready;
      }
      return getOneTimeProjectBillingReadyState(project, monthKey).ready;
    });

    for (const project of candidates) {
      await notifyProjectBillingReady(project, monthKey);
    }
  }

  async function runInvoiceProcessPreflight(
    project: HeroProjectPreview,
    draft: Pick<InvoiceDraft, "serviceDate" | "plannedExecutionMonth" | "sourceOfferNumber">,
    options: { skipConfirmation?: boolean; source: "create" | "finalize" }
  ) {
    if (options.skipConfirmation) return true;

    const invoiceMonth =
      (draft.serviceDate || "").slice(0, 7) ||
      draft.plannedExecutionMonth ||
      projectComparisonMonth ||
      formatDateKey(new Date()).slice(0, 7);
    const issues: string[] = [];
    const warnings: string[] = [];
    const beforeImageCount = getProjectProcessAttachmentCount(project, "Bilder: Vorherbilder", "Bild", invoiceMonth);
    const afterImageCount = getProjectProcessAttachmentCount(project, "Bilder: Nachherbilder", "Bild", invoiceMonth);
    const activityReportCount = getMatchingActivityReportCount(project, invoiceMonth, draft.sourceOfferNumber);
    const finalInspectionCount = getProjectProcessAttachmentCount(project, "Dokumente: Endkontrolle", "Dokument", invoiceMonth);
    const requiresActivityReport = isImmocareProject(project);
    const isWinterService = isWinterServiceProject(project);

    if (requiresActivityReport && activityReportCount === 0) {
      if (beforeImageCount > 0 && afterImageCount > 0) {
        const context =
          isWinterService
            ? "Für diesen Winterdienst-Einsatz sind Vorher- und Nachherbilder vorhanden."
            : isRecurringProjectKindValue(getProjectKind(project))
              ? `Für ${formatMonthLabel(invoiceMonth)} sind Vorher- und Nachherbilder vorhanden.`
              : draft.sourceOfferNumber
                ? `Für das Angebot ${draft.sourceOfferNumber} sind Vorher- und Nachherbilder vorhanden.`
                : "Vorher- und Nachherbilder sind vorhanden.";
        const createNow = window.confirm(
          `${context}\n\nEs gibt aber noch keinen Tätigkeitsbericht. Soll der Tätigkeitsbericht jetzt vor der Rechnung erstellt werden?`
        );
        if (createNow) {
          try {
            await createActivityReportForProject(project, invoiceMonth, { sourceOfferNumber: draft.sourceOfferNumber });
            setSelectedProjectFileId(project.id);
            setProjectComparisonMonth(invoiceMonth);
            setProjectFileTab("documents");
            setOpenProjectFileNavGroup("documents");
            setSelectedProjectDocumentType("Tätigkeitsberichte");
            setInvoiceError("Tätigkeitsbericht wurde erstellt. Bitte die Rechnung anschließend erneut fakturieren.");
          } catch (error) {
            setInvoiceError(error instanceof Error ? error.message : "Tätigkeitsbericht konnte nicht erstellt werden.");
          }
          return false;
        }

        warnings.push("Tätigkeitsbericht fehlt, obwohl Vorher- und Nachherbilder vorhanden sind.");
      } else {
        const missing = [
          beforeImageCount === 0 ? "Vorherbild" : "",
          afterImageCount === 0 ? "Nachherbild" : "",
        ].filter(Boolean);
        issues.push(`Tätigkeitsbericht fehlt; Voraussetzung fehlt: ${missing.join(" und ")}.`);
      }
    }

    if (finalInspectionCount === 0) {
      issues.push(
        isRecurringProjectKindValue(getProjectKind(project))
          ? `Endkontrolle für ${formatMonthLabel(invoiceMonth)} fehlt.`
          : "Endkontrolle fehlt."
      );
    }

    if (issues.length === 0 && warnings.length === 0) return true;

    const projectCompanyText = isImmocareProject(project) ? "OK immocare" : "OK solutions";
    const message = [
      "Vor dem Fakturieren ist der Prozess noch nicht vollständig:",
      "",
      ...issues.map((issue) => `- ${issue}`),
      ...warnings.map((warning) => `- ${warning}`),
      "",
      `Projektart: ${projectCompanyText}${isWinterService ? " / Winterdienst" : ""}`,
      "Soll die Rechnung trotzdem erstellt bzw. fakturiert werden?",
    ].join("\n");

    return window.confirm(message);
  }

  function isProjectActiveInBillingMonth(project: HeroProjectPreview, monthKey: string) {
    const startMonth = (project.autoBillingStartMonth || project.projectRuntimeFrom || "").slice(0, 7);
    const endMonth = (project.autoBillingEndMonth || project.projectRuntimeUntil || "").slice(0, 7);
    return (!startMonth || monthKey >= startMonth) && (!endMonth || monthKey <= endMonth);
  }

  function getAutoBillingComparison(project: HeroProjectPreview, monthKey: string) {
    const previousInvoices = getProjectInvoicesSorted(project.id)
      .filter((invoice) => {
        const invoiceMonth = getProjectInvoiceMonth(invoice);
        return invoiceMonth && invoiceMonth < monthKey;
      })
      .slice(0, 3);
    const amounts = previousInvoices.map((invoice) => roundCurrencyValue(invoice.netTotal));
    const stable = amounts.length >= 3 && amounts.every((amount) => amount === amounts[0]);

    return { previousInvoices, stable };
  }

  function getAutoBillingPreviousInvoice(project: HeroProjectPreview, monthKey: string) {
    const previousMonthKey = getPreviousMonthKey(monthKey);
    if (!previousMonthKey) return null;

    return (
      getProjectInvoicesSorted(project.id).find((invoice) => getProjectInvoiceMonth(invoice) === previousMonthKey) ??
      null
    );
  }

  function getAutoBillingTemplateForProject(project: HeroProjectPreview, monthKey: string): AutoBillingTemplate | null {
    const previousInvoice = getAutoBillingPreviousInvoice(project, monthKey);
    return previousInvoice ? invoiceToAutoBillingTemplate(previousInvoice) : null;
  }

  function buildAutoBillingInvoiceDraft(project: HeroProjectPreview, monthKey: string) {
    const isImmocare =
      (project.projectType ?? "").toLowerCase().includes("immocare") ||
      (project.projectNumber ?? "").toLowerCase().startsWith("oki");
    const addressParts = (project.address || "").split(",").map((part) => part.trim()).filter(Boolean);
    const previousInvoice = getAutoBillingPreviousInvoice(project, monthKey);
    const amount = previousInvoice ? roundCurrencyValue(previousInvoice.netTotal) : 0;
    const template = getAutoBillingTemplateForProject(project, monthKey);
    const monthLabel = formatMonthLabel(monthKey);
    const serviceDate = getLastDayOfMonthKey(monthKey);
    const paymentTermDays = getInvoicePaymentTermDaysForProject(project);
    const vatRate = template?.vatRate || 19;
    const lines =
      template?.lines && template.lines.length > 0
        ? template.lines.map((line) => ({ ...line, id: crypto.randomUUID(), laborItems: [] }))
        : [
            {
              ...createEmptyOfferLine(vatRate),
              title: `Monatliche Pauschale ${monthLabel}`,
              description: project.title,
              quantity: 1,
              unit: "Pauschale",
              unitPrice: amount,
            },
          ];

    return {
      ...emptyInvoiceDraft,
      company: template?.company || (isImmocare ? "OK immocare" : "OK solutions"),
      customerName: template?.customerName || project.customer || "",
      customerStreet: template?.customerStreet || addressParts[0] || project.address || "",
      customerCity: template?.customerCity || addressParts.slice(1).join(", "),
      contactName: template?.contactName || "",
      internalContactName: activeUser?.name || template?.internalContactName || "System",
      internalPhone: template?.internalPhone || "",
      internalEmail: activeUser?.email || template?.internalEmail || "",
      plannedExecutionMonth: monthKey,
      serviceDate,
      paymentTermDays,
      dueDate: getInvoiceDueDate(serviceDate, paymentTermDays),
      sourceOfferId: "",
      sourceOfferNumber: "",
      introText: template?.introText || `wir stellen Ihnen die monatliche Leistung fuer ${monthLabel} in Rechnung.`,
      closingText: template?.closingText || "Bitte ueberweisen Sie den Rechnungsbetrag innerhalb der vereinbarten Zahlungsfrist.",
      vatRate,
      discountPercent: template?.discountPercent || 0,
      lines,
    };
  }

  function openInvoiceFromOffer(offer: OfferItem) {
    if (!isActiveFinalOffer(offer)) {
      setErrorMessage("Nur aktive finale Angebote können als Rechnungsgrundlage verwendet werden.");
      return;
    }
    const project = heroProjects.find((item) => item.id === offer.projectId) || selectedProjectFile;
    const isRecurringProject = project ? getProjectKind(project).startsWith("Dauer") : false;
    const invoiceMonth = isRecurringProject
      ? projectComparisonMonth || offer.plannedExecutionMonth || formatDateKey(new Date()).slice(0, 7)
      : offer.plannedExecutionMonth || formatDateKey(new Date()).slice(0, 7);
    const serviceDate = project
      ? getProjectServiceDateSuggestion(project, invoiceMonth)
      : getLastDayOfMonthKey(invoiceMonth);
    const paymentTermDays = project ? getInvoicePaymentTermDaysForProject(project) : 14;
    setInvoiceDraft({
      company: offer.company,
      offerType: "base",
      addendumMode: "addition",
      plannedExecutionEndMonth: offer.plannedExecutionEndMonth || "",
      parentOfferId: "",
      customerName: offer.customerName,
      customerStreet: offer.customerStreet,
      customerCity: offer.customerCity,
      contactName: offer.contactName,
      internalContactName: activeUser?.name || offer.internalContactName,
      internalPhone: offer.internalPhone,
      internalEmail: activeUser?.email || offer.internalEmail,
      plannedExecutionMonth: invoiceMonth,
      serviceDate,
      paymentTermDays,
      dueDate: getInvoiceDueDate(serviceDate, paymentTermDays),
      sourceOfferId: offer.id,
      sourceOfferNumber: offer.offerNumber,
      discountPercent: offer.discountPercent ?? 0,
      introText: "wir stellen Ihnen folgende Leistungen aus dem Angebot in Rechnung.",
      closingText: "Bitte überweisen Sie den Rechnungsbetrag innerhalb der vereinbarten Zahlungsfrist.",
      vatRate: offer.vatRate || 19,
      lines: offer.lines.map((line) => ({
        id: crypto.randomUUID(),
        catalogItemId: line.catalogItemId,
        catalogType: line.catalogType,
        quantity: line.quantity,
        unit: line.unit,
        title: line.title,
        description: line.description,
        unitPrice: line.unitPrice,
        discountPercent: line.discountPercent ?? 0,
        vatRate: line.vatRate,
        laborItems: (line.laborItems ?? []).map((labor) => ({
          id: crypto.randomUUID(),
          userId: labor.userId,
          employeeName: labor.employeeName,
          plannedHours: labor.plannedHours,
          hourlyCostRate: labor.hourlyCostRate,
          totalCost: labor.totalCost,
        })),
      })),
    });
    setEditingInvoiceId("");
    setInvoicePreviewDataUrl("");
    setInvoiceError("");
    setInvoiceLineSearchTerms({});
    setOpenInvoiceLinePickerId("");
    setInvoiceStampEntryIds([]);
    setInvoiceBillableStampEntryIds([]);
    setIsInvoiceSourcePickerOpen(false);
    setIsInvoiceModalOpen(true);
  }

  function openEditInvoiceModal(invoice: InvoiceItem) {
    const invoiceProject =
      heroProjects.find((project) => project.id === invoice.projectId) ||
      (selectedProjectFile?.id === invoice.projectId ? selectedProjectFile : null);
    if (!invoiceProject) {
      setErrorMessage("Projekt zur Rechnung wurde nicht gefunden.");
      return;
    }
    setSelectedProjectFileId(invoiceProject.id);
    const correctedCompany =
      invoice.billingSource === "hourly-recurring" && invoiceProject ? getProjectCompany(invoiceProject) : invoice.company;
    setInvoiceDraft({
      company: correctedCompany,
      offerType: "base",
      addendumMode: "addition",
      plannedExecutionEndMonth: "",
      parentOfferId: "",
      customerName: invoice.customerName,
      customerStreet: invoice.customerStreet,
      customerCity: invoice.customerCity,
      contactName: invoice.contactName,
      internalContactName: invoice.internalContactName,
      internalPhone: invoice.internalPhone,
      internalEmail: invoice.internalEmail,
      plannedExecutionMonth: invoice.plannedExecutionMonth || "",
      serviceDate: invoice.serviceDate || "",
      paymentTermDays: invoice.paymentTermDays ?? 14,
      dueDate: invoice.dueDate || "",
      sourceOfferId: invoice.sourceOfferId || "",
      sourceOfferNumber: invoice.sourceOfferNumber || "",
      discountPercent: invoice.discountPercent ?? 0,
      introText: invoice.introText,
      closingText: invoice.closingText,
      vatRate: invoice.vatRate || 19,
      lines:
        invoice.lines.length > 0
          ? invoice.lines.map((line) => ({
              id: line.id || crypto.randomUUID(),
              catalogItemId: line.catalogItemId,
              catalogType: line.catalogType,
              quantity: line.quantity,
              unit: line.unit,
              title: line.title,
              description: line.description,
              unitPrice: line.unitPrice,
              discountPercent: line.discountPercent ?? 0,
              vatRate: line.vatRate,
              laborItems: (line.laborItems ?? []).map((labor) => ({
                id: labor.id || crypto.randomUUID(),
                userId: labor.userId,
                employeeName: labor.employeeName,
                plannedHours: labor.plannedHours,
                hourlyCostRate: labor.hourlyCostRate,
                totalCost: labor.totalCost,
              })),
            }))
          : [createEmptyOfferLine(invoice.vatRate || 19)],
    });
    setEditingInvoiceId(invoice.id);
    setInvoicePreviewDataUrl(invoice.pdfAvailable ? getInvoicePdfUrl(invoice.id) : "");
    setInvoiceError("");
    setInvoiceLineSearchTerms({});
    setOpenInvoiceLinePickerId("");
    const linkedStampEntryIds = stampEntries
      .filter((entry) => String(entry.invoiceId ?? "") === String(invoice.id) && !entry.deletedAt)
      .map((entry) => entry.id);
    setInvoiceStampEntryIds(linkedStampEntryIds);
    setInvoiceBillableStampEntryIds(linkedStampEntryIds);
    setIsInvoiceSourcePickerOpen(false);
    setIsInvoiceModalOpen(true);
  }

  function openInvoiceFlow(project: HeroProjectPreview) {
    const projectOffers = offers.filter((offer) => offer.projectId === project.id && offer.status !== "Entwurf");
    const invoicedOfferNumbers = new Set(
      invoices
        .filter((invoice) => invoice.projectId === project.id && !isDeletedInvoice(invoice))
        .map((invoice) => invoice.lines.map((line) => line.description).join(" "))
        .join(" ")
        .match(/ANG-\d+/g) ?? []
    );
    const openOffers = projectOffers.filter((offer) => !invoicedOfferNumbers.has(offer.offerNumber));

    if (openOffers.length > 0) {
      setIsInvoiceSourcePickerOpen(true);
      return;
    }

    openFreeInvoiceModal(project);
  }

  function updateInvoiceLine(index: number, patch: Partial<OfferLineDraft>) {
    setInvoiceDraft((current) => ({
      ...current,
      lines: current.lines.map((line, lineIndex) => {
        if (lineIndex !== index) return line;
        const selectedItem = patch.catalogItemId
          ? catalogItems.find((item) => item.id === patch.catalogItemId)
          : null;
        if (selectedItem) {
          const nextQuantity = patch.quantity ?? line.quantity;
          const nextLine = createOfferLineFromCatalogItem(selectedItem);
          return {
            ...line,
            ...nextLine,
            id: line.id,
            quantity: nextQuantity,
            laborItems: canPlanOfferLineLabor(nextLine) ? line.laborItems : [],
          };
        }
        const nextLine = { ...line, ...patch };
        if (Object.prototype.hasOwnProperty.call(patch, "unit")) {
          nextLine.unit = normalizeUnit(String(patch.unit ?? ""));
        }
        return nextLine;
      }),
    }));
  }

  function selectInvoiceCatalogItem(index: number, itemId: string) {
    if (itemId) {
      updateInvoiceLine(index, { catalogItemId: itemId });
    } else {
      updateInvoiceLine(index, {
        catalogItemId: "",
        catalogType: "",
        title: "",
        description: "",
        quantity: 1,
        unit: "Stk",
        unitPrice: 0,
        laborItems: [],
      });
    }
    const lineId = invoiceDraft.lines[index]?.id;
    if (lineId) {
      setInvoiceLineSearchTerms((current) => ({ ...current, [lineId]: "" }));
    }
    setOpenInvoiceLinePickerId("");
  }

  function updateInvoiceLineLabor(lineIndex: number, laborId: string, plannedHours: number) {
    setInvoiceDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) => {
        if (currentLineIndex !== lineIndex) return line;

        const laborItems = line.laborItems.map((labor) =>
          labor.id === laborId
            ? {
                ...labor,
                plannedHours: Math.max(0, plannedHours),
                totalCost: Math.max(0, plannedHours) * Number(labor.hourlyCostRate || 0),
              }
            : labor
        );
        const invoiceHours = laborItems.reduce((sum, labor) => sum + Number(labor.plannedHours || 0), 0);

        return {
          ...line,
          quantity: canPlanOfferLineLabor(line) ? invoiceHours : line.quantity,
          laborItems,
        };
      }),
    }));
  }

  function addInvoiceLineLabor(lineIndex: number) {
    const nextLabor = createOfferLaborItem();
    if (selectedProjectFile) {
      showInvoiceLaborStampNotice(invoiceDraft, selectedProjectFile.id, nextLabor, Number(nextLabor.plannedHours || 0));
    }
    setInvoiceDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) =>
        currentLineIndex === lineIndex && canPlanOfferLineLabor(line)
          ? { ...line, laborItems: [...line.laborItems, nextLabor] }
          : line
      ),
    }));
  }

  function removeInvoiceLineLabor(lineIndex: number, laborId: string) {
    setInvoiceDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) => {
        if (currentLineIndex !== lineIndex) return line;
        const laborItems = line.laborItems.filter((labor) => labor.id !== laborId);
        const invoiceHours = laborItems.reduce((sum, labor) => sum + Number(labor.plannedHours || 0), 0);
        return {
          ...line,
          quantity: canPlanOfferLineLabor(line) ? invoiceHours : line.quantity,
          laborItems,
        };
      }),
    }));
  }

  function addInvoiceLine() {
    const firstItem = catalogItems.find((item) => item.isActive);
    setInvoiceDraft((current) => ({
      ...current,
      lines: [
        ...current.lines,
        firstItem
          ? createOfferLineFromCatalogItem(firstItem)
          : {
              id: crypto.randomUUID(),
              catalogItemId: "",
              catalogType: "",
              quantity: 1,
              unit: "Stk",
              title: "",
              description: "",
              unitPrice: 0,
              vatRate: current.vatRate,
              laborItems: [],
            },
      ],
    }));
  }

  function removeInvoiceLine(index: number) {
    setInvoiceDraft((current) => ({
      ...current,
      lines: current.lines.filter((_, lineIndex) => lineIndex !== index),
    }));
    const lineId = invoiceDraft.lines[index]?.id;
    if (lineId) {
      setInvoiceLineSearchTerms((current) => {
        const next = { ...current };
        delete next[lineId];
        return next;
      });
    }
  }

  async function generateInvoicePreview() {
    if (!selectedProjectFile) return;
    setIsGeneratingInvoicePreview(true);
    setInvoiceError("");
    const editingInvoice = invoices.find((invoice) => invoice.id === editingInvoiceId);
    const res = await fetch("/api/invoices", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        ...invoiceDraft,
        invoiceNumber: editingInvoice?.invoiceNumber || "VORSCHAU",
        projectId: selectedProjectFile.id,
        projectNumber: selectedProjectFile.projectNumber || selectedProjectFile.id,
        projectTitle: selectedProjectFile.title,
      }),
    });
    setIsGeneratingInvoicePreview(false);

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setInvoiceError(data?.error ?? "Vorschau konnte nicht erstellt werden.");
      return;
    }

    const data = (await res.json()) as { pdfDataUrl: string };
    setInvoicePreviewDataUrl(data.pdfDataUrl);
  }

  function getUnbilledProjectStampEntries(projectId: string) {
    return stampEntries.filter(
      (entry) =>
        entry.mode === "project" &&
        String(entry.projectId) === String(projectId) &&
        !entry.deletedAt &&
        !String(entry.invoiceId ?? "").trim()
    );
  }

  function getProjectStampEntriesForMonth(projectId: string, monthKey: string) {
    return stampEntries.filter(
      (entry) =>
        entry.mode === "project" &&
        String(entry.projectId) === String(projectId) &&
        !entry.deletedAt &&
        normalizeDateKeyValue(entry.date).startsWith(monthKey)
    );
  }

  function getUnbilledProjectStampEntriesForMonth(projectId: string, monthKey: string) {
    return getProjectStampEntriesForMonth(projectId, monthKey).filter((entry) => !String(entry.invoiceId ?? "").trim());
  }

  function getInvoiceBillingMonthKey(draft: InvoiceDraft) {
    return draft.plannedExecutionMonth || normalizeDateKeyValue(draft.serviceDate).slice(0, 7);
  }

  function getRoundedBillableStampHours(entry: StampTimeEntry) {
    const rawHours = Math.max(0, Number(entry.durationMs || 0) / 3_600_000);
    if (rawHours <= 0) return 0;
    const roundingFactor = [0.25, 0.5, 1].includes(Number(hourlyBillingRoundingFactorHours))
      ? Number(hourlyBillingRoundingFactorHours)
      : 0.5;
    return Number((Math.ceil(rawHours / roundingFactor) * roundingFactor).toFixed(2));
  }

  function cleanInvoiceStampLabel(value?: string | null) {
    return String(value ?? "")
      .replace(/\s*\([^)]+\/\s*Std\.\)\s*$/i, "")
      .trim();
  }

  function getInvoiceLineStampEntries(
    projectId: string,
    draft: InvoiceDraft,
    line: OfferLineDraft,
    invoiceId?: string | null
  ) {
    const monthKey = getInvoiceBillingMonthKey(draft);
    const lineCatalogItemId = String(line.catalogItemId ?? "").trim();
    const lineTitle = cleanInvoiceStampLabel(line.title).toLowerCase();
    const catalogLabel = lineCatalogItemId
      ? catalogItems.find((item) => item.id === lineCatalogItemId)
      : null;
    const catalogLineTitle = catalogLabel
      ? cleanInvoiceStampLabel(`${catalogLabel.number} | ${catalogLabel.name}`).toLowerCase()
      : "";
    const activeInvoiceId = String(invoiceId ?? "").trim();

    return stampEntries.filter((entry) => {
      if (entry.mode !== "project") return false;
      if (String(entry.projectId) !== String(projectId)) return false;
      if (entry.deletedAt) return false;
      if (entry.completionStatus === "interrupted") return false;
      if (Number(entry.durationMs || 0) <= 0) return false;
      if (monthKey && !normalizeDateKeyValue(entry.date).startsWith(monthKey)) return false;

      const entryInvoiceId = String(entry.invoiceId ?? "").trim();
      if (entryInvoiceId && entryInvoiceId !== activeInvoiceId) return false;

      const entryCatalogItemId = String(entry.billingCatalogItemId ?? "").trim();
      if (lineCatalogItemId && entryCatalogItemId && entryCatalogItemId === lineCatalogItemId) return true;

      const entryLabel = cleanInvoiceStampLabel(entry.billingCatalogItemLabel).toLowerCase();
      return Boolean(entryLabel && (entryLabel === lineTitle || entryLabel === catalogLineTitle));
    });
  }

  function getRoundedStampedInvoiceLaborItems(entries: StampTimeEntry[]) {
    const grouped = new Map<string, OfferLineLaborDraft>();
    for (const entry of entries) {
      const userId = String(entry.userId ?? "");
      const employeeName = entry.employee || users.find((user) => user.id === userId)?.name || "Mitarbeiter";
      const key = userId || employeeName.toLowerCase();
      const hours = getRoundedBillableStampHours(entry);
      if (hours <= 0) continue;
      const current =
        grouped.get(key) ??
        (userId
          ? createOfferLaborItem(users.find((user) => user.id === userId))
          : {
              id: crypto.randomUUID(),
              userId: "",
              employeeName,
              plannedHours: 0,
              hourlyCostRate: 0,
              totalCost: 0,
            });
      current.userId = userId || current.userId;
      current.employeeName = employeeName;
      current.plannedHours += hours;
      current.hourlyCostRate = current.userId ? getEmployeeHourlyCostRate(current.userId) : current.hourlyCostRate;
      current.totalCost = current.plannedHours * Number(current.hourlyCostRate || 0);
      grouped.set(key, current);
    }
    return Array.from(grouped.values()).map((labor) => ({
      ...labor,
      id: crypto.randomUUID(),
      plannedHours: Number(labor.plannedHours.toFixed(2)),
      totalCost: Number((labor.plannedHours * Number(labor.hourlyCostRate || 0)).toFixed(2)),
    }));
  }

  function syncInvoiceLineLaborFromStampIds(lineIndex: number, entryIds: string[]) {
    if (!selectedProjectFile) return;
    const selectedIds = new Set(entryIds);
    setInvoiceDraft((current) => ({
      ...current,
      lines: current.lines.map((line, currentLineIndex) => {
        if (currentLineIndex !== lineIndex || !canPlanOfferLineLabor(line)) return line;
        const lineEntries = getInvoiceLineStampEntries(selectedProjectFile.id, current, line, editingInvoiceId).filter(
          (entry) => selectedIds.has(entry.id)
        );
        const laborItems = getRoundedStampedInvoiceLaborItems(lineEntries);
        const invoiceHours = laborItems.reduce((sum, labor) => sum + Number(labor.plannedHours || 0), 0);
        return {
          ...line,
          quantity: Number(invoiceHours.toFixed(2)),
          laborItems,
        };
      }),
    }));
  }

  function toggleInvoiceLineStampEntry(lineIndex: number, entryId: string, checked: boolean) {
    const nextIds = checked
      ? Array.from(new Set([...invoiceStampEntryIds, entryId]))
      : invoiceStampEntryIds.filter((id) => id !== entryId);
    setInvoiceStampEntryIds(nextIds);
    setInvoiceBillableStampEntryIds(nextIds);
    syncInvoiceLineLaborFromStampIds(lineIndex, nextIds);
  }

  function takeOverInvoiceLineStampEntries(lineIndex: number, entries: StampTimeEntry[]) {
    if (entries.length === 0) return;
    const nextIds = Array.from(new Set([...invoiceStampEntryIds, ...entries.map((entry) => entry.id)]));
    setInvoiceStampEntryIds(nextIds);
    setInvoiceBillableStampEntryIds(nextIds);
    syncInvoiceLineLaborFromStampIds(lineIndex, nextIds);
  }

  function getInvoiceStampBasisEntries(projectId: string, draft: InvoiceDraft) {
    const monthKey = getInvoiceBillingMonthKey(draft);
    return stampEntries.filter((entry) => {
      if (entry.mode !== "project") return false;
      if (String(entry.projectId) !== String(projectId)) return false;
      if (entry.deletedAt) return false;
      if (entry.completionStatus === "interrupted") return false;
      if (Number(entry.durationMs || 0) <= 0) return false;
      if (!monthKey) return true;
      return normalizeDateKeyValue(entry.date).startsWith(monthKey);
    });
  }

  function getInvoiceStampBasisHoursForWorker(
    projectId: string,
    draft: InvoiceDraft,
    worker: Pick<OfferLineLaborDraft, "userId" | "employeeName">
  ) {
    const userId = String(worker.userId ?? "");
    const employeeName = String(worker.employeeName ?? "").trim().toLowerCase();
    return getInvoiceStampBasisEntries(projectId, draft)
      .filter((entry) => {
        if (userId) return String(entry.userId ?? "") === userId;
        return String(entry.employee ?? "").trim().toLowerCase() === employeeName;
      })
      .reduce((sum, entry) => sum + getRoundedBillableStampHours(entry), 0);
  }

  function getInvoiceLaborStampWarnings(draft: InvoiceDraft, projectId: string) {
    const plannedByWorker = new Map<string, { userId: string; employeeName: string; hours: number }>();
    for (const line of draft.lines) {
      if (!canPlanOfferLineLabor(line)) continue;
      for (const labor of line.laborItems) {
        const hours = Number(labor.plannedHours || 0);
        if (hours <= 0) continue;
        const userId = String(labor.userId ?? "");
        const employeeName = String(labor.employeeName ?? "").trim() || "Mitarbeiter";
        const key = userId || employeeName.toLowerCase();
        const current = plannedByWorker.get(key) ?? { userId, employeeName, hours: 0 };
        current.hours += hours;
        plannedByWorker.set(key, current);
      }
    }

    const warnings: string[] = [];
    for (const worker of plannedByWorker.values()) {
      const stampBasisHours = getInvoiceStampBasisHoursForWorker(projectId, draft, worker);
      if (stampBasisHours <= 0) {
        warnings.push(
          `${worker.employeeName}: Es gibt im Abrechnungsmonat keine passende Stempelung.`
        );
      } else if (worker.hours > stampBasisHours + 0.01) {
        warnings.push(
          `${worker.employeeName}: ${formatHours(worker.hours)} Std. angesetzt, aber nur ${formatHours(stampBasisHours)} Std. aus Stempelungen ableitbar.`
        );
      }
    }
    return warnings;
  }

  function showInvoiceLaborStampNotice(
    draft: InvoiceDraft,
    projectId: string,
    labor: Pick<OfferLineLaborDraft, "userId" | "employeeName">,
    plannedHours: number
  ) {
    const employeeName = String(labor.employeeName ?? "").trim() || "Mitarbeiter";
    const stampBasisHours = getInvoiceStampBasisHoursForWorker(projectId, draft, labor);
    if (stampBasisHours <= 0) {
      window.alert(
        `Hinweis: Für ${employeeName} gibt es im Abrechnungsmonat keine passende Stempelung. Bitte nur bewusst manuell abrechnen.`
      );
      return;
    }
    if (plannedHours > stampBasisHours + 0.01) {
      window.alert(
        `Hinweis: Für ${employeeName} sind ${formatHours(plannedHours)} Std. angesetzt, aber nur ${formatHours(stampBasisHours)} Std. aus Stempelungen ableitbar. Bitte prüfen.`
      );
    }
  }

  function getStampedInvoiceLaborItems(entries: StampTimeEntry[]) {
    const grouped = new Map<string, OfferLineLaborDraft>();
    for (const entry of entries) {
      const userId = String(entry.userId ?? "");
      const employeeName = entry.employee || users.find((user) => user.id === userId)?.name || "Mitarbeiter";
      const key = userId || employeeName;
      const hours = Number(entry.durationMs || 0) / 3_600_000;
      const current =
        grouped.get(key) ??
        (userId
          ? createOfferLaborItem(users.find((user) => user.id === userId))
          : {
              id: crypto.randomUUID(),
              userId: "",
              employeeName,
              plannedHours: 0,
              hourlyCostRate: 0,
              totalCost: 0,
            });
      current.userId = userId || current.userId;
      current.employeeName = employeeName;
      current.plannedHours += hours;
      current.hourlyCostRate = current.userId ? getEmployeeHourlyCostRate(current.userId) : current.hourlyCostRate;
      current.totalCost = current.plannedHours * Number(current.hourlyCostRate || 0);
      grouped.set(key, current);
    }
    return Array.from(grouped.values()).map((labor) => ({
      ...labor,
      id: crypto.randomUUID(),
      plannedHours: Number(labor.plannedHours.toFixed(2)),
      totalCost: Number((labor.plannedHours * Number(labor.hourlyCostRate || 0)).toFixed(2)),
    }));
  }

  function applyStampedHoursToInvoiceDraft(draft: InvoiceDraft, entries: StampTimeEntry[]) {
    const laborItems = getStampedInvoiceLaborItems(entries);
    const stampedHours = laborItems.reduce((sum, labor) => sum + Number(labor.plannedHours || 0), 0);
    if (stampedHours <= 0) return draft;

    const targetLineIndex = draft.lines.findIndex((line) => canPlanOfferLineLabor(line));
    const lines = [...draft.lines];
    if (targetLineIndex >= 0) {
      const line = lines[targetLineIndex];
      lines[targetLineIndex] = {
        ...line,
        quantity: stampedHours,
        laborItems,
      };
      return { ...draft, lines };
    }

    const serviceItem = catalogItems.find((item) => item.isActive && item.type === "service");
    const fallbackLine = serviceItem
      ? createOfferLineFromCatalogItem(serviceItem)
      : {
          id: crypto.randomUUID(),
          catalogItemId: "",
          catalogType: "service" as CatalogItemType,
          quantity: stampedHours,
          unit: "Std",
          title: "Arbeitszeit laut Stempelung",
          description: "Produktiv gestempelte Stunden",
          unitPrice: 0,
          discountPercent: 0,
          vatRate: draft.vatRate,
          laborItems: [],
        };

    return {
      ...draft,
      lines: [
        ...lines,
        {
          ...fallbackLine,
          quantity: stampedHours,
          laborItems,
        },
      ],
    };
  }

  function takeOverStampEntriesForInvoice(entries: StampTimeEntry[], billable: boolean) {
    if (entries.length === 0) return;
    const entryIds = entries.map((entry) => entry.id);
    if (billable) {
      setInvoiceDraft((current) => applyStampedHoursToInvoiceDraft(current, entries));
      setInvoiceBillableStampEntryIds(entryIds);
    }
    setInvoiceStampEntryIds(entryIds);
  }

  function toggleInvoiceStampEntry(entryId: string, checked: boolean) {
    setInvoiceStampEntryIds((currentIds) =>
      checked ? Array.from(new Set([...currentIds, entryId])) : currentIds.filter((id) => id !== entryId)
    );
  }

  function getInvoiceDraftLaborHours(draft: OfferDraft) {
    return draft.lines.reduce(
      (sum, line) =>
        sum + line.laborItems.reduce((lineSum, labor) => lineSum + Number(labor.plannedHours || 0), 0),
      0
    );
  }

  function createInvoiceDraftFromInvoice(invoice: InvoiceItem): InvoiceDraft {
    return {
      company: invoice.company,
      offerType: "base",
      addendumMode: "addition",
      plannedExecutionEndMonth: "",
      parentOfferId: "",
      customerName: invoice.customerName,
      customerStreet: invoice.customerStreet,
      customerCity: invoice.customerCity,
      contactName: invoice.contactName,
      internalContactName: invoice.internalContactName,
      internalPhone: invoice.internalPhone,
      internalEmail: invoice.internalEmail,
      plannedExecutionMonth: invoice.plannedExecutionMonth || "",
      serviceDate: invoice.serviceDate || "",
      paymentTermDays: invoice.paymentTermDays ?? 14,
      dueDate: invoice.dueDate || "",
      sourceOfferId: invoice.sourceOfferId || "",
      sourceOfferNumber: invoice.sourceOfferNumber || "",
      discountPercent: invoice.discountPercent ?? 0,
      introText: invoice.introText,
      closingText: invoice.closingText,
      vatRate: invoice.vatRate || 19,
      lines:
        invoice.lines.length > 0
          ? invoice.lines.map((line) => ({
              id: line.id || crypto.randomUUID(),
              catalogItemId: line.catalogItemId,
              catalogType: line.catalogType,
              quantity: line.quantity,
              unit: line.unit,
              title: line.title,
              description: line.description,
              unitPrice: line.unitPrice,
              discountPercent: line.discountPercent ?? 0,
              vatRate: line.vatRate,
              laborItems: (line.laborItems ?? []).map((labor) => ({
                id: labor.id || crypto.randomUUID(),
                userId: labor.userId,
                employeeName: labor.employeeName,
                plannedHours: labor.plannedHours,
                hourlyCostRate: labor.hourlyCostRate,
                totalCost: labor.totalCost,
              })),
            }))
          : [createEmptyOfferLine(invoice.vatRate || 19)],
    };
  }

  async function saveInvoice(options: {
    asDraft?: boolean;
    finalizeConfirmed?: boolean;
    processPreflightConfirmed?: boolean;
    noteConfirmed?: boolean;
  } = {}) {
    if (!selectedProjectFile) return;
    const saveAsDraft = Boolean(options.asDraft);
    const editingInvoice = editingInvoiceId ? invoices.find((invoice) => invoice.id === editingInvoiceId) : null;
    if (!saveAsDraft && editingInvoice?.status === "Entwurf" && !options.finalizeConfirmed) {
      setPendingFinalizeInvoice({ source: "modal" });
      return;
    }
    if (
      !saveAsDraft &&
      !options.noteConfirmed &&
      (!editingInvoice || editingInvoice.status === "Entwurf")
    ) {
      const customer = getProjectCustomerContact(selectedProjectFile);
      const notes = await loadCustomerProjectNotes({
        customerId: customer?.id || selectedProjectFile.contactId || "",
        projectId: selectedProjectFile.id,
        context: "invoiceCreate",
        userId: activeUserId,
      });
      if (notes.length > 0) {
        setIsPendingNoteConfirmed(false);
        setPendingWorkflowNoteConfirm({
          notes,
          context: "invoiceCreate",
          customerId: customer?.id || selectedProjectFile.contactId || "",
          projectId: selectedProjectFile.id,
          invoiceOptions: options,
        });
        setNoteError("");
        return;
      }
    }
    const normalizedServiceDate =
      invoiceDraft.serviceDate || getProjectServiceDateSuggestion(selectedProjectFile, invoiceDraft.plannedExecutionMonth);
    const normalizedInvoiceDraft = {
      ...invoiceDraft,
      serviceDate: normalizedServiceDate,
      plannedExecutionMonth: normalizedServiceDate.slice(0, 7) || invoiceDraft.plannedExecutionMonth,
      dueDate: invoiceDraft.dueDate || getInvoiceDueDate(normalizedServiceDate, invoiceDraft.paymentTermDays),
    };
    if (!saveAsDraft && !normalizedInvoiceDraft.serviceDate) {
      setInvoiceError("Bitte ein Leistungsdatum setzen.");
      return;
    }
    if (!saveAsDraft) {
      const processPreflightOk = await runInvoiceProcessPreflight(
        selectedProjectFile,
        normalizedInvoiceDraft,
        {
          skipConfirmation: options.processPreflightConfirmed,
          source: "create",
        }
      );
      if (!processPreflightOk) return;
    }
    if (!saveAsDraft && !editingInvoiceId && !options.finalizeConfirmed) {
      const confirmedServiceDate = window.confirm(
        `Die Rechnung wird mit dem Leistungsdatum ${getInvoiceServiceDateLabel(normalizedInvoiceDraft.serviceDate)} erstellt. Ist das korrekt?`
      );
      if (!confirmedServiceDate) return;
    }
    setIsSavingInvoice(true);
    setInvoiceError("");
    let draftToSave = normalizedInvoiceDraft;
    let billedStampEntryIds = invoiceStampEntryIds;
    let allowUnderbilledStampedHours = false;
    const unbilledStampEntries = getUnbilledProjectStampEntries(selectedProjectFile.id);
    const selectedStampEntries = unbilledStampEntries.filter((entry) =>
      invoiceStampEntryIds.includes(entry.id)
    );
    const billableStampEntries = unbilledStampEntries.filter((entry) =>
      invoiceBillableStampEntryIds.includes(entry.id)
    );

    if (!saveAsDraft && billableStampEntries.length > 0) {
      const stampedHours = billableStampEntries.reduce((sum, entry) => sum + Number(entry.durationMs || 0) / 3_600_000, 0);
      const invoiceLaborHours = getInvoiceDraftLaborHours(draftToSave);
      if (invoiceLaborHours + 0.01 < stampedHours) {
        allowUnderbilledStampedHours = window.confirm(
          `Achtung: Es wurden ${formatHours(stampedHours)} Std. zur Rechnung übernommen, aber nur ${formatHours(invoiceLaborHours)} Std. fakturiert. Trotzdem speichern?`
        );
        if (!allowUnderbilledStampedHours) {
          setIsSavingInvoice(false);
          return;
        }
      }
    } else if (!saveAsDraft && selectedStampEntries.length > 0) {
      allowUnderbilledStampedHours = true;
    } else if (!saveAsDraft && unbilledStampEntries.length > 0) {
      const stampedHours = unbilledStampEntries.reduce((sum, entry) => sum + Number(entry.durationMs || 0) / 3_600_000, 0);
      const shouldTakeOverStampedHours = window.confirm(
        `Es gibt ${formatHours(stampedHours)} produktiv gestempelte, noch nicht fakturierte Stunden. Möchtest du diese Stunden auf die Rechnung übernehmen?`
      );

      if (shouldTakeOverStampedHours) {
        draftToSave = applyStampedHoursToInvoiceDraft(draftToSave, unbilledStampEntries);
        billedStampEntryIds = unbilledStampEntries.map((entry) => entry.id);
        setInvoiceDraft(draftToSave);
        setInvoiceStampEntryIds(billedStampEntryIds);
        setInvoiceBillableStampEntryIds(billedStampEntryIds);

        const invoiceLaborHours = getInvoiceDraftLaborHours(draftToSave);
        if (invoiceLaborHours + 0.01 < stampedHours) {
          allowUnderbilledStampedHours = window.confirm(
            `Achtung: Es wurden ${formatHours(stampedHours)} Std. gestempelt, aber nur ${formatHours(invoiceLaborHours)} Std. fakturiert. Trotzdem speichern?`
          );
          if (!allowUnderbilledStampedHours) {
            setIsSavingInvoice(false);
            return;
          }
        }
      }
    }

    if (!saveAsDraft) {
      const laborStampWarnings = getInvoiceLaborStampWarnings(draftToSave, selectedProjectFile.id);
      if (laborStampWarnings.length > 0) {
        const confirmedLaborStampWarnings = window.confirm(
          `Bitte prüfen:\n\n${laborStampWarnings.join("\n")}\n\nTrotzdem speichern?`
        );
        if (!confirmedLaborStampWarnings) {
          setIsSavingInvoice(false);
          return;
        }
      }
    }

    const unlinkedStampEntries = unbilledStampEntries.filter((entry) => !billedStampEntryIds.includes(entry.id));
    if (!saveAsDraft && unlinkedStampEntries.length > 0) {
      const confirmedWithoutStampLinks = window.confirm(
        "Achtung, zu verknüpfende Stempelungen vorhanden! Wollen Sie diese sicher nicht mit der Rechnung verknüpfen?"
      );
      if (!confirmedWithoutStampLinks) {
        setIsSavingInvoice(false);
        return;
      }
    }

    const res = await fetch("/api/invoices", {
      method: editingInvoiceId ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: editingInvoiceId,
        actorId: activeUserId,
        ...draftToSave,
        saveAsDraft,
        billedStampEntryIds,
        allowUnderbilledStampedHours,
        projectId: selectedProjectFile.id,
        projectNumber: selectedProjectFile.projectNumber || selectedProjectFile.id,
        projectTitle: selectedProjectFile.title,
      }),
    });
    setIsSavingInvoice(false);

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      if (data?.requiresUnderbillingConfirmation) {
        const confirmed = window.confirm(`${data.error} Trotzdem speichern?`);
        setIsSavingInvoice(false);
        if (confirmed) {
          setTimeout(() => {
            void saveInvoice({ processPreflightConfirmed: true, noteConfirmed: true });
          }, 0);
        }
        return;
      }
      setInvoiceError(data?.error ?? "Rechnung konnte nicht erstellt werden.");
      return;
    }

    const savedInvoice = (await res.json()) as InvoiceItem;
    setInvoices((currentInvoices) => [savedInvoice, ...currentInvoices.filter((invoice) => invoice.id !== savedInvoice.id)]);
    if (!saveAsDraft && billedStampEntryIds.length > 0) {
      setStampEntries((currentEntries) =>
        currentEntries.map((entry) =>
          billedStampEntryIds.includes(entry.id)
            ? {
                ...entry,
                invoiceId: savedInvoice.id,
                invoiceNumber: savedInvoice.invoiceNumber,
                invoicedAt: new Date().toISOString(),
              }
            : entry
        )
      );
    }
    await addProjectLogbookEntry(
      selectedProjectFile.id,
      "Rechnung",
      `${saveAsDraft ? "Rechnungsentwurf gespeichert" : editingInvoiceId ? "Rechnung geändert" : "Rechnung erstellt"}: ${savedInvoice.invoiceNumber} (${formatMoney(
        savedInvoice.grossTotal
      )} brutto).`
    );
    if (!saveAsDraft) {
      await applyProjectStatusAfterInvoice(selectedProjectFile, savedInvoice);
    }
    setSelectedProjectDocumentType("Rechnungen");
    setProjectFileTab("documents");
    setIsInvoiceModalOpen(false);
    setEditingInvoiceId("");
    setInvoiceStampEntryIds([]);
    setInvoiceBillableStampEntryIds([]);
    if (!saveAsDraft && savedInvoice.pdfAvailable) {
      window.open(getInvoicePdfUrl(savedInvoice.id), "_blank");
    }
  }

  async function finalizeInvoice(invoice: InvoiceItem, noteConfirmed = false) {
    if (invoice.status !== "Entwurf") return;
    const project = heroProjects.find((item) => item.id === invoice.projectId) || selectedProjectFile;
    if (!project) {
      setErrorMessage("Projekt zur Rechnung wurde nicht gefunden.");
      return;
    }

    if (!noteConfirmed) {
      const customer = getProjectCustomerContact(project);
      const notes = await loadCustomerProjectNotes({
        customerId: customer?.id || project.contactId || "",
        projectId: project.id,
        context: "invoiceCreate",
        userId: activeUserId,
      });
      if (notes.length > 0) {
        setIsPendingNoteConfirmed(false);
        setPendingWorkflowNoteConfirm({
          notes,
          context: "invoiceCreate",
          customerId: customer?.id || project.contactId || "",
          projectId: project.id,
          invoiceToFinalize: invoice,
        });
        setNoteError("");
        return;
      }
    }

    setInvoiceError("");
    const serviceDate = invoice.serviceDate || getProjectServiceDateSuggestion(project, invoice.plannedExecutionMonth);
    const invoiceDraftForFinalize = {
      ...createInvoiceDraftFromInvoice(invoice),
      serviceDate,
      plannedExecutionMonth: serviceDate.slice(0, 7) || invoice.plannedExecutionMonth,
    };
    const processPreflightOk = await runInvoiceProcessPreflight(project, invoiceDraftForFinalize, {
      source: "finalize",
    });
    if (!processPreflightOk) return;

    setIsSavingInvoice(true);
    const res = await fetch("/api/invoices", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: invoice.id,
        actorId: activeUserId,
        ...invoiceDraftForFinalize,
        saveAsDraft: false,
        billedStampEntryIds: [],
        allowUnderbilledStampedHours: false,
        projectId: project.id,
        projectNumber: project.projectNumber || project.id,
        projectTitle: project.title,
      }),
    });

    setIsSavingInvoice(false);

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Rechnung konnte nicht fakturiert werden.");
      return;
    }

    const savedInvoice = (await res.json()) as InvoiceItem;
    setInvoices((currentInvoices) =>
      currentInvoices.map((currentInvoice) => (currentInvoice.id === savedInvoice.id ? savedInvoice : currentInvoice))
    );
    await addProjectLogbookEntry(
      project.id,
      "Rechnung",
      `Rechnung fakturiert: ${savedInvoice.invoiceNumber} (${formatMoney(savedInvoice.grossTotal)} brutto).`
    );
    await applyProjectStatusAfterInvoice(project, savedInvoice);
  }

  async function confirmFinalizeInvoice() {
    const pending = pendingFinalizeInvoice;
    if (!pending) return;
    setPendingFinalizeInvoice(null);
    if (pending.source === "modal") {
      await saveInvoice({ finalizeConfirmed: true });
      return;
    }
    await finalizeInvoice(pending.invoice);
  }

  async function cancelInvoice(invoice: InvoiceItem) {
    if (!selectedProjectFile) return;
    if (["Storniert", "Stornorechnung"].includes(invoice.status) || isDeletedStatus(invoice.status)) return;

    const confirmed = window.confirm(
      `Soll ${invoice.invoiceNumber} wirklich storniert werden? Es wird automatisch eine neue Stornorechnung mit eigener Rechnungsnummer erstellt.`
    );
    if (!confirmed) return;

    const res = await fetch("/api/invoices", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: invoice.id,
        action: "cancel",
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      const message = data?.error ?? "Rechnung konnte nicht storniert werden.";
      setErrorMessage(message);
      window.alert(message);
      return;
    }

    const data = (await res.json()) as {
      originalInvoice: InvoiceItem;
      cancellationInvoice: InvoiceItem;
    };
    setInvoices((currentInvoices) => [
      data.cancellationInvoice,
      data.originalInvoice,
      ...currentInvoices.filter(
        (currentInvoice) =>
          currentInvoice.id !== data.originalInvoice.id &&
          currentInvoice.id !== data.cancellationInvoice.id
      ),
    ]);
    setStampEntries((currentEntries) =>
      currentEntries.map((entry) =>
        entry.invoiceId === invoice.id || entry.invoiceNumber === invoice.invoiceNumber
          ? { ...entry, invoiceId: "", invoiceNumber: "", invoicedAt: "" }
          : entry
      )
    );
    await loadProjectTimeEntries();
    await addProjectLogbookEntry(
      selectedProjectFile.id,
      "Rechnung",
      `Rechnung storniert: ${invoice.invoiceNumber}. Stornorechnung ${data.cancellationInvoice.invoiceNumber} wurde erstellt.`
    );
    window.open(getInvoicePdfUrl(data.cancellationInvoice.id), "_blank");
  }

  async function deleteInvoice(invoice: InvoiceItem, projectOverride?: HeroProjectPreview) {
    const invoiceProject = projectOverride ?? selectedProjectFile ?? heroProjects.find((project) => project.id === invoice.projectId);
    if (!invoiceProject || !canDeleteInvoices) return;
    if (isDeletedStatus(invoice.status)) return;

    const confirmed = window.confirm(
      `Rechnung ${invoice.invoiceNumber} wirklich löschen? Sie wird als gelöscht markiert und aus verknüpften Stempelzeiten gelöst.`
    );
    if (!confirmed) return;

    const res = await fetch("/api/invoices", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: invoice.id,
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      const message = data?.error ?? "Rechnung konnte nicht gelöscht werden.";
      setErrorMessage(message);
      window.alert(message);
      return;
    }

    const deletedInvoice = (await res.json()) as InvoiceItem;
    setInvoices((currentInvoices) =>
      currentInvoices.filter((currentInvoice) => currentInvoice.id !== deletedInvoice.id)
    );
    setSelectedBatchDraftInvoiceIds((currentIds) => currentIds.filter((invoiceId) => invoiceId !== deletedInvoice.id));
    setStampEntries((currentEntries) =>
      currentEntries.map((entry) =>
        entry.invoiceId === invoice.id || entry.invoiceNumber === invoice.invoiceNumber
          ? { ...entry, invoiceId: "", invoiceNumber: "", invoicedAt: "" }
          : entry
      )
    );
    await loadProjectTimeEntries();
    await addProjectLogbookEntry(
      invoiceProject.id,
      "Rechnung",
      `Rechnung gelöscht: ${invoice.invoiceNumber}.`
    );
    await loadInvoiceHistory(invoiceProject.id);
  }

  function applyMailTemplate(kind: DocumentMailKind, documentNumber: string) {
    const template = mailTemplates[kind];
    const sender = activeUser?.name || "WorkPilot360";
    const normalizeTemplateText = (value: string) =>
      value
        .replaceAll("Rueckfragen", "Rückfragen")
        .replaceAll("Verfuegung", "Verfügung")
        .replaceAll("Gruessen", "Grüßen")
        .replaceAll("Taetigkeitsbericht", "Tätigkeitsbericht");

    return {
      subject: normalizeTemplateText(template.subject)
        .replaceAll("{{number}}", documentNumber)
        .replaceAll("{{sender}}", sender),
      body: normalizeTemplateText(template.body)
        .replaceAll("{{number}}", documentNumber)
        .replaceAll("{{sender}}", sender),
    };
  }

  function escapeMailHtml(value: string) {
    return value
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  function textToMailHtml(value: string) {
    return escapeMailHtml(value.trimEnd())
      .split(/\n{2,}/)
      .map((paragraph) => paragraph.replace(/\r?\n/g, "<br>"))
      .map((paragraph) => `<p>${paragraph || "&nbsp;"}</p>`)
      .join("");
  }

  function stripTrailingMailClosing(value: string) {
    return value
      .replace(/\s*(?:\r?\n){1,}Mit freundlichen Gr(?:\u00fc|ue)(?:\u00df|ss)en\s*(?:\r?\n)+[^\r\n]+\s*$/i, "")
      .trimEnd();
  }

  function sanitizeMailSignatureHtml(value: string) {
    return value
      .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, "")
      .replace(/\son\w+="[^"]*"/gi, "")
      .replace(/\son\w+='[^']*'/gi, "");
  }

  function normalizeMailSignatureHtml(value = "") {
    const signature = value.trim();
    if (!signature) return "";
    return /<\/?[a-z][\s\S]*>/i.test(signature)
      ? sanitizeMailSignatureHtml(signature)
      : textToMailHtml(signature);
  }

  function getActiveUserSignatureHtml() {
    if (activeUser?.signatureHidden) return "";
    return normalizeMailSignatureHtml(activeUser?.signature || "");
  }

  function getDocumentMailFeedbackPreviewHtml() {
    const testButtonHtml =
      activeUser?.role === "GESCHAEFTSFUEHRER"
        ? '<a href="/feedback/preview" target="_blank" rel="noreferrer" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;font-weight:800;border-radius:10px;padding:10px 16px;">Jetzt bewerten</a>'
        : '<span style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;font-weight:800;border-radius:10px;padding:10px 16px;">Jetzt bewerten</span>';
    const hintText =
      activeUser?.role === "GESCHAEFTSFUEHRER"
        ? "Testansicht: Es wird kein echter Kundenlink erzeugt und nichts gespeichert."
        : "Der persönliche Bewertungslink wird beim Versand erzeugt.";

    return [
      '<div style="margin:22px 0 18px;padding:16px 18px;border:1px solid #cbd8e6;border-radius:14px;background:#f8fbff;max-width:520px;">',
      '<p style="margin:0 0 8px;color:#0f172a;font-weight:800;">Wie zufrieden waren Sie mit unserer Leistung?</p>',
      '<div style="color:#f5b800;font-size:24px;letter-spacing:2px;line-height:1;margin:0 0 12px;">&#9733;&#9733;&#9733;&#9733;&#9733;</div>',
      testButtonHtml,
      `<p style="margin:10px 0 0;color:#64748b;font-size:12px;line-height:1.4;">${hintText}</p>`,
      "</div>",
    ].join("");
  }

  function getDocumentMailPreviewHtml() {
    if (!documentMailDraft) return "";
    const signatureHtml = getActiveUserSignatureHtml();
    const rawBody =
      documentMailDraft.activeMailTab === "activityReport" && documentMailDraft.hasActivityReportRecipientField
        ? documentMailDraft.activityReportBody || ""
        : documentMailDraft.body;
    const messageBody = signatureHtml ? stripTrailingMailClosing(rawBody) : rawBody;
    const feedbackHtml =
      documentMailDraft.kind === "invoice" &&
      (
        documentMailDraft.activeMailTab === "activityReport"
          ? documentMailDraft.includeActivityReportFeedbackLink !== false
          : documentMailDraft.includeFeedbackLink !== false
      )
        ? getDocumentMailFeedbackPreviewHtml()
        : "";
    return `${textToMailHtml(messageBody)}${feedbackHtml}${signatureHtml ? signatureHtml : ""}`;
  }

  function getDefaultSignatureSource(user: UserOption) {
    return [
      "<p>Mit freundlichen Gr&uuml;&szlig;en</p>",
      `<p><strong>${escapeMailHtml(user.name)}</strong><br>`,
      `${escapeMailHtml(user.roleLabel || "")}<br>`,
      "OK solutions GmbH<br>",
      "Im Kr&ouml;tenteich 3/4<br>",
      "74722 Buchen</p>",
    ].join("");
  }

  function getDocumentMailKindLabel(kind: DocumentMailKind) {
    if (kind === "offer") return "Angebot";
    if (kind === "invoice") return "Rechnung";
    if (kind === "cancellation") return "Stornorechnung";
    if (kind === "reminder") return "Mahnung";
    if (kind === "activityReport") return "Tätigkeitsbericht";
    return "Dokument";
  }

  function getDocumentMailPrimaryAttachmentLabel(draft: DocumentMailDraft) {
    const fallbackName = draft.attachmentName || `${draft.documentNumber}.pdf`;
    if (draft.kind === "invoice") return `Rechnung ${draft.documentNumber} als PDF anhängen`;
    if (draft.kind === "offer") return `Angebot ${draft.documentNumber} als PDF anhängen`;
    if (draft.kind === "cancellation") return `Stornorechnung ${draft.documentNumber} als PDF anhängen`;
    if (draft.kind === "reminder") return `Mahnung ${draft.documentNumber} als PDF anhängen`;
    if (draft.kind === "activityReport") return `Tätigkeitsbericht ${fallbackName} anhängen`;
    return `${fallbackName} anhängen`;
  }

  function getDocumentMailInvoice(draft: DocumentMailDraft | null) {
    if (!draft || draft.kind !== "invoice") return null;
    return invoices.find((invoice) => invoice.id === draft.documentId) ?? null;
  }

  function getInvoiceRecipientContact(invoice: InvoiceItem | null) {
    if (!invoice) return null;
    const project = heroProjects.find((item) => item.id === invoice.projectId) ?? null;
    const relatedContacts = contacts.filter((contact) => {
      if (project && [project.contactId, project.contactPersonId, project.addressContactId].includes(contact.id)) return true;
      if (project?.contactId && contact.parentCompanyId === project.contactId) return true;
      return contact.companyName === invoice.customerName || getContactDisplayName(contact) === invoice.customerName;
    });

    return (
      relatedContacts.find((contact) => contact.invoiceEmail.trim()) ??
      relatedContacts.find((contact) => contact.isInvoiceRecipient) ??
      relatedContacts.find((contact) => contact.isMainContact) ??
      relatedContacts[0] ??
      null
    );
  }

  function getActivityReportRecipientContactForInvoice(invoice: InvoiceItem | null) {
    if (!invoice) return null;
    const invoiceRecipient = getInvoiceRecipientContact(invoice);
    const project = heroProjects.find((item) => item.id === invoice.projectId) ?? null;
    const relatedContacts = contacts.filter((contact) => {
      if (project && [project.contactId, project.contactPersonId, project.addressContactId].includes(contact.id)) return true;
      if (project?.contactId && contact.parentCompanyId === project.contactId) return true;
      return contact.companyName === invoice.customerName || getContactDisplayName(contact) === invoice.customerName;
    });
    const recipient = relatedContacts.find((contact) => getContactActivityReportEmail(contact));
    if (!recipient) return null;
    const recipientEmail = getContactActivityReportEmail(recipient).toLowerCase();
    const invoiceEmail = getContactInvoiceEmail(invoiceRecipient).toLowerCase();
    if (recipientEmail && invoiceEmail && recipientEmail === invoiceEmail) return null;
    return recipient;
  }

  function getOfferRecipientContact(offer: OfferItem | null) {
    if (!offer) return null;
    const project = heroProjects.find((item) => item.id === offer.projectId) ?? null;
    const relatedContacts = contacts.filter((contact) => {
      if (project && [project.contactId, project.contactPersonId, project.addressContactId].includes(contact.id)) return true;
      if (project?.contactId && contact.parentCompanyId === project.contactId) return true;
      return contact.companyName === offer.customerName || getContactDisplayName(contact) === offer.customerName;
    });

    return (
      relatedContacts.find((contact) => contact.invoiceEmail.trim()) ??
      relatedContacts.find((contact) => contact.isInvoiceRecipient) ??
      relatedContacts.find((contact) => contact.isMainContact) ??
      relatedContacts[0] ??
      null
    );
  }

  function getLeitwegIdModulo97(value: string) {
    let remainder = 0;
    for (const character of value) {
      remainder = (remainder * 10 + Number(character)) % 97;
    }
    return remainder;
  }

  function expandLeitwegIdForChecksum(value: string) {
    return value
      .replace(/-/g, "")
      .toUpperCase()
      .replace(/[A-Z]/g, (character) => String(character.charCodeAt(0) - 55));
  }

  function validateLeitwegId(value: string): LeitwegIdValidation {
    const normalized = value.trim().toUpperCase();
    if (!normalized) {
      return {
        normalized,
        isEmpty: true,
        isValid: false,
        message: "Keine Leitweg-ID gepflegt.",
      };
    }

    const formatMatch = normalized.match(/^([0-9]{2,12})(?:-([A-Z0-9]{1,30}))?-([0-9]{2})$/);
    if (!formatMatch) {
      return {
        normalized,
        isEmpty: false,
        isValid: false,
        message: "Format ungültig. Erwartet wird Grobadressierung, optional Feinadressierung und zweistellige Prüfziffer.",
      };
    }

    const expanded = expandLeitwegIdForChecksum(normalized);
    if (!/^[0-9]+$/.test(expanded) || getLeitwegIdModulo97(expanded) !== 1) {
      return {
        normalized,
        isEmpty: false,
        isValid: false,
        message: "Prüfziffer ungültig. Bitte Leitweg-ID beim öffentlichen Auftraggeber abgleichen.",
      };
    }

    return {
      normalized,
      isEmpty: false,
      isValid: true,
      message: "Leitweg-ID ist formal gültig.",
    };
  }

  function getEInvoiceReadiness(draft: DocumentMailDraft | null): EInvoiceReadiness {
    const invoice = getDocumentMailInvoice(draft);
    const recipientContact = getInvoiceRecipientContact(invoice);
    const missingRequired: string[] = [];
    const missingRecommended: string[] = [];

    if (!invoice) {
      return {
        invoice,
        recipientContact,
        missingRequired: ["Rechnungsdatensatz konnte im aktuellen Stand nicht geladen werden."],
        missingRecommended,
      };
    }

    const hasInvoiceAddress = Boolean(invoice.customerStreet.trim() && invoice.customerCity.trim());
    const hasRecipientAddress = Boolean(
      recipientContact?.street?.trim() && [recipientContact?.postalCode, recipientContact?.city].filter(Boolean).join(" ").trim()
    );
    const validLines = invoice.lines.filter((line) => {
      const quantity = Number(line.quantity ?? 0);
      const unitPrice = Number(line.unitPrice ?? 0);
      const vatRate = Number(line.vatRate ?? invoice.vatRate ?? 19);
      return line.title.trim() && Number.isFinite(quantity) && quantity > 0 && line.unit.trim() && Number.isFinite(unitPrice) && Number.isFinite(vatRate);
    });
    const isPublicRecipient = recipientContact?.eInvoiceRecipientType === "public";
    const leitwegValidation = validateLeitwegId(recipientContact?.leitwegId ?? "");
    const effectiveDueDate = invoice.dueDate.trim() || getInvoiceDueDate(invoice.serviceDate, invoice.paymentTermDays ?? 14);

    if (invoice.status === "Entwurf") missingRequired.push("Rechnung ist noch ein Entwurf.");
    if (!invoice.invoiceNumber.trim()) missingRequired.push("Rechnungsnummer fehlt.");
    if (!invoice.serviceDate.trim()) missingRequired.push("Leistungsdatum fehlt.");
    if (!effectiveDueDate) missingRequired.push("Fälligkeitsdatum fehlt.");
    if (!invoice.customerName.trim()) missingRequired.push("Rechnungsempfänger/Kunde fehlt.");
    if (!hasInvoiceAddress && !hasRecipientAddress) missingRequired.push("Vollständige Empfängeradresse fehlt.");
    if (!invoice.lines.length) missingRequired.push("Rechnungspositionen fehlen.");
    if (invoice.lines.length && validLines.length !== invoice.lines.length) {
      missingRequired.push("Mindestens eine Rechnungsposition ist unvollständig.");
    }
    if (!(Number(invoice.netTotal) > 0) || !(Number(invoice.grossTotal) > 0)) {
      missingRequired.push("Rechnungssummen sind nicht plausibel.");
    }
    if (isPublicRecipient && leitwegValidation.isEmpty) {
      missingRequired.push("Leitweg-ID fehlt. Für XRechnung an öffentliche Auftraggeber ist sie erforderlich.");
    }
    if (isPublicRecipient && !leitwegValidation.isEmpty && !leitwegValidation.isValid) {
      missingRequired.push(`Leitweg-ID ist ungültig: ${leitwegValidation.message}`);
    }

    if (!isPublicRecipient && leitwegValidation.isEmpty) {
      missingRecommended.push("Leitweg-ID ist bei Firmenkunden nur nötig, wenn der Empfänger sie ausdrücklich verlangt.");
    }
    if (!isPublicRecipient && !leitwegValidation.isEmpty && !leitwegValidation.isValid) {
      missingRecommended.push(`Leitweg-ID ist eingetragen, aber ungültig: ${leitwegValidation.message}`);
    }
    if (!recipientContact?.taxId?.trim()) {
      missingRecommended.push("Steuer-/USt-ID des Empfängers ist nicht gepflegt.");
    }
    if (!recipientContact?.isInvoiceRecipient) {
      missingRecommended.push("Kein Kontakt ist ausdrücklich als Rechnungsempfänger markiert.");
    }
    if (!recipientContact?.eInvoiceRequired) {
      missingRecommended.push("E-Rechnung ist beim Empfänger noch nicht als erforderlich markiert.");
    }

    return { invoice, recipientContact, missingRequired, missingRecommended };
  }

  async function validateDocumentMailXRechnung(draft: DocumentMailDraft) {
    setIsValidatingXrechnung(true);
    setXrechnungValidationResult(null);
    try {
      const res = await fetch(buildActorApiUrl("/api/invoices", { xrechnungValidationId: draft.documentId }));
      const data = (await res.json()) as XRechnungValidationResponse | { error?: string };
      if (!res.ok || !("validation" in data)) {
        setDocumentMailError(
          "error" in data && data.error ? data.error : "XRechnung-Prüfung konnte nicht ausgeführt werden."
        );
        return;
      }
      setDocumentMailError("");
      setXrechnungValidationResult(data);
    } catch {
      setDocumentMailError("XRechnung-Prüfung konnte nicht ausgeführt werden.");
    } finally {
      setIsValidatingXrechnung(false);
    }
  }

  function getInvoiceDocumentMailKind(invoice: InvoiceItem): DocumentMailKind {
    return invoice.status === "Stornorechnung" || invoice.invoiceNumber.toUpperCase().startsWith("ST-")
      ? "cancellation"
      : "invoice";
  }

  function getLogbookEntryMonthKey(entry: { date?: string; projectMonth?: string }) {
    if (/^\d{4}-\d{2}$/.test(entry.projectMonth || "")) return entry.projectMonth || "";
    const rawDate = entry.date || "";
    const isoMatch = rawDate.match(/^(\d{4})-(\d{2})/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}`;
    const germanMatch = rawDate.match(/^(\d{2})\.(\d{2})\.(\d{4}|\d{2})/);
    if (germanMatch) {
      const year = germanMatch[3].length === 2 ? `20${germanMatch[3]}` : germanMatch[3];
      return `${year}-${germanMatch[2]}`;
    }

    const parsedDate = parseAppDateTime(rawDate);
    return Number.isNaN(parsedDate.getTime()) ? "" : formatDateKey(parsedDate).slice(0, 7);
  }

  function getActivityReportMailAttachmentsForProject(projectId: string, monthKey = "") {
    const project = heroProjects.find((item) => item.id === projectId);
    const isRecurring = project ? getProjectKind(project).startsWith("Dauer") : false;

    return projectLogbookEntries
      .filter((entry) => entry.projectId === projectId)
      .filter((entry) => entry.title === "Dokumente: Tätigkeitsberichte")
      .filter((entry) => !isRecurring || !monthKey || getLogbookEntryMonthKey(entry) === monthKey)
      .flatMap((entry) =>
        entry.attachments.flatMap((attachment) =>
          attachment.type === "Dokument" && attachment.dataUrl
            ? [{ name: attachment.name, dataUrl: attachment.dataUrl }]
            : []
        )
      );
  }

  function openDocumentMailDialog(kind: DocumentMailKind, document: OfferItem | InvoiceItem) {
    if (kind === "invoice" && (document as InvoiceItem).status === "Entwurf") {
    const confirmed = window.confirm("Sie möchten einen Entwurf versenden. Sind Sie sicher?");
      if (!confirmed) return;
    }
    const activeMailAccount = getSafeEmployeeMailAccount(activeUser?.mailAccount, activeUser?.email || "");
    const documentNumber = kind === "offer" ? (document as OfferItem).offerNumber : getInvoiceDisplayNumber(document as InvoiceItem);
    const template = applyMailTemplate(kind, documentNumber);
    const invoice = kind === "invoice" ? (document as InvoiceItem) : null;
    const invoiceRecipient = kind === "invoice" ? getInvoiceRecipientContact(invoice) : null;
    const offerRecipient = kind === "offer" ? getOfferRecipientContact(document as OfferItem) : null;
    const activityReportRecipient = kind === "invoice" ? getActivityReportRecipientContactForInvoice(invoice) : null;
    const activityReportTemplate =
      kind === "invoice" ? applyMailTemplate("activityReport", documentNumber) : null;
    const activityReportAttachments =
      kind === "invoice"
        ? getActivityReportMailAttachmentsForProject(document.projectId, getProjectInvoiceMonth(document as InvoiceItem))
        : [];

    setDocumentMailDraft({
      kind,
      documentId: document.id,
      documentNumber,
      projectId: document.projectId,
      projectNumber: document.projectNumber,
      projectTitle: document.projectTitle,
      customerName: document.customerName,
      to: getContactInvoiceEmail(invoiceRecipient) || getContactInvoiceEmail(offerRecipient),
      cc: "",
      bcc: activeMailAccount.bcc,
      subject: template.subject,
      body: template.body,
      attachPdf: true,
      eInvoiceFormat: kind === "invoice" ? "pdf" : undefined,
      includeFeedbackLink: kind === "invoice",
      includeActivityReportFeedbackLink: kind === "invoice",
      attachActivityReports: activityReportAttachments.length > 0,
      additionalAttachments: activityReportAttachments,
      activityReportTo: getContactActivityReportEmail(activityReportRecipient),
      activityReportSubject: activityReportTemplate?.subject || "",
      activityReportBody: activityReportTemplate?.body || "",
      hasActivityReportRecipientField: Boolean(getContactActivityReportEmail(activityReportRecipient)),
      activeMailTab: "invoice",
    });
    closeDocumentMailProjectAttachmentPicker();
    setDocumentMailError(
      activeMailAccount.status === "connected"
        ? ""
        : "Für deinen Benutzer ist noch kein Microsoft 365 Konto verbunden. Du kannst den Versanddialog vorbereiten, aber noch nicht senden."
    );
    setDocumentMailSuccess("");
  }

  function openGenericDocumentMailDialog(input: {
    kind: DocumentMailKind;
    documentId: string;
    documentNumber: string;
    projectId?: string;
    projectNumber?: string;
    projectTitle?: string;
    customerName?: string;
    attachmentName?: string;
    attachmentDataUrl?: string;
  }) {
    const activeMailAccount = getSafeEmployeeMailAccount(activeUser?.mailAccount, activeUser?.email || "");
    const template = applyMailTemplate(input.kind, input.documentNumber);
    const reminderInvoiceNumber =
      input.kind === "reminder" ? input.documentNumber.match(/^MA-(.+)-\d+$/i)?.[1] || "" : "";
    const reminderInvoice = reminderInvoiceNumber
      ? invoices.find(
          (invoice) =>
            invoice.projectId === (input.projectId || selectedProjectFile?.id || "") &&
            invoice.invoiceNumber === reminderInvoiceNumber
        ) ?? null
      : null;
    const reminderRecipientEmail =
      input.kind === "reminder" ? getContactInvoiceEmail(getInvoiceRecipientContact(reminderInvoice)) : "";

    setDocumentMailDraft({
      kind: input.kind,
      documentId: input.documentId,
      documentNumber: input.documentNumber,
      projectId: input.projectId || selectedProjectFile?.id || "",
      projectNumber: input.projectNumber || selectedProjectFile?.projectNumber || selectedProjectFile?.id || "",
      projectTitle: input.projectTitle || selectedProjectFile?.title || "",
      customerName: input.customerName || selectedProjectFile?.customer || "",
      attachmentName: input.attachmentName,
      attachmentDataUrl: input.attachmentDataUrl,
      to: reminderRecipientEmail,
      cc: "",
      bcc: activeMailAccount.bcc,
      subject: template.subject,
      body: template.body,
      attachPdf: Boolean(input.attachmentDataUrl),
      eInvoiceFormat: input.kind === "invoice" ? "pdf" : undefined,
      includeFeedbackLink: input.kind === "invoice",
      includeActivityReportFeedbackLink: input.kind === "invoice",
    });
    closeDocumentMailProjectAttachmentPicker();
    setDocumentMailError(
      activeMailAccount.status === "connected"
        ? ""
        : "Für deinen Benutzer ist noch kein Microsoft 365 Konto verbunden. Du kannst den Versanddialog vorbereiten, aber noch nicht senden."
    );
    setDocumentMailSuccess("");
  }

  async function sendDocumentMail(noteConfirmed = false) {
    if (!documentMailDraft) return;
    if (!noteConfirmed && (documentMailDraft.kind === "offer" || documentMailDraft.kind === "invoice")) {
      const project = heroProjects.find((item) => item.id === documentMailDraft.projectId) || selectedProjectFile;
      if (project) {
        const customer = getProjectCustomerContact(project);
        const context = documentMailDraft.kind === "offer" ? "offerSend" : "invoiceSend";
        const notes = await loadCustomerProjectNotes({
          customerId: customer?.id || project.contactId || "",
          projectId: project.id,
          context,
          userId: activeUserId,
        });
        if (notes.length > 0) {
          setIsPendingNoteConfirmed(false);
          setPendingWorkflowNoteConfirm({
            notes,
            context,
            customerId: customer?.id || project.contactId || "",
            projectId: project.id,
          });
          setNoteError("");
          return;
        }
      }
    }
    if (!documentMailDraft.to.trim()) {
      setDocumentMailError("Bitte mindestens einen Empfänger eintragen.");
      return;
    }

    setIsSendingDocumentMail(true);
    setDocumentMailError("");
    setDocumentMailSuccess("");

    const res = await fetch("/api/document-mail", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...documentMailDraft,
        actorId: activeUserId,
      }),
    });

    const data = await res.json().catch(() => null);
    setIsSendingDocumentMail(false);

    if (!res.ok) {
      setDocumentMailError(data?.error ?? "E-Mail konnte nicht gesendet werden.");
      return;
    }

    setDocumentMailSuccess("E-Mail wurde für den Versand protokolliert.");
    await loadOfferHistory(documentMailDraft.projectId);
    await loadInvoiceHistory(documentMailDraft.projectId);
    await loadDocumentMailDispatches(documentMailDraft.projectId);
    if (documentMailDraft.kind === "invoice") {
      await loadCustomerFeedbackRequests();
    }
    if (documentMailDraft.projectId) {
      await addProjectLogbookEntry(
        documentMailDraft.projectId,
        "E-Mail",
        `${getDocumentMailKindLabel(documentMailDraft.kind)} ${documentMailDraft.documentNumber} wurde per E-Mail an ${documentMailDraft.to} gesendet.`
      );
    }
    window.setTimeout(() => setDocumentMailDraft(null), 700);
  }

  function readMailAttachmentFile(file: File) {
    return new Promise<{ name: string; dataUrl: string }>((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        if (typeof reader.result === "string") {
          resolve({ name: file.name, dataUrl: reader.result });
          return;
        }
        reject(new Error("Datei konnte nicht gelesen werden."));
      };
      reader.onerror = () => reject(new Error("Datei konnte nicht gelesen werden."));
      reader.readAsDataURL(file);
    });
  }

  function getDataUrlByteSize(dataUrl: string) {
    const base64 = dataUrl.split(",", 2)[1] ?? "";
    const padding = base64.endsWith("==") ? 2 : base64.endsWith("=") ? 1 : 0;
    return Math.max(0, Math.floor((base64.length * 3) / 4) - padding);
  }

  function getDocumentMailManualAttachmentBytes(attachments: Array<{ dataUrl: string }>) {
    return attachments.reduce((sum, attachment) => sum + getDataUrlByteSize(attachment.dataUrl), 0);
  }

  async function addManualDocumentMailAttachments(files: FileList | null) {
    if (!files?.length) return;
    const selectedFiles = Array.from(files);
    const totalBytes = selectedFiles.reduce((sum, file) => sum + file.size, 0);
    const existingBytes = getDocumentMailManualAttachmentBytes(documentMailDraft?.manualAttachments || []);
    const maxBytes = 15 * 1024 * 1024;

    if (existingBytes + totalBytes > maxBytes) {
      setDocumentMailError("Die ausgewählten Zusatzanhänge sind größer als 15 MB.");
      return;
    }

    try {
      const attachments = (await Promise.all(selectedFiles.map(readMailAttachmentFile))).map((attachment) => ({
        ...attachment,
        target: documentMailDraft?.hasActivityReportRecipientField
          ? documentMailDraft.activeMailTab === "activityReport"
            ? "activityReport" as const
            : "invoice" as const
          : undefined,
      }));
      setDocumentMailDraft((current) =>
        current
          ? {
              ...current,
              manualAttachments: [...(current.manualAttachments || []), ...attachments],
            }
          : current
      );
      setDocumentMailError("");
    } catch (error) {
      setDocumentMailError(error instanceof Error ? error.message : "Zusatzanhang konnte nicht gelesen werden.");
    }
  }

  function removeManualDocumentMailAttachment(index: number) {
    setDocumentMailDraft((current) =>
      current
        ? {
            ...current,
            manualAttachments: (current.manualAttachments || []).filter((_, itemIndex) => itemIndex !== index),
          }
        : current
    );
  }

  function getDocumentMailProjectAttachmentOptions(draft: DocumentMailDraft | null) {
    if (!draft?.projectId) return [];

    const selectedAttachments = [
      ...(draft.manualAttachments || []),
      ...(draft.attachActivityReports ? draft.additionalAttachments || [] : []),
    ];

    return projectLogbookEntries
      .filter((entry) => entry.projectId === draft.projectId)
      .flatMap((entry) =>
        entry.attachments.flatMap((attachment, attachmentIndex) => {
          if (!attachment.dataUrl) return [];
          const alreadySelected = selectedAttachments.some(
            (selectedAttachment) =>
              selectedAttachment.name === attachment.name && selectedAttachment.dataUrl === attachment.dataUrl
          );
          if (alreadySelected) return [];

          const category = entry.title.replace(/^(Dokumente|Bilder):\s*/i, "") || "Projektanhang";
          const typeLabel = attachment.type === "Bild" ? "Bild" : "Dokument";
          return [
            {
              key: `${entry.id}:${attachmentIndex}`,
              name: attachment.name,
              dataUrl: attachment.dataUrl,
              type: attachment.type,
              category: `${typeLabel}: ${category}`,
            },
          ];
        })
      );
  }

  function toggleDocumentMailProjectAttachmentSelection(key: string) {
    setSelectedDocumentMailProjectAttachmentKeys((current) =>
      current.includes(key) ? current.filter((item) => item !== key) : [...current, key]
    );
  }

  function closeDocumentMailProjectAttachmentPicker() {
    setIsDocumentMailProjectAttachmentPickerOpen(false);
    setSelectedDocumentMailProjectAttachmentKeys([]);
  }

  function addSelectedProjectDocumentMailAttachments() {
    const options = getDocumentMailProjectAttachmentOptions(documentMailDraft);
    const selectedOptions = options.filter((item) => selectedDocumentMailProjectAttachmentKeys.includes(item.key));
    if (!selectedOptions.length) return;
    const existingAttachments = documentMailDraft?.manualAttachments || [];
    const selectedAttachments = selectedOptions.map((option) => ({
      name: option.name,
      dataUrl: option.dataUrl,
      target: documentMailDraft?.hasActivityReportRecipientField
        ? documentMailDraft.activeMailTab === "activityReport"
          ? "activityReport" as const
          : "invoice" as const
        : undefined,
    }));
    const totalBytes = getDocumentMailManualAttachmentBytes([...existingAttachments, ...selectedAttachments]);
    const maxBytes = 15 * 1024 * 1024;

    if (totalBytes > maxBytes) {
      setDocumentMailError("Die ausgewählten Projektanhänge sind zusammen größer als 15 MB.");
      return;
    }

    setDocumentMailDraft((current) =>
      current
        ? {
            ...current,
            manualAttachments: [
              ...(current.manualAttachments || []),
              ...selectedAttachments,
            ],
          }
        : current
    );
    closeDocumentMailProjectAttachmentPicker();
    setDocumentMailError("");
  }

  function getNextCatalogNumber(type: CatalogItemType) {
    const prefix = type === "service" ? "L" : type === "package" ? "P" : "A";
    const current =
      catalogItems
        .filter((item) => item.number.startsWith(prefix))
        .map((item) => Number(item.number.replace(/\D/g, "")))
        .filter((value) => Number.isFinite(value))
        .sort((first, second) => second - first)[0] ?? 1000;

    return `${prefix}${String(current + 1).padStart(4, "0")}`;
  }

