  async function saveContact() {
    if (!activeUserId) {
      setErrorMessage("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }

    const normalizedContactDraft = {
      ...contactDraft,
      category:
        contactDraft.type === "person"
          ? "Ansprechpartner"
          : contactDraft.type === "private"
            ? "Privatkunde"
            : contactDraft.category === "Privatkunde" || contactDraft.category === "Ansprechpartner"
              ? "Kunde"
              : contactDraft.category,
      parentCompanyId: contactDraft.type === "person" ? contactDraft.parentCompanyId : "",
      parentCompanyName: contactDraft.type === "person" ? contactDraft.parentCompanyName : "",
    };
    if (normalizedContactDraft.type === "company" && !normalizedContactDraft.companyName.trim()) {
      setErrorMessage("Bitte einen Firmennamen angeben.");
      return;
    }
    if (
      normalizedContactDraft.type !== "company" &&
      !normalizedContactDraft.firstName.trim() &&
      !normalizedContactDraft.lastName.trim()
    ) {
      setErrorMessage("Bitte mindestens Vorname oder Nachname angeben.");
      return;
    }
    if (
      (normalizedContactDraft.type === "private" ||
        normalizedContactDraft.category === "Kunde" ||
        normalizedContactDraft.category === "Privatkunde") &&
      normalizedContactDraft.customerStatusOverride !== "automatic" &&
      !normalizedContactDraft.customerStatusOverrideReason.trim()
    ) {
      setErrorMessage("Bitte begründe die manuelle Kundenstatus-Einstufung.");
      return;
    }
    const res = await fetch("/api/contacts", {
      method: editingContactId ? "PATCH" : "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        ...normalizedContactDraft,
        id: editingContactId,
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Kontakt konnte nicht erstellt werden.");
      return;
    }

    const savedContact = (await res.json()) as ContactItem;
    setContacts((currentContacts) =>
      editingContactId
        ? currentContacts.map((contact) =>
            contact.id === savedContact.id ? savedContact : contact
          )
        : [savedContact, ...currentContacts]
    );
    if (editingContactId) {
      await Promise.all([
        loadCustomerLogbookEntries(savedContact.id),
        loadNotifications(false),
      ]);
    }
    setIsContactModalOpen(false);
    setEditingContactId(null);
    if (!editingContactId && projectContactTarget) {
      const targetKey =
        projectContactTarget === "person"
          ? "contactPersonId"
          : projectContactTarget === "address"
            ? "addressContactId"
            : "contactId";
      updateProjectDraft(targetKey, savedContact.id);
      setProjectContactTarget("");
    }
    setErrorMessage("");
  }

  async function deleteContact() {
    if (!editingContactId) return;
    if (!activeUserId) {
      setErrorMessage("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }

    const contactName = [contactDraft.firstName, contactDraft.lastName].filter(Boolean).join(" ");
    const confirmed = window.confirm(
      `Kontakt "${contactName || contactDraft.companyName || contactDraft.customerNumber}" wirklich löschen?`
    );
    if (!confirmed) return;

    const res = await fetch("/api/contacts", {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ id: editingContactId, actorId: activeUserId }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Kontakt konnte nicht gelöscht werden.");
      return;
    }

    setContacts((currentContacts) =>
      currentContacts.filter((contact) => contact.id !== editingContactId)
    );
    setIsContactModalOpen(false);
    setEditingContactId(null);
    setErrorMessage("");
  }

