  async function loadProjectLogbookEntries() {
    if (!activeUserId) return;

    const params = new URLSearchParams({ actorId: activeUserId, summary: "1" });
    const res = await fetch(`/api/project-logbook-entries?${params.toString()}`, {
      cache: "no-store",
    });

    if (!res.ok) {
      setLogbookError("Projekt-Logbucheinträge konnten nicht geladen werden.");
      return;
    }

    const data = (await res.json()) as ProjectLogbookEntrySummary[];
    setProjectLogbookEntries((currentEntries) =>
      (data as ProjectLogbookEntry[]).map((summaryEntry) => {
        const currentEntry = currentEntries.find((entry) => entry.id === summaryEntry.id);
        if (!currentEntry) return summaryEntry;

        const attachments = summaryEntry.attachments.map((attachment, attachmentIndex) => {
          if (attachment.dataUrl) return attachment;
          const currentAttachment = currentEntry.attachments[attachmentIndex];
          if (
            currentAttachment?.dataUrl &&
            currentAttachment.name === attachment.name &&
            currentAttachment.type === attachment.type
          ) {
            return { ...attachment, dataUrl: currentAttachment.dataUrl };
          }

          const matchingAttachment = currentEntry.attachments.find(
            (candidate) => candidate.name === attachment.name && candidate.type === attachment.type && candidate.dataUrl
          );
          return matchingAttachment ? { ...attachment, dataUrl: matchingAttachment.dataUrl } : attachment;
        });

        return { ...summaryEntry, attachments };
      })
    );
    setLogbookError("");
  }

  function getProjectLogbookUpdatedAfter(projectId: string) {
    return projectLogbookEntriesRef.current
      .filter((entry) => String(entry.projectId) === String(projectId))
      .map((entry) => new Date(entry.updatedAt || "").getTime())
      .filter(Number.isFinite)
      .sort((first, second) => second - first)[0];
  }

  async function loadProjectLogbookEntriesForProject(projectId: string, options: { onlyChanged?: boolean } = {}) {
    if (!projectId || !activeUserId) return;

    const updatedAfter = options.onlyChanged ? getProjectLogbookUpdatedAfter(projectId) : undefined;
    const params = new URLSearchParams({ projectId, actorId: activeUserId });
    if (updatedAfter) params.set("updatedAfter", new Date(updatedAfter).toISOString());

    const res = await fetch(`/api/project-logbook-entries?${params.toString()}`, { cache: "no-store" });

    if (!res.ok) return;

    const data = (await res.json()) as ProjectLogbookEntry[];
    if (options.onlyChanged && data.length === 0) return;

    setProjectLogbookEntries((currentEntries) => [
      ...data,
      ...currentEntries.filter((entry) =>
        options.onlyChanged
          ? !data.some((updatedEntry) => updatedEntry.id === entry.id)
          : String(entry.projectId) !== String(projectId)
      ),
    ]);
  }

  function getProjectLogbookSignature(entries: Array<ProjectLogbookEntry | ProjectLogbookEntrySummary>) {
    return entries
      .map((entry) => {
        const attachments = entry.attachments
          .map((attachment) => `${attachment.type}:${attachment.name}:${attachment.size || 0}`)
          .sort()
          .join(",");
        return `${entry.id}|${entry.title}|${entry.projectMonth || ""}|${entry.updatedAt || ""}|${attachments}`;
      })
      .sort()
      .join(";");
  }

  async function syncOpenProjectLogbookEntries(projectId: string) {
    if (!projectId || !activeUserId) return;

    const params = new URLSearchParams({ projectId, actorId: activeUserId, summary: "1" });
    const res = await fetch(`/api/project-logbook-entries?${params.toString()}`, { cache: "no-store" });

    if (!res.ok) return;

    const serverSummary = (await res.json()) as ProjectLogbookEntrySummary[];
    const currentProjectEntries = projectLogbookEntriesRef.current.filter(
      (entry) => String(entry.projectId) === String(projectId)
    );

    if (getProjectLogbookSignature(serverSummary) !== getProjectLogbookSignature(currentProjectEntries)) {
      await loadProjectLogbookEntriesForProject(projectId);
    }
  }

