  async function loadNotifications(showDesktopNotice = false) {
    if (!activeUserId) return;

    const res = await fetch(`/api/notifications?userId=${activeUserId}`, {
      cache: "no-store",
    });

    if (!res.ok) return;

    const data = (await res.json()) as AppNotification[];

    setNotifications((currentNotifications) => {
      const currentIds = new Set(currentNotifications.map((notification) => notification.id));
      const newUnreadNotifications = data.filter(
        (notification) => !notification.readAt && !currentIds.has(notification.id)
      );

      if (
        showDesktopNotice &&
        hasLoadedNotifications.current &&
        newUnreadNotifications.length > 0 &&
        typeof window !== "undefined" &&
        "Notification" in window &&
        window.Notification.permission === "granted"
      ) {
        newUnreadNotifications.slice(0, 3).forEach((notification) => {
          new window.Notification(notification.subject, {
            body: notification.body,
            tag: notification.id,
          });
        });
      }

      hasLoadedNotifications.current = true;
      return data;
    });
  }

  async function loadNotificationHistory(options?: { append?: boolean; search?: string }) {
    if (!activeUserId) return;
    const requestId = notificationHistoryRequestId.current + 1;
    notificationHistoryRequestId.current = requestId;
    const append = options?.append === true;
    const params = new URLSearchParams({
      userId: activeUserId,
      history: "true",
      limit: "50",
      offset: String(append ? notificationHistoryOffset : 0),
    });
    const search = (options?.search ?? notificationSearchTerm).trim();
    if (search) params.set("search", search);
    setIsNotificationHistoryLoading(true);
    try {
      const res = await fetch(`/api/notifications?${params.toString()}`, { cache: "no-store" });
      const data = (await res.json().catch(() => null)) as NotificationHistoryResponse | { error?: string } | null;
      if (requestId !== notificationHistoryRequestId.current) return;
      if (!res.ok || !data || !("items" in data)) {
        setErrorMessage(data && "error" in data && data.error ? data.error : "Benachrichtigungshistorie konnte nicht geladen werden.");
        return;
      }
      setNotificationHistory((current) => append ? [...current, ...data.items] : data.items);
      setNotificationHistoryHasMore(data.hasMore);
      setNotificationHistoryOffset(data.nextOffset);
    } finally {
      if (requestId === notificationHistoryRequestId.current) setIsNotificationHistoryLoading(false);
    }
  }

  function urlBase64ToUint8Array(value: string) {
    const padding = "=".repeat((4 - (value.length % 4)) % 4);
    const base64 = (value + padding).replace(/-/g, "+").replace(/_/g, "/");
    const rawData = window.atob(base64);
    return Uint8Array.from(Array.from(rawData).map((character) => character.charCodeAt(0)));
  }

  async function waitForDesktopPushStep<T>(promise: Promise<T>, timeoutMessage: string, timeoutMs = 15_000) {
    let timeoutId: ReturnType<typeof setTimeout> | undefined;
    const timeout = new Promise<never>((_resolve, reject) => {
      timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
    });

    try {
      return await Promise.race([promise, timeout]);
    } finally {
      if (timeoutId) clearTimeout(timeoutId);
    }
  }

  async function requestDesktopNotifications() {
    setDesktopPushMessage("");
    if (typeof window === "undefined" || !("Notification" in window) || !("serviceWorker" in navigator) || !("PushManager" in window)) {
      setDesktopPushStatus("unsupported");
      setDesktopPushMessage("Dieser Browser unterstützt keine Desktop-Push-Benachrichtigungen.");
      return;
    }
    if (!window.isSecureContext) {
      setDesktopPushStatus("unsupported");
      setDesktopPushMessage("Desktop-Push benötigt HTTPS oder localhost.");
      return;
    }
    setDesktopPushStatus("checking");
    try {
      setDesktopPushMessage("Browser-Berechtigung wird geprüft...");
      const permission = window.Notification.permission === "default"
        ? await waitForDesktopPushStep(
            window.Notification.requestPermission(),
            "Die Browser-Berechtigung antwortet nicht. Bitte die Website-Berechtigung prüfen und erneut versuchen."
          )
        : window.Notification.permission;
      setDesktopPermission(permission);
      if (permission !== "granted") {
        setDesktopPushStatus("blocked");
        setDesktopPushMessage("Benachrichtigungen sind im Browser blockiert. Bitte die Website-Berechtigung auf ‚Zulassen‘ stellen.");
        return;
      }
      setDesktopPushMessage("Push-Konfiguration wird geladen...");
      const keyResponse = await waitForDesktopPushStep(
        fetch("/api/push/public-key", { cache: "no-store" }),
        "Die Push-Konfiguration konnte nicht rechtzeitig geladen werden. Bitte erneut versuchen."
      );
      const keyData = (await keyResponse.json().catch(() => null)) as { configured?: boolean; publicKey?: string } | null;
      if (!keyResponse.ok || !keyData?.configured || !keyData.publicKey) {
        setDesktopPushStatus("unconfigured");
        setDesktopPushMessage("Web-Push ist auf diesem Server noch nicht konfiguriert.");
        return;
      }
      setDesktopPushMessage("Benachrichtigungsdienst wird vorbereitet...");
      const registration = await waitForDesktopPushStep(
        navigator.serviceWorker.register("/workpilot-sw.js", { scope: "/" }),
        "Der Benachrichtigungsdienst konnte nicht gestartet werden. Bitte die Seite neu laden und erneut versuchen."
      );
      await waitForDesktopPushStep(
        navigator.serviceWorker.ready,
        "Der Benachrichtigungsdienst antwortet nicht. Bitte die Seite neu laden und erneut versuchen."
      );
      setDesktopPushMessage("Gerät wird für Push-Benachrichtigungen registriert...");
      const existingSubscription = await waitForDesktopPushStep(
        registration.pushManager.getSubscription(),
        "Eine vorhandene Push-Registrierung konnte nicht gelesen werden. Bitte erneut versuchen."
      );
      const subscription = existingSubscription ?? await waitForDesktopPushStep(
        registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: urlBase64ToUint8Array(keyData.publicKey),
        }),
        "Die Push-Registrierung des Browsers antwortet nicht. Bitte die Website-Berechtigung prüfen und erneut versuchen."
      );
      setDesktopPushMessage("Push-Registrierung wird sicher gespeichert...");
      const subscriptionResponse = await waitForDesktopPushStep(
        fetch("/api/push/subscriptions", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ userId: activeUserId, userAgent: navigator.userAgent, subscription: subscription.toJSON() }),
        }),
        "Die Push-Registrierung konnte nicht rechtzeitig gespeichert werden. Bitte erneut versuchen."
      );
      const subscriptionData = await subscriptionResponse.json().catch(() => null);
      if (!subscriptionResponse.ok) throw new Error(subscriptionData?.error || "Push-Subscription konnte nicht gespeichert werden.");
      setDesktopPushStatus("active");
      setDesktopPushMessage("Desktop-Benachrichtigungen sind aktiv.");
    } catch (error) {
      setDesktopPushStatus("error");
      setDesktopPushMessage(error instanceof Error ? error.message : "Desktop-Benachrichtigungen konnten nicht aktiviert werden.");
    }
  }

  async function resetDesktopPushConnection() {
    setDesktopPushStatus("checking");
    setDesktopPushMessage("Alte Push-Verbindung wird zurückgesetzt...");
    try {
      if (!("serviceWorker" in navigator)) {
        throw new Error("Dieser Browser unterstützt keine Service Worker.");
      }
      const registrations = await waitForDesktopPushStep(
        navigator.serviceWorker.getRegistrations(),
        "Die vorhandenen Benachrichtigungsdienste konnten nicht gelesen werden. Bitte die Seite neu laden."
      );
      const workPilotRegistrations = registrations.filter((registration) =>
        registration.scope === `${window.location.origin}/` ||
        registration.active?.scriptURL.endsWith("/workpilot-sw.js") ||
        registration.waiting?.scriptURL.endsWith("/workpilot-sw.js") ||
        registration.installing?.scriptURL.endsWith("/workpilot-sw.js")
      );
      for (const registration of workPilotRegistrations) {
        const subscription = await waitForDesktopPushStep(
          registration.pushManager.getSubscription(),
          "Die alte Push-Registrierung konnte nicht gelesen werden."
        );
        if (subscription) {
          await waitForDesktopPushStep(
            subscription.unsubscribe(),
            "Die alte Push-Registrierung konnte nicht entfernt werden."
          );
        }
        await waitForDesktopPushStep(
          registration.unregister(),
          "Der alte Benachrichtigungsdienst konnte nicht entfernt werden."
        );
      }
      setDesktopPushStatus("idle");
      setDesktopPushMessage("Push-Verbindung wurde zurückgesetzt. Neuer Versuch startet...");
      await requestDesktopNotifications();
    } catch (error) {
      setDesktopPushStatus("error");
      setDesktopPushMessage(error instanceof Error ? error.message : "Die Push-Verbindung konnte nicht zurückgesetzt werden.");
    }
  }

  async function requestDesktopNotificationsLegacy() {
    if (typeof window === "undefined" || !("Notification" in window)) {
      setErrorMessage("Desktop-Benachrichtigungen werden von diesem Browser nicht unterstützt.");
      return;
    }

    const permission = await window.Notification.requestPermission();
    setDesktopPermission(permission);
  }

