  async function openNotificationTarget(notification: AppNotification) {
    if (
      (notification.linkTarget === "planning-entry" ||
        notification.linkTarget === "planning-entry-overlap") &&
      notification.linkTargetId
    ) {
      const entry = planningEntries.find((item) => item.id === notification.linkTargetId);
      if (entry) {
        setSelectedPlanningDateKey(entry.date);
        setSelectedPlanningBoard(entry.board);
        setSelectedPlanningGroup(entry.groupName);
        setIsPlanningDayOpen(true);
        setActiveTab("planningBoard");
        setIsNotificationsOpen(false);
        openEditPlanningEntryModal(entry);
      }
    }

    if (notification.linkTarget === "planning-entry-overcapacity" && notification.linkTargetId) {
      const [userId, date] = notification.linkTargetId.split(":");
      const entry = planningEntries.find(
        (item) =>
          !item.deletedAt &&
          item.approvalStatus === "confirmed" &&
          item.userId === userId &&
          item.date === date
      );
      if (entry) {
        setSelectedPlanningDateKey(entry.date);
        setSelectedPlanningBoard(entry.board);
        setSelectedPlanningGroup(entry.groupName);
        setIsPlanningDayOpen(true);
        setActiveTab("planningBoard");
      }
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "daily-planning-reminder" && notification.linkTargetId) {
      setActiveTab("dashboard");
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "content-item" && notification.linkTargetId) {
      if (!CONTENT_MANAGEMENT_ENABLED) {
        setIsNotificationsOpen(false);
        return;
      }

      let entry = contentItems.find((item) => item.id === notification.linkTargetId);
      if (!entry) {
        const loadedItems = await loadContentItems();
        entry = loadedItems.find((item) => item.id === notification.linkTargetId);
      }
      if (entry) {
        const targetTab =
          getReadableContentStatus(entry.status) === "Korrektur nötig"
            ? "contentCorrections"
            : entry.status === "Richtungsfreigabe offen" || entry.status === "Finale Freigabe offen"
              ? "contentApprovals"
              : "editorialPlan";
        setActiveTab(targetTab);
        setOpenSidebarMenus({ contentManagement: true });
        setIsNotificationsOpen(false);
        openContentModal(entry);
      }
    }

    if (notification.linkTarget === "idea-store") {
      if (!CONTENT_MANAGEMENT_ENABLED) {
        setIsNotificationsOpen(false);
        return;
      }

      await loadIdeaPosts();
      setActiveTab("ideaStore");
      setOpenSidebarMenus({ contentManagement: true });
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "news-feed") {
      await loadNewsFeed();
      setActiveTab("newsFeed");
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "customer" && notification.linkTargetId) {
      const customer = contacts.find((contact) => contact.id === notification.linkTargetId);
      if (customer) {
        openCustomerFile(customer);
      } else {
        setSelectedCustomerFileId(notification.linkTargetId);
        setCustomerFileTab("logbook");
      }
      setActiveTab("contacts");
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "task" && notification.linkTargetId) {
      let task = tasks.find((item) => item.id === notification.linkTargetId);
      if (!task) {
        const loadedTasks = await loadTasks();
        task = loadedTasks.find((item) => item.id === notification.linkTargetId);
      }
      if (task) {
        setActiveTab("dashboard");
        setOpenSidebarMenus({ tasks: true });
        setIsNotificationsOpen(false);
        openEditModal(task);
      }
    }

    if (notification.linkTarget === "project-logbook" && notification.linkTargetId) {
      await loadProjectLogbookEntries();
      const notificationProject = heroProjects.find((project) => project.id === notification.linkTargetId);
      if (notificationProject) {
        openProjectFile(notificationProject, { tab: "logbook" });
      } else {
        setSelectedProjectFileId(notification.linkTargetId);
        setProjectFileTab("logbook");
        setActiveTab("projectsSolutions");
      }
      setProjectLogbookSearch("Zusatzverkauf");
      setOpenSidebarMenus({ projectsSolutions: true });
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "project" && notification.linkTargetId) {
      const notificationProject = heroProjects.find((project) => project.id === notification.linkTargetId);
      if (notificationProject) {
        openProjectFile(notificationProject, { tab: "documents", documentType: "Rechnungen" });
      } else {
        setSelectedProjectFileId(notification.linkTargetId);
        setProjectFileTab("documents");
        setSelectedProjectDocumentType("Rechnungen");
        setActiveTab("projectsSolutions");
      }
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "project-endphase" && notification.linkTargetId) {
      const notificationProject = heroProjects.find((project) => project.id === notification.linkTargetId);
      if (notificationProject) {
        openProjectFile(notificationProject, { tab: "logbook" });
      } else {
        setSelectedProjectFileId(notification.linkTargetId);
        setProjectFileTab("logbook");
        setActiveTab("projectsSolutions");
      }
      setOpenSidebarMenus({ projectsSolutions: true });
      setIsNotificationsOpen(false);
    }

    if (notification.linkTarget === "project-potential" && notification.linkTargetId) {
      let potential = projectPotentials.find((item) => item.id === notification.linkTargetId);
      if (!potential) {
        const loadedPotentials = await loadProjectPotentials();
        potential = loadedPotentials.find((item) => item.id === notification.linkTargetId);
      }

      setActiveTab("salesOpportunities");
      setPotentialStatusFilter("all");
      setIsNotificationsOpen(false);
      if (potential) openPotentialDetail(potential);
    }

    if (notification.linkTarget === "absence-request" && notification.linkTargetId) {
      let targetAbsence = absences.find(
        (absence) => (absence.requestGroupId || absence.id) === notification.linkTargetId
      );

      if (!targetAbsence) {
        const loadedAbsences = await loadAbsences();
        targetAbsence = loadedAbsences.find(
          (absence) => (absence.requestGroupId || absence.id) === notification.linkTargetId
        );
      }

      setActiveTab("absenceRequests");
      setAbsenceRequestView(
        targetAbsence?.status === "genehmigt" || targetAbsence?.status === "abgelehnt" ? "history" : "active"
      );
      setHighlightedAbsenceRequestId(notification.linkTargetId);
      setIsNotificationsOpen(false);
      if (targetAbsence) openEditAbsenceModal(targetAbsence);
    }
  }

  async function saveAbsence() {
    setAbsenceWarning("");

    if (!absenceRepresentativeUserId) {
      setAbsenceWarning("Bitte einen Vertreter auswählen. Eine Abwesenheit kann nur mit Vertreter gespeichert werden.");
      return;
    }

    if (!isAbsenceHandoverComplete) {
      setAbsenceWarning("Bitte die Aufgabenübergabe vollständig ausfüllen und bestätigen.");
      return;
    }

    const res = await fetch("/api/absences", {
      method: editingAbsenceId ? "PATCH" : "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        absenceId: editingAbsenceId,
        actorId: activeUserId,
        userId: absenceUserId,
        dateFrom: absenceDateFrom,
        dateTo: absenceDateTo,
        type: absenceType,
        dayPart: absenceDayPart,
        representativeUserId: absenceRepresentativeUserId || null,
        note: absenceNote,
        handoverTaskIds: absenceHandoverMode === "open" ? absenceHandoverTaskIds : [],
        handoverChecklist: [],
        handoverConfirmed: isAbsenceHandoverComplete,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setAbsenceWarning(data?.error ?? "Abwesenheit konnte nicht gespeichert werden.");
      return;
    }

    setAbsenceNote("");
    setAbsenceDayPart("full");
    setAbsenceHandoverMode("open");
    setAbsenceHandoverTaskIds([]);
    setAcceptedHandoverTaskIds([]);
    setPendingHandoverTaskIds([]);
    setEditingAbsenceId(null);
    setAbsenceChecklist(vacationHandoverItems.map(() => false));
    setAbsenceHandoverConfirmed(false);
    setAbsenceWarning("");
    setIsAbsenceModalOpen(false);
    await loadAbsences();
    await loadNotifications(true);
  }

  async function updateAbsenceRequest(absence: AbsenceItem, action: "accept-representation" | "final-approve" | "reject") {
    const reason =
      action === "reject"
        ? window.prompt("Bitte Begründung für die Ablehnung angeben:")?.trim()
        : "";

    if (action === "reject" && !reason) {
      setErrorMessage("Bitte eine Begründung für die Ablehnung angeben.");
      return;
    }

    const res = await fetch("/api/absences", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        absenceId: absence.id,
        action,
        reason,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      const message = data?.error ?? "Abwesenheitsantrag konnte nicht aktualisiert werden.";
      setAbsenceWarning(message);
      setErrorMessage(message);
      return;
    }

    await loadAbsences();
    await loadNotifications(true);
    setAbsenceWarning("");
    setEditingAbsenceId(null);
    setIsAbsenceModalOpen(false);
  }

  async function acceptAbsenceHandoverTask(event: MouseEvent<HTMLButtonElement>, task: TaskItem) {
    event.stopPropagation();
    setErrorMessage("");
    setAbsenceWarning("");
    setPendingHandoverTaskIds((current) => (current.includes(task.id) ? current : [...current, task.id]));

    const res = await fetch("/api/tasks/respond", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId: task.id,
        actorId: activeUserId,
        response: "accepted",
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      const message = data?.error ?? "Übergabe-Aufgabe konnte nicht akzeptiert werden.";
      setAbsenceWarning(message);
      setErrorMessage(message);
      setPendingHandoverTaskIds((current) => current.filter((taskId) => taskId !== task.id));
      return;
    }

    setAcceptedHandoverTaskIds((current) => (current.includes(task.id) ? current : [...current, task.id]));
    setPendingHandoverTaskIds((current) => current.filter((taskId) => taskId !== task.id));
    setTasks((currentTasks) =>
      currentTasks.map((currentTask) =>
        currentTask.id === task.id
          ? {
              ...currentTask,
              acceptanceStatus: "accepted",
              acceptanceRespondedAt: new Date().toISOString(),
              rejectionReason: "",
              zustaendigId: activeUserId,
              zustaendig: activeUser?.name ?? currentTask.zustaendig,
            }
          : currentTask
      )
    );
    const currentAbsence = absences.find((absence) => absence.id === editingAbsenceId);
    const allHandoverTasksAccepted = absenceHandoverTaskIds.every((handoverTaskId) => {
      if (handoverTaskId === task.id) return true;
      return tasks.find((currentTask) => currentTask.id === handoverTaskId)?.acceptanceStatus === "accepted";
    });

    if (
      currentAbsence &&
      currentAbsence.status === "wartet_vertreter" &&
      allHandoverTasksAccepted
    ) {
      await updateAbsenceRequest(currentAbsence, "accept-representation");
    }

    await loadTasks();
    await loadAbsences();
    await loadNotifications(true);
  }

  async function deleteAbsence(absenceId: string) {
    const confirmed = window.confirm("Abwesenheit wirklich löschen?");
    if (!confirmed) return;

    const res = await fetch("/api/absences", {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        actorId: activeUserId,
        absenceId,
        dateFrom: absenceDateFrom,
        dateTo: absenceDateTo,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Abwesenheit konnte nicht entfernt werden.");
      return;
    }

    await loadAbsences();
    await loadNotifications(true);
    setEditingAbsenceId(null);
    setIsAbsenceModalOpen(false);
  }

