  function openPlanningEntryModal(options: Partial<{
    board: PlanningBoardCompany;
    groupName: string;
    date: string;
    userId: string;
    startTime: string;
    endTime: string;
    approvalStatus: PlanningEntryApprovalStatus;
    requireManualAssignment: boolean;
    requireManualGroup: boolean;
  }> = {}) {
    const approvalStatus = options.approvalStatus ?? "confirmed";
    if (!mayManagePlanningEntries && approvalStatus !== "requested") {
      setErrorMessage("Mitarbeiter können nur eigene Terminwünsche anlegen.");
      return;
    }

    const isOwnEmployeeRequest = !mayManagePlanningEntries && approvalStatus === "requested";
    const shouldRequireManualAssignment = options.requireManualAssignment === true;
    const shouldRequireManualGroup = options.requireManualGroup === true;
    const ownBoard: PlanningBoardCompany =
      activeUser?.planningBoard === "OK immocare" ? "OK immocare" : "OK solutions";
    const board = isOwnEmployeeRequest
      ? ownBoard
      : shouldRequireManualAssignment
        ? ""
        : options.board ?? "OK solutions";
    const groups = getPlanningEntryGroups(board);
    const preferredGroup = isOwnEmployeeRequest ? activeUser?.planningGroup ?? "" : options.groupName ?? "";
    const groupName = shouldRequireManualGroup
      ? ""
      : groups.includes(preferredGroup)
        ? preferredGroup
        : groups[0] ?? "";
    const startTime = options.startTime ?? "08:00";
    const startTimeIndex = planningTimelineSlots.indexOf(startTime);
    const endTime =
      options.endTime ??
      planningTimelineSlots[Math.min(startTimeIndex >= 0 ? startTimeIndex + 4 : 4, planningTimelineSlots.length - 1)] ??
      "09:00";
    const defaultUserId = isOwnEmployeeRequest ? activeUserId : options.userId ?? "";

    resetPlanningEntryForm();
    setPlanningEntryApprovalStatus(approvalStatus);
    setPlanningEntryBoard(board);
    setPlanningEntryGroup(groupName);
    const nextPlanningDate = options.date ?? formatDateKey(new Date());
    setPlanningEntryDate(nextPlanningDate);
    setPlanningRecurrenceWeekdays([getWeekdayFromDateKey(nextPlanningDate)]);
    setPlanningEntryUserId(defaultUserId);
    setPlanningEntryStartTime(startTime);
    setPlanningEntryEndTime(endTime);
    setErrorMessage("");
    setPlanningEntryError("");
    setIsPlanningEntryModalOpen(true);
  }

  function canModifyPlanningEntry(entry: PlanningEntry) {
    const mayEditOwnRequest =
      entry.approvalStatus === "requested" &&
      (entry.userId === activeUserId || entry.requestedByUserId === activeUserId);
    return mayManagePlanningEntries || mayEditOwnRequest;
  }

  function openEditPlanningEntryModal(entry: PlanningEntry) {
    if (!canModifyPlanningEntry(entry)) {
      setErrorMessage("Mitarbeiter können nur eigene offene Terminwünsche bearbeiten.");
      return;
    }

    const board = (entry.board === "OK immocare" ? "OK immocare" : "OK solutions") as PlanningBoardCompany;
    const groups = getPlanningEntryGroups(board);
    const groupName = groups.includes(entry.groupName) ? entry.groupName : groups[0];

    const entryProject = heroProjects.find((project) => project.id === entry.projectId);
    const entryProjectHasOfferPlanning =
      entryProject &&
      !getProjectKind(entryProject).startsWith("Dauer") &&
      offers.some(
        (offer) =>
          offer.projectId === entryProject.id &&
          offer.status !== "Entwurf" &&
          getOfferLaborPlanningHours(offer) > 0
      );
    const entryHasOfferReference = entry.source === "offer" || Boolean(entry.offerId || entry.offerLabel);

    setEditingPlanningEntryId(entry.id);
    setPlanningEntryApprovalStatus(entry.approvalStatus);
    setPlanningEntrySource(entryHasOfferReference || entryProjectHasOfferPlanning ? "offer" : "manual");
    setPlanningEntryBoard(board);
    setPlanningEntryGroup(groupName);
    setPlanningEntryUserId(entry.userId);
    setPlanningEntryDate(entry.date);
    setPlanningRecurrenceWeekdays([getWeekdayFromDateKey(entry.date)]);
    setPlanningEntryStartTime(entry.startTime);
    setPlanningEntryEndTime(entry.endTime);
    setPlanningEntryTitle(entry.title);
    setPlanningEntryCustomer(entry.customer);
    setPlanningEntryProjectId(entry.projectId);
    setPlanningEntryObjectAddressId(entry.objectAddressId || "");
    setPlanningEntryTrade(entry.planningTrade);
    setPlanningEntryBillingCatalogItemId(entry.billingCatalogItemId);
    setPlanningEntryHasAdditionalEmployees("no");
    setPlanningEntryAdditionalUserIds([]);
    setPlanningEntryProjectSearch(entry.projectLabel || entry.customer || "");
    setIsPlanningEntryProjectSearchOpen(false);
    setPlanningEntryDescription(entry.description);
    setPlanningEntryOfferLabel(entry.offerLabel);
    setPlanningEntryOfferId(entry.offerId);
    setPlanningEntryOfferLineId(entry.offerLineId);
    setPlanningEntryOfferTotalHours(
      entry.offerTotalMinutes > 0 ? String(entry.offerTotalMinutes / 60) : "5"
    );
    if (entryProject && isHourlyRecurringProject(entryProject) && catalogItems.length === 0) void loadCatalogItems();
    setPlanningRecurrenceType("once");
    setPlanningRecurrenceUntil("");
    setErrorMessage("");
    setPlanningEntryError("");
    setIsPlanningEntryModalOpen(true);
  }

  function getPlanningBoardForGroup(groupName: string): PlanningBoardCompany {
    return groupName === "VZK" || groupName === "TZK" ? "OK immocare" : "OK solutions";
  }

  function getPlanningSlotTimeFromClick(event: MouseEvent<HTMLDivElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    const relativeX = Math.max(0, Math.min(rect.width, event.clientX - rect.left));
    const slotIndex = Math.max(
      0,
      Math.min(planningSlotColumnCount - 1, Math.floor((relativeX / rect.width) * planningSlotColumnCount))
    );
    const totalMinutes = 6 * 60 + slotIndex * 15;
    return `${String(Math.floor(totalMinutes / 60)).padStart(2, "0")}:${String(totalMinutes % 60).padStart(2, "0")}`;
  }

  function openPlanningSlotAction(event: MouseEvent<HTMLDivElement>, employeeUser?: UserOption) {
    if (selectedPlanningIsWeekend || selectedPlanningHoliday) return;

    const employeeBoard: PlanningBoardCompany =
      employeeUser?.planningBoard === "OK immocare" ? "OK immocare" : selectedPlanningBoard;
    const employeeGroup = getSelectedPlanningGroupForUser(employeeUser);
    if (!employeeGroup) return;

    setPlanningSlotAction({
      date: selectedPlanningDateKey,
      board: employeeBoard,
      groupName: employeeGroup,
      userId: employeeUser?.id ?? "",
      employeeName: employeeUser?.name ?? "",
      startTime: getPlanningSlotTimeFromClick(event),
      approvalStatus: "",
      projectSearch: "",
    });
  }

  function openPlanningEntryFromSlot(project?: HeroProjectPreview | null) {
    if (!planningSlotAction || !planningSlotAction.approvalStatus) return;

    const projectBoard = project ? getProjectCompany(project) : planningSlotAction.board;
    const groupOptions = getPlanningEntryGroups(projectBoard);
    const groupName = groupOptions.includes(planningSlotAction.groupName)
      ? planningSlotAction.groupName
      : groupOptions[0];
    const selectedUser =
      users.find(
        (user) =>
          user.isActive &&
          user.id === planningSlotAction.userId &&
          (user.planningBoard ?? "OK solutions") === projectBoard &&
          (user.planningGroup ?? "") === groupName
      ) ??
      users.find(
        (user) =>
          user.isActive &&
          (user.planningBoard ?? "OK solutions") === projectBoard &&
          (user.planningGroup ?? "") === groupName
      );
    const projectHasOfferPlanning =
      project &&
      !getProjectKind(project).startsWith("Dauer") &&
      offers.some(
        (offer) =>
          offer.projectId === project.id &&
          offer.status !== "Entwurf" &&
          getOfferLaborPlanningHours(offer) > 0
      );

    openPlanningEntryModal({
      board: projectBoard,
      groupName,
      date: planningSlotAction.date,
      userId: selectedUser?.id ?? planningSlotAction.userId,
      startTime: planningSlotAction.startTime,
      approvalStatus: planningSlotAction.approvalStatus,
    });

    setPlanningEntrySource(projectHasOfferPlanning ? "offer" : "manual");
    if (project) {
      setPlanningEntryProjectId(project.id);
      setPlanningEntryObjectAddressId(project.objectAddressId || "");
      setPlanningEntryCustomer(project.customer || "");
      setPlanningEntryProjectSearch(`${project.projectNumber || project.id} | ${project.title}`);
      setPlanningEntryTrade(isHourlyRecurringProject(project) ? project.trade || "" : "");
      setPlanningEntryBillingCatalogItemId("");
      setPlanningEntryHasAdditionalEmployees(isHourlyRecurringProject(project) ? "" : "no");
      setPlanningEntryAdditionalUserIds([]);
      if (isHourlyRecurringProject(project) && catalogItems.length === 0) void loadCatalogItems();
    } else {
      setPlanningEntryProjectId("");
      setPlanningEntryObjectAddressId("");
      setPlanningEntryCustomer("");
      setPlanningEntryProjectSearch("");
      setPlanningEntryTrade("");
      setPlanningEntryBillingCatalogItemId("");
      setPlanningEntryHasAdditionalEmployees("");
      setPlanningEntryAdditionalUserIds([]);
    }
    setIsPlanningEntryProjectSearchOpen(false);
    setPlanningSlotAction(null);
  }

  function entryOrFallbackRequestedByUserId() {
    if (!editingPlanningEntryId) return activeUserId;
    return planningEntries.find((entry) => entry.id === editingPlanningEntryId)?.requestedByUserId || activeUserId;
  }

  function entryOrFallbackRequestedByName() {
    if (!editingPlanningEntryId) return activeUser?.name ?? "";
    return planningEntries.find((entry) => entry.id === editingPlanningEntryId)?.requestedByName || activeUser?.name || "";
  }

  function shouldShowPlanningOfferAssignment() {
    const selectedProject = heroProjects.find((project) => project.id === planningEntryProjectId);
    if (!selectedProject || getProjectKind(selectedProject).startsWith("Dauer")) return false;
    return offers.some(
      (offer) =>
        offer.projectId === selectedProject.id &&
        offer.status !== "Entwurf" &&
        getOfferLaborPlanningHours(offer) > 0
    );
  }

  function getAlreadyPlannedOfferMinutesForPlanningEntry() {
    const normalizedOfferLabel = planningEntryOfferLabel.trim().toLowerCase();
    const normalizedTitle = planningEntryTitle.trim().toLowerCase();
    const selectedOffer = planningEntryOfferId
      ? offers.find((offer) => offer.id === planningEntryOfferId)
      : null;

    return planningEntries
      .filter(
        (entry) => {
          if (
            entry.projectId !== planningEntryProjectId ||
            entry.id === editingPlanningEntryId ||
            entry.deletedAt
          ) {
            return false;
          }

          if (planningEntryOfferId) {
            if (entry.offerId === planningEntryOfferId) return true;
            if (!selectedOffer) return false;
            const haystack = [entry.title, entry.description, entry.offerLabel].join(" ").toLowerCase();
            if (haystack.includes(selectedOffer.offerNumber.toLowerCase())) return true;
            if (entry.offerId || entry.offerLabel) return false;
            const offersInEntryMonth = offers.filter(
              (offer) =>
                offer.projectId === planningEntryProjectId &&
                offer.status !== "Entwurf" &&
                offer.plannedExecutionMonth === entry.date.slice(0, 7) &&
                getOfferLaborPlanningHours(offer) > 0
            );
            return offersInEntryMonth.length === 1 && offersInEntryMonth[0].id === selectedOffer.id;
          }

          const haystack = [entry.title, entry.description, entry.offerLabel].join(" ").toLowerCase();
          if (normalizedOfferLabel && haystack.includes(normalizedOfferLabel)) return true;
          if (normalizedTitle && haystack.includes(normalizedTitle)) return true;

          return false;
        }
      )
      .reduce((sum, entry) => sum + Number(entry.offerPlannedMinutes || entry.durationMinutes || 0), 0);
  }

  function getHourlyPlanningServiceOptions(trade: string) {
    const normalizedTrade = normalizeTradeName(trade);
    return catalogItems
      .filter((item) => {
        if (!item.isActive || item.type !== "service") return false;
        if (normalizeUnit(item.unit) !== "Std") return false;
        if (Number(item.salesPrice || 0) <= 0) return false;
        return normalizedTrade ? normalizeTradeName(item.trade) === normalizedTrade : false;
      })
      .sort((first, second) => first.name.localeCompare(second.name, "de"));
  }

  function getPlanningBillingCatalogItemLabel(item?: CatalogItem | null) {
    if (!item) return "";
    return `${item.number} | ${item.name}`;
  }

  function getAdditionalPlanningUserOptions() {
    return users.filter(
      (user) =>
        user.isActive &&
        user.id !== planningEntryUserId &&
        (user.planningBoard ?? "OK solutions") === planningEntryBoard &&
        (user.planningGroup ?? "") === planningEntryGroup
    );
  }

  function getWeekdayFromDateKey(dateKey: string) {
    return parseProjectDate(dateKey)?.getDay() ?? 1;
  }

  function setPlanningDateAndDefaultWeekday(dateKey: string) {
    setPlanningEntryDate(dateKey);
    if (planningRecurrenceType === "once" || planningRecurrenceWeekdays.length === 0) {
      setPlanningRecurrenceWeekdays([getWeekdayFromDateKey(dateKey)]);
    }
  }

  function togglePlanningRecurrenceWeekday(weekday: number) {
    if (editingPlanningEntryId || planningRecurrenceType === "once") return;
    setPlanningRecurrenceWeekdays((currentWeekdays) => {
      if (currentWeekdays.includes(weekday)) {
        const nextWeekdays = currentWeekdays.filter((currentWeekday) => currentWeekday !== weekday);
        return nextWeekdays.length > 0 ? nextWeekdays : currentWeekdays;
      }

      return [...currentWeekdays, weekday].sort((first, second) => {
        const firstIndex = planningWeekdayOptions.findIndex((option) => option.value === first);
        const secondIndex = planningWeekdayOptions.findIndex((option) => option.value === second);
        return firstIndex - secondIndex;
      });
    });
  }

  function getPlanningRecurrenceWeekdayOccurrence(date: Date) {
    let occurrence = 0;
    for (let day = 1; day <= date.getDate(); day += 1) {
      const currentDate = new Date(date.getFullYear(), date.getMonth(), day);
      if (currentDate.getDay() === date.getDay()) {
        occurrence += 1;
      }
    }
    return Math.max(1, occurrence);
  }

  function getMonthlyPlanningDate(year: number, month: number, weekday: number, occurrence: number) {
    let matchingDate: Date | null = null;
    let matchCount = 0;
    const lastDay = new Date(year, month + 1, 0).getDate();

    for (let day = 1; day <= lastDay; day += 1) {
      const currentDate = new Date(year, month, day);
      if (currentDate.getDay() !== weekday) continue;
      matchCount += 1;
      matchingDate = currentDate;
      if (matchCount === occurrence) {
        return currentDate;
      }
    }

    return matchingDate;
  }

  function getPlanningRecurrenceDates() {
    if (editingPlanningEntryId || planningRecurrenceType === "once") return [planningEntryDate];
    if (!planningRecurrenceUntil || planningRecurrenceUntil < planningEntryDate) return [planningEntryDate];

    const dates: string[] = [];
    const startDate = parseProjectDate(planningEntryDate);
    const currentDate = parseProjectDate(planningEntryDate);
    const untilDate = parseProjectDate(planningRecurrenceUntil);
    if (!startDate || !currentDate || !untilDate) return [planningEntryDate];

    const selectedWeekdays =
      planningRecurrenceWeekdays.length > 0 ? planningRecurrenceWeekdays : [startDate.getDay()];

    if (planningRecurrenceType === "monthly") {
      const occurrence = getPlanningRecurrenceWeekdayOccurrence(startDate);
      const currentMonth = new Date(startDate.getFullYear(), startDate.getMonth(), 1);

      while (currentMonth.getTime() <= untilDate.getTime() && dates.length < 120) {
        selectedWeekdays.forEach((weekday) => {
          const monthlyDate = getMonthlyPlanningDate(
            currentMonth.getFullYear(),
            currentMonth.getMonth(),
            weekday,
            occurrence
          );
          if (!monthlyDate) return;
          if (monthlyDate.getTime() < startDate.getTime() || monthlyDate.getTime() > untilDate.getTime()) return;
          dates.push(formatDateKey(monthlyDate));
        });
        currentMonth.setMonth(currentMonth.getMonth() + 1);
      }

      return dates.length > 0 ? Array.from(new Set(dates)).sort() : [planningEntryDate];
    }

    const intervalWeeks = planningRecurrenceType === "biweekly" ? 2 : 1;

    while (currentDate.getTime() <= untilDate.getTime() && dates.length < 120) {
      const daysSinceStart = Math.floor((currentDate.getTime() - startDate.getTime()) / (24 * 60 * 60 * 1000));
      const weeksSinceStart = Math.floor(daysSinceStart / 7);
      if (weeksSinceStart % intervalWeeks === 0 && selectedWeekdays.includes(currentDate.getDay())) {
        dates.push(formatDateKey(currentDate));
      }

      currentDate.setDate(currentDate.getDate() + 1);
    }

    return dates.length > 0 ? dates : [planningEntryDate];
  }

  function getPlanningRecurrenceLabel() {
    const recurrenceTypeForLabel: PlanningRecurrenceType = planningRecurrenceType;
    const weekdayLabel = (planningRecurrenceWeekdays.length > 0
      ? planningRecurrenceWeekdays
      : [getWeekdayFromDateKey(planningEntryDate)]
    )
      .map((weekday) => planningWeekdayOptions.find((option) => option.value === weekday)?.label)
      .filter(Boolean)
      .join(", ");
    if (recurrenceTypeForLabel === "weekly") return `woechentlich ${weekdayLabel}`;
    if (recurrenceTypeForLabel === "biweekly") return `alle 2 Wochen ${weekdayLabel}`;
    if (recurrenceTypeForLabel === "monthly") return `monatlich ${weekdayLabel}`;
    if (planningRecurrenceType === "weekly") return "wöchentlich";
    if (planningRecurrenceType === "biweekly") return "alle 2 Wochen";
    if (planningRecurrenceType === "monthly") return "monatlich";
    return "einmalig";
  }

  async function savePlanningEntry(nextApprovalStatus = planningEntryApprovalStatus) {
    setPlanningEntryError("");
    setErrorMessage("");
    const selectedUser = users.find((user) => user.id === planningEntryUserId);
    const selectedProject = heroProjects.find((project) => project.id === planningEntryProjectId);
    const planningProjectAddress = getProjectPlanningAddress(selectedProject);
    const requiresHourlyPlanningFields = Boolean(selectedProject && isHourlyRecurringProject(selectedProject));
    const hourlyPlanningServiceOptions = getHourlyPlanningServiceOptions(planningEntryTrade);
    const selectedBillingCatalogItem = planningEntryBillingCatalogItemId
      ? catalogItems.find((item) => item.id === planningEntryBillingCatalogItemId)
      : null;
    const selectedAdditionalUsers =
      planningEntryHasAdditionalEmployees === "yes"
        ? users.filter((user) => planningEntryAdditionalUserIds.includes(user.id) && user.isActive)
        : [];
    const durationMinutes = getPlanningNetMinutesBetween(
      planningEntryStartTime,
      planningEntryEndTime,
      getUserBreakWindowForDate(selectedUser, planningEntryDate)
    );
    const offerTotalMinutes = Math.round(Number(planningEntryOfferTotalHours) * 60);
    const title = planningEntryTitle.trim();
    const description = planningEntryDescription.trim();
    const selectedAbsence = planningEntryUserId
      ? getUserAbsenceForDateKey(planningEntryUserId, planningEntryDate)
      : undefined;
    const recurrenceDates = getPlanningRecurrenceDates();
    const recurrenceId =
      !editingPlanningEntryId && recurrenceDates.length > 1 ? crypto.randomUUID() : "";
    const recurrenceRule =
      recurrenceDates.length > 1
        ? `${getPlanningRecurrenceLabel()} bis ${formatProjectDate(recurrenceDates.at(-1))}`
        : "";

    if (!planningEntryBoard) {
      setPlanningEntryError("Bitte ein Planungsboard auswählen.");
      return;
    }

    if (!planningEntryGroup) {
      setPlanningEntryError("Bitte eine Planungsgruppe auswählen.");
      return;
    }

    if (!isValidDateKeyValue(planningEntryDate)) {
      setPlanningEntryError("Bitte ein gültiges Datum auswählen.");
      return;
    }

    if (!selectedUser) {
      setPlanningEntryError("Bitte einen Mitarbeiter zuweisen.");
      return;
    }

    if (!title) {
      setPlanningEntryError("Bitte einen Titel eintragen.");
      return;
    }

    if (!description) {
      setPlanningEntryError("Bitte eine Beschreibung eintragen.");
      return;
    }

    if (planningEntryBoard === "OK immocare" && selectedProject) {
      if (!planningProjectAddress) {
        setPlanningEntryError("Für dieses Immocare-Projekt ist noch keine Einsatzadresse hinterlegt.");
        return;
      }
    }

    if (requiresHourlyPlanningFields) {
      if (!planningEntryTrade.trim()) {
        setPlanningEntryError("Bitte ein Termin-Gewerk für diese Stundenabrechnung auswählen.");
        return;
      }

      if (!selectedBillingCatalogItem) {
        setPlanningEntryError("Bitte eine konkrete Abrechnungsleistung für diese Stundenabrechnung auswählen.");
        return;
      }

      if (!hourlyPlanningServiceOptions.some((item) => item.id === selectedBillingCatalogItem.id)) {
        setPlanningEntryError("Die ausgewaehlte Abrechnungsleistung passt nicht zum Termin-Gewerk.");
        return;
      }

      if (!planningEntryHasAdditionalEmployees) {
        setPlanningEntryError("Bitte auswählen, ob weitere Mitarbeiter für diesen Termin eingeplant werden.");
        return;
      }

      if (planningEntryHasAdditionalEmployees === "yes" && selectedAdditionalUsers.length === 0) {
        setPlanningEntryError("Bitte mindestens einen weiteren Mitarbeiter auswählen.");
        return;
      }
    }

    const isSingleProjectWithOfferPlanning =
      selectedProject &&
      !getProjectKind(selectedProject).startsWith("Dauer") &&
      offers.some((offer) => {
        if (offer.projectId !== selectedProject.id || offer.status === "Entwurf") return false;
        return getOfferLaborPlanningHours(offer) > 0;
      });
    const selectedPlanningOffer = planningEntryOfferId
      ? offers.find((offer) => offer.id === planningEntryOfferId)
      : null;
    const previousPlanningEntry = editingPlanningEntryId
      ? planningEntries.find((entry) => entry.id === editingPlanningEntryId)
      : null;
    const planningBillingGroupId =
      requiresHourlyPlanningFields ? previousPlanningEntry?.billingGroupId || crypto.randomUUID() : "";

    if (isSingleProjectWithOfferPlanning && !selectedPlanningOffer) {
      setPlanningEntryError("Bitte ein Angebot für diese Planung auswählen.");
      return;
    }

    if (selectedProject && selectedPlanningOffer && !getProjectKind(selectedProject).startsWith("Dauer")) {
      const targetExecutionMonth = planningEntryDate.slice(0, 7);
      const currentExecutionMonth = selectedPlanningOffer.plannedExecutionMonth || "";
      if (targetExecutionMonth && currentExecutionMonth && targetExecutionMonth !== currentExecutionMonth) {
        const confirmed = window.confirm(
          `Achtung: Du planst Angebot ${selectedPlanningOffer.offerNumber} nicht im hinterlegten Ausführungsmonat ${formatMonthLabel(
            currentExecutionMonth
          )}, sondern im ${formatMonthLabel(targetExecutionMonth)}. Soll der Ausführungsmonat auf ${formatMonthLabel(
            targetExecutionMonth
          )} geändert und die Planung gespeichert werden?`
        );
        if (!confirmed) return;

        const res = await fetch("/api/offers", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ...selectedPlanningOffer,
            actorId: activeUserId,
            plannedExecutionMonth: targetExecutionMonth,
            saveAsDraft: false,
            projectId: selectedProject.id,
            projectNumber: selectedProject.projectNumber || selectedProject.id,
            projectTitle: selectedProject.title,
          }),
        });

        if (!res.ok) {
          const data = await res.json().catch(() => null);
          setPlanningEntryError(data?.error ?? "Ausführungsmonat konnte nicht geändert werden.");
          return;
        }

        const updatedOffer = (await res.json()) as OfferItem;
        setOffers((currentOffers) =>
          currentOffers.map((offer) => (offer.id === updatedOffer.id ? updatedOffer : offer))
        );
        await addProjectLogbookEntry(
          selectedProject.id,
          "Angebot",
          `Ausführungsmonat ${updatedOffer.offerNumber} von ${formatMonthLabel(
            currentExecutionMonth
          )} auf ${formatMonthLabel(targetExecutionMonth)} geändert, weil eine Planung am ${formatDateOnly(
            planningEntryDate
          )} gespeichert wurde.`
        );
      }
    }

    if (doesAbsenceBlockTime(selectedAbsence, planningEntryStartTime, planningEntryEndTime)) {
      setPlanningEntryError(
        `${selectedUser?.name ?? "Der ausgewählte Mitarbeiter"} ist am ${formatDateOnly(planningEntryDate)} ${absenceLabel(
          selectedAbsence!.type
        )} (${absenceDayPartLabel(selectedAbsence!.dayPart)}). Die Planung wurde blockiert.`
      );
      return;
    }

    const blockedAdditionalUser = selectedAdditionalUsers.find((user) =>
      doesAbsenceBlockTime(
        getUserAbsenceForDateKey(user.id, planningEntryDate),
        planningEntryStartTime,
        planningEntryEndTime
      )
    );
    if (blockedAdditionalUser) {
      setPlanningEntryError(
        `${blockedAdditionalUser.name} ist am ${formatDateOnly(planningEntryDate)} abwesend. Die Planung wurde blockiert.`
      );
      return;
    }

    if (recurrenceDates.length > 1 && planningEntryUserId) {
      const blockedDate = recurrenceDates.find((dateKey) =>
        doesAbsenceBlockTime(
          getUserAbsenceForDateKey(planningEntryUserId, dateKey),
          planningEntryStartTime,
          planningEntryEndTime
        )
      );
      if (blockedDate) {
        setPlanningEntryError(
          `${selectedUser?.name ?? "Der ausgewählte Mitarbeiter"} ist am ${formatDateOnly(blockedDate)} abwesend. Die Serie wurde nicht gespeichert.`
        );
        return;
      }
    }

    if (recurrenceDates.length > 1 && selectedAdditionalUsers.length > 0) {
      const blockedAdditionalPlanning = selectedAdditionalUsers.flatMap((user) =>
        recurrenceDates
          .filter((dateKey) =>
            doesAbsenceBlockTime(
              getUserAbsenceForDateKey(user.id, dateKey),
              planningEntryStartTime,
              planningEntryEndTime
            )
          )
          .map((dateKey) => ({ user, dateKey }))
      )[0];
      if (blockedAdditionalPlanning) {
        setPlanningEntryError(
          `${blockedAdditionalPlanning.user.name} ist am ${formatDateOnly(blockedAdditionalPlanning.dateKey)} abwesend. Die Serie wurde nicht gespeichert.`
        );
        return;
      }
    }

    if (selectedProject) {
      const projectBudgetWarnings = Array.from(new Set(recurrenceDates.map((date) => date.slice(0, 7))))
        .map((monthKey) => {
          const monthBudgetHours = getProjectBudgetAllocationHours(selectedProject, monthKey);
          if (monthBudgetHours <= 0) return null;

          const alreadyPlannedMinutes = planningEntries
            .filter(
              (entry) =>
                entry.projectId === selectedProject.id &&
                entry.date.startsWith(monthKey) &&
                entry.id !== editingPlanningEntryId &&
                !entry.deletedAt
            )
            .reduce((sum, entry) => sum + Number(entry.durationMinutes || 0), 0);
          const plannedUserCount = requiresHourlyPlanningFields ? 1 + selectedAdditionalUsers.length : 1;
          const newPlannedMinutes =
            recurrenceDates.filter((date) => date.startsWith(monthKey)).length * durationMinutes * plannedUserCount;
          const afterSaveHours = (alreadyPlannedMinutes + newPlannedMinutes) / 60;

          return {
            monthKey,
            budgetHours: monthBudgetHours,
            afterSaveHours,
            overHours: Math.max(afterSaveHours - monthBudgetHours, 0),
          };
        })
        .filter(Boolean) as Array<{
        monthKey: string;
        budgetHours: number;
        afterSaveHours: number;
        overHours: number;
      }>;
      const overplannedBudget = projectBudgetWarnings.find((warning) => warning.overHours > 0);

      if (overplannedBudget) {
        const confirmed = window.confirm(
          `Achtung: Du willst im ${formatMonthLabel(overplannedBudget.monthKey)} ${formatHours(
            overplannedBudget.afterSaveHours
          )} Std. planen. Hinterlegt sind ${formatHours(
            overplannedBudget.budgetHours
          )} Std. Dadurch wird das Monatskontingent um ${formatHours(
            overplannedBudget.overHours
          )} Std. überschritten. Trotzdem speichern?`
        );
        if (!confirmed) return;
      }
    }

    if (planningEntrySource === "offer") {
      const alreadyPlannedMinutes = getAlreadyPlannedOfferMinutesForPlanningEntry();
      const remainingOfferMinutes = Math.max(offerTotalMinutes - alreadyPlannedMinutes, 0);

      if (durationMinutes > remainingOfferMinutes) {
        const confirmed = window.confirm(
          `Achtung: Du willst ${formatMinutes(durationMinutes)} planen, es sind aber nur noch ${formatMinutes(
            remainingOfferMinutes
          )} von ${formatMinutes(offerTotalMinutes)} offen. Dadurch wird das Kontingent überplant. Trotzdem speichern?`
        );
        if (!confirmed) return;
      }
    }

    const storedPlanningEntrySource: PlanningEntrySource =
      planningEntrySource === "offer" || (isSingleProjectWithOfferPlanning && planningEntryOfferId)
        ? "offer"
        : "manual";
    const shouldAskOfferWon =
      selectedPlanningOffer &&
      storedPlanningEntrySource === "offer" &&
      isActiveFinalOffer(selectedPlanningOffer) &&
      !isWonOffer(selectedPlanningOffer) &&
      ((!editingPlanningEntryId && nextApprovalStatus === "requested") ||
        (nextApprovalStatus === "confirmed" && previousPlanningEntry?.approvalStatus === "requested"));
    const offerWonReason =
      nextApprovalStatus === "requested"
        ? `Terminwunsch aus Angebot ${selectedPlanningOffer?.offerNumber ?? ""}`
        : `Termin aus Angebot ${selectedPlanningOffer?.offerNumber ?? ""} bestaetigt`;

    const usersToPlan = [selectedUser, ...selectedAdditionalUsers].filter(Boolean) as UserOption[];
    const savedPlanningEntries: PlanningEntry[] = [];
    for (const date of recurrenceDates) {
      for (const userToPlan of usersToPlan) {
        const userDurationMinutes = getPlanningNetMinutesBetween(
          planningEntryStartTime,
          planningEntryEndTime,
          getUserBreakWindowForDate(userToPlan, date)
        );
        const res = await fetch("/api/planning-entries", {
          method: "POST",
          credentials: "same-origin",
          headers: {
            "Content-Type": "application/json",
          },
        body: JSON.stringify({
          source: storedPlanningEntrySource,
          id: userToPlan.id === selectedUser?.id ? editingPlanningEntryId : "",
          approvalStatus: nextApprovalStatus,
          actorUserId: activeUserId,
          actorName: activeUser?.name ?? "",
          requestedByUserId:
            nextApprovalStatus === "requested"
              ? entryOrFallbackRequestedByUserId()
              : "",
          requestedByName:
            nextApprovalStatus === "requested"
              ? entryOrFallbackRequestedByName()
              : "",
          approvedByUserId:
            nextApprovalStatus === "confirmed" && editingPlanningEntryId
              ? activeUserId
              : "",
          board: planningEntryBoard,
          groupName: planningEntryGroup,
          userId: userToPlan.id,
          employeeName: userToPlan.name,
          date,
          startTime: planningEntryStartTime,
          endTime: planningEntryEndTime,
          durationMinutes: userDurationMinutes,
          title,
          customer: selectedProject?.customer || planningEntryCustomer,
          description,
          projectId: selectedProject?.id ?? "",
          projectLabel: selectedProject
            ? `${selectedProject.projectNumber} | ${selectedProject.title}`
            : "",
          objectAddressId: selectedProject?.objectAddressId || planningEntryObjectAddressId || "",
          objectAddressLabel: planningProjectAddress,
          planningTrade: requiresHourlyPlanningFields ? planningEntryTrade : "",
          billingCatalogItemId: requiresHourlyPlanningFields ? planningEntryBillingCatalogItemId : "",
          billingCatalogItemLabel: requiresHourlyPlanningFields
            ? getPlanningBillingCatalogItemLabel(selectedBillingCatalogItem)
            : "",
          billingGroupId: planningBillingGroupId,
          offerId: storedPlanningEntrySource === "offer" ? planningEntryOfferId : "",
          offerLineId: storedPlanningEntrySource === "offer" ? planningEntryOfferLineId : "",
          offerLabel: storedPlanningEntrySource === "offer" ? planningEntryOfferLabel : "",
          offerTotalMinutes: storedPlanningEntrySource === "offer" ? offerTotalMinutes : 0,
          offerPlannedMinutes: storedPlanningEntrySource === "offer" ? userDurationMinutes : 0,
          recurrenceId,
          recurrenceRule,
        }),
      });

        if (!res.ok) {
          const data = await res.json().catch(() => null);
          setPlanningEntryError(data?.error ?? "Planung konnte nicht gespeichert werden.");
          return;
        }

        const savedPlanningEntry = (await res.json()) as PlanningEntry;
        savedPlanningEntries.push(savedPlanningEntry);
      }
    }

    if (selectedProject) {
      const statusAutomationTarget =
        nextApprovalStatus === "requested"
          ? {
              nextStatus: "Zur Planung bereit",
              reason: `Terminwunsch ${title} am ${formatDateOnly(planningEntryDate)} gespeichert`,
              question: `Terminwunsch wurde gespeichert. Soll der Projektstatus auf „Zur Planung bereit“ gesetzt werden?`,
            }
          : {
              nextStatus: "Geplant",
              reason: `Fester Termin ${title} am ${formatDateOnly(planningEntryDate)} gespeichert`,
              question: `Fester Termin wurde gespeichert. Soll der Projektstatus auf „Geplant“ gesetzt werden?`,
            };

      await confirmAndApplyProjectStatus({
        project: selectedProject,
        ...statusAutomationTarget,
      });
    }

    if (shouldAskOfferWon && selectedPlanningOffer) {
      const confirmed = window.confirm(
        `Soll Angebot ${selectedPlanningOffer.offerNumber} jetzt als gewonnen markiert werden?`
      );
      if (confirmed) {
        await markOfferWon(selectedPlanningOffer, offerWonReason, selectedProject?.id);
      }
    }

    const logProjectId = selectedProject?.id ?? "";
    const logEntryWasEdit = Boolean(editingPlanningEntryId);
    const logPlanningDate = planningEntryDate;
    const logPlanningStartTime = planningEntryStartTime;
    const logPlanningEndTime = planningEntryEndTime;
    const logEmployeeName =
      usersToPlan.length > 1
        ? usersToPlan.map((user) => user.name).join(", ")
        : selectedUser?.name || "Mitarbeiter";
    setIsPlanningEntryModalOpen(false);
    resetPlanningEntryForm();
    const reloadedPlanningEntries = await loadPlanningEntries();
    if (reloadedPlanningEntries) {
      const missingSavedEntries = savedPlanningEntries.filter(
        (savedEntry) => !reloadedPlanningEntries.some((entry) => entry.id === savedEntry.id && !entry.deletedAt)
      );
      if (missingSavedEntries.length > 0) {
        const firstMissingEntry = missingSavedEntries[0];
        setErrorMessage(
          `Planung wurde gespeichert, ist aber nach dem Neuladen nicht im Planungsboard sichtbar: ${
            firstMissingEntry.title
          } am ${formatDateOnly(firstMissingEntry.date)} von ${firstMissingEntry.startTime} bis ${
            firstMissingEntry.endTime
          } in ${firstMissingEntry.board} / ${firstMissingEntry.groupName}. Bitte Planungsboard neu laden oder prüfen.`
        );
      }
    }
    await loadNotifications(true);
    if (logProjectId) {
      await addProjectLogbookEntry(
        logProjectId,
        "Planung",
        `${logEntryWasEdit ? "Planung geändert" : "Planung angelegt"}: ${title} am ${formatProjectDate(
          logPlanningDate
        )} von ${logPlanningStartTime} bis ${logPlanningEndTime} für ${logEmployeeName}.`
      );
    }
  }

  async function deletePlanningEntry() {
    if (!editingPlanningEntryId) return;
    await deletePlanningEntryById(editingPlanningEntryId);
  }

  async function deletePlanningEntryById(entryId: string) {
    if (!entryId) return;
    const targetEntry = planningEntries.find((entry) => entry.id === entryId);
    if (targetEntry && !canModifyPlanningEntry(targetEntry)) {
      setErrorMessage("Mitarbeiter können nur eigene offene Terminwünsche löschen.");
      return;
    }
    const confirmed = window.confirm("Planung wirklich löschen?");
    if (!confirmed) return;

    const params = new URLSearchParams({
      id: entryId,
      actorUserId: activeUserId,
      actorName: activeUser?.name ?? "",
    });
    const res = await fetch(`/api/planning-entries?${params.toString()}`, {
      method: "DELETE",
      credentials: "same-origin",
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Planung konnte nicht gelöscht werden.");
      return;
    }

    setIsPlanningEntryModalOpen(false);
    resetPlanningEntryForm();
    await loadPlanningEntries();
    const deletedEntry = planningEntries.find((entry) => entry.id === entryId);
    if (deletedEntry?.projectId) {
      await addProjectLogbookEntry(
        deletedEntry.projectId,
        "Planung",
        `Planung gelöscht: ${deletedEntry.title} am ${formatProjectDate(deletedEntry.date)} von ${
          deletedEntry.startTime
        } bis ${deletedEntry.endTime} für ${deletedEntry.employeeName || "Mitarbeiter"}.`
      );
    }
  }

  function jumpToPlanningEntry(entry: PlanningEntry) {
    setSelectedPlanningDateKey(entry.date);
    setSelectedPlanningBoard(entry.board);
    setSelectedPlanningGroup(entry.groupName);
    setIsPlanningDayOpen(true);
    setActiveTab("planningBoard");
    setSelectedProjectFileId("");
  }

  function openMainView(tab: AppTab) {
    if (!CONTENT_MANAGEMENT_ENABLED && isContentManagementTab(tab)) {
      setActiveTab("overview");
      return;
    }

    setActiveTab(tab);

    if (tab === "contacts") {
      setSelectedCustomerFileId("");
      setSelectedContactIds([]);
    }

    if (tab === "projectsSolutions" || tab === "projectsImmocare" || tab === "hero") {
      setSelectedProjectFileId("");
      setProjectFileTab("logbook");
    }

    if (
      tab === "employees" ||
      tab === "absenceRequests" ||
      tab === "timeTracking" ||
      tab === "timeCategories" ||
      tab === "breakManagement"
    ) {
      setSelectedEmployeeId("");
      resetUserForm();
    }

    if (tab === "planningBoard") {
      const todayKey = formatDateKey(new Date());
      setPlanningBoardStartDate(getWeekStartDateKey(todayKey));
      setSelectedPlanningDateKey(todayKey);
      setIsPlanningDayOpen(false);
      setIsPlanningEntryModalOpen(false);
      setEditingPlanningEntryId("");
    }

    if (tab === "articles" || tab === "services" || tab === "packages" || tab === "salesPrices" || tab === "datanorm") {
      setIsCatalogModalOpen(false);
      setEditingCatalogItemId("");
    }
  }

  function normalizeGoalPerson(value?: string | null) {
    return String(value || "").trim().toLowerCase();
  }

  function normalizeGoalPeriodStart(value: string) {
    if (/^\d{4}-\d{2}$/.test(value)) return `${value}-01`;
    return normalizeDateKeyValue(value);
  }

  function normalizeGoalPeriodEnd(value: string) {
    if (/^\d{4}-\d{2}$/.test(value)) {
      const [year, month] = value.split("-").map(Number);
      return formatDateKey(new Date(year, month, 0, 12));
    }
    return normalizeDateKeyValue(value);
  }

  function getGoalQuarterForMonth(monthKey: string) {
    const month = Number(monthKey.slice(5, 7)) || 1;
    return String(Math.ceil(month / 3));
  }

  function getGoalPeriodRange(type: GoalPeriodType, monthKey: string, quarterValue: string, yearValue: string) {
    const safeYear = Number(yearValue) || new Date().getFullYear();
    if (type === "month") {
      const [year, month] = monthKey.split("-").map(Number);
      const safeMonth = month || 1;
      return {
        start: formatDateKey(new Date(year || safeYear, safeMonth - 1, 1, 12)),
        end: formatDateKey(new Date(year || safeYear, safeMonth, 0, 12)),
      };
    }
    if (type === "quarter") {
      const quarter = Math.min(4, Math.max(1, Number(quarterValue) || 1));
      const startMonth = (quarter - 1) * 3;
      return {
        start: formatDateKey(new Date(safeYear, startMonth, 1, 12)),
        end: formatDateKey(new Date(safeYear, startMonth + 3, 0, 12)),
      };
    }
    if (type === "year") {
      return {
        start: formatDateKey(new Date(safeYear, 0, 1, 12)),
        end: formatDateKey(new Date(safeYear, 11, 31, 12)),
      };
    }
    return { start: goalDraft.periodStart, end: goalDraft.periodEnd };
  }

  function applyGoalPeriodSelection(type: GoalPeriodType, monthKey = goalPeriodMonth, quarterValue = goalPeriodQuarter, yearValue = goalPeriodYear) {
    setGoalPeriodType(type);
    setGoalPeriodMonth(monthKey);
    setGoalPeriodQuarter(quarterValue);
    setGoalPeriodYear(yearValue);
    if (type === "custom") return;
    const range = getGoalPeriodRange(type, monthKey, quarterValue, yearValue);
    setGoalDraft((current) => ({
      ...current,
      periodStart: formatGoalPeriodLabel(range.start),
      periodEnd: formatGoalPeriodLabel(range.end),
    }));
  }

  function getGoalPeriodMonths(periodStart: string, periodEnd: string) {
    const startKey = normalizeGoalPeriodStart(periodStart);
    const endKey = normalizeGoalPeriodEnd(periodEnd);
    if (!startKey || !endKey || endKey < startKey) return [];
    const start = new Date(Number(startKey.slice(0, 4)), Number(startKey.slice(5, 7)) - 1, 1, 12);
    const end = new Date(Number(endKey.slice(0, 4)), Number(endKey.slice(5, 7)) - 1, 1, 12);
    const months: string[] = [];
    for (const cursor = new Date(start); cursor.getTime() <= end.getTime(); cursor.setMonth(cursor.getMonth() + 1)) {
      months.push(`${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}`);
    }
    return months;
  }

  function getGoalDisplayPeriodType(goal: SalesGoal): GoalPeriodType {
    const months = getGoalPeriodMonths(goal.periodStart || goal.targetMonth, goal.periodEnd || goal.targetMonth);
    if (months.length === 1) return "month";
    if (months.length === 3 && ["01", "04", "07", "10"].includes(months[0].slice(5, 7))) return "quarter";
    if (months.length === 12 && months[0].endsWith("-01")) return "year";
    return "custom";
  }

  function getGoalMonthRange(monthKey: string) {
    const [year, month] = monthKey.split("-").map(Number);
    return {
      start: formatDateKey(new Date(year, month - 1, 1, 12)),
      end: formatDateKey(new Date(year, month, 0, 12)),
    };
  }

  function normalizeGoalDateValue(value: string) {
    const trimmedValue = String(value || "").trim();
    const isoPrefix = trimmedValue.match(/^(\d{4}-\d{2}-\d{2})/);
    if (isoPrefix) return isoPrefix[1];
    return normalizeDateKeyValue(trimmedValue);
  }

  function isGoalDateInPeriod(value: string | undefined, periodStart: string, periodEnd: string) {
    const dateKey = normalizeGoalDateValue(value || "");
    if (!dateKey) return false;
    const startKey = normalizeGoalPeriodStart(periodStart);
    const endKey = normalizeGoalPeriodEnd(periodEnd);
    if (!startKey || !endKey) return false;
    return dateKey >= startKey && dateKey <= endKey;
  }

  function isGoalItemAssignedToUser(user: UserOption, value?: string | null, fallbackId?: string | null) {
    if (fallbackId && fallbackId === user.id) return true;
    return normalizeGoalPerson(value) === normalizeGoalPerson(user.name);
  }

  function getGoalMetricOption(metricKey: GoalMetricKey | "") {
    return goalMetricOptions.find((option) => option.key === metricKey) ?? goalMetricOptions[0];
  }

  function formatGoalValue(value: number, metricKey: GoalMetricKey | "") {
    const metric = getGoalMetricOption(metricKey);
    if (metric.unit === "currency") return formatMoney(value);
    if (metric.unit === "percent") return `${value.toLocaleString("de-DE", { maximumFractionDigits: 1 })}%`;
    if (["avg_offer_to_win_days", "avg_offer_to_loss_days", "avg_offer_to_planning_days", "avg_offer_to_followup_days"].includes(metricKey)) {
      return `${value.toLocaleString("de-DE", { maximumFractionDigits: 1 })} Tg.`;
    }
    if (["project_hours", "unproductive_hours", "attendance_hours"].includes(metricKey)) {
      return `${value.toLocaleString("de-DE", { maximumFractionDigits: 2 })} Std.`;
    }
    return value.toLocaleString("de-DE", { maximumFractionDigits: 0 });
  }

  function formatGoalPeriodLabel(value: string) {
    const normalizedValue = /^\d{4}-\d{2}$/.test(value) ? `${value}-01` : normalizeGoalDateValue(value);
    return normalizedValue ? formatDateOnly(normalizedValue) : "-";
  }

  function syncGoalPeriodControls(periodStart: string, periodEnd: string) {
    const startKey = normalizeGoalPeriodStart(periodStart);
    const endKey = normalizeGoalPeriodEnd(periodEnd);
    if (!startKey || !endKey) {
      setGoalPeriodType("custom");
      return;
    }
    const months = getGoalPeriodMonths(startKey, endKey);
    const year = startKey.slice(0, 4);
    if (months.length === 1) {
      setGoalPeriodType("month");
      setGoalPeriodMonth(months[0]);
      setGoalPeriodQuarter(getGoalQuarterForMonth(months[0]));
      setGoalPeriodYear(year);
      return;
    }
    if (months.length === 3 && ["01", "04", "07", "10"].includes(months[0].slice(5, 7))) {
      setGoalPeriodType("quarter");
      setGoalPeriodMonth(months[0]);
      setGoalPeriodQuarter(getGoalQuarterForMonth(months[0]));
      setGoalPeriodYear(year);
      return;
    }
    if (months.length === 12 && months[0].endsWith("-01")) {
      setGoalPeriodType("year");
      setGoalPeriodMonth(months[0]);
      setGoalPeriodQuarter("1");
      setGoalPeriodYear(year);
      return;
    }
    setGoalPeriodType("custom");
    setGoalPeriodMonth(months[0] ?? goalPeriodMonth);
    setGoalPeriodQuarter(months[0] ? getGoalQuarterForMonth(months[0]) : goalPeriodQuarter);
    setGoalPeriodYear(year);
  }

  function isLowerBetterGoalMetric(metricKey: GoalMetricKey | "") {
    return [
      "lost_offers_count",
      "lost_offers_value",
      "offer_loss_rate",
      "stale_open_offers",
      "avg_offer_to_win_days",
      "avg_offer_to_loss_days",
      "avg_offer_to_planning_days",
      "avg_offer_to_followup_days",
      "open_tasks",
      "overdue_tasks",
      "unproductive_hours",
    ].includes(metricKey);
  }

  function isAverageGoalMetric(metricKey: GoalMetricKey | "") {
    return (
      getGoalMetricOption(metricKey).unit === "percent" ||
      ["avg_offer_to_win_days", "avg_offer_to_loss_days", "avg_offer_to_planning_days", "avg_offer_to_followup_days"].includes(metricKey)
    );
  }

  function getGoalDateTime(value?: string | null) {
    if (!value) return null;
    const date = parseAppDateTime(value);
    return Number.isFinite(date.getTime()) ? date : null;
  }

  function getGoalDaysBetween(startValue?: string | null, endValue?: string | null) {
    const start = getGoalDateTime(startValue);
    const end = getGoalDateTime(endValue);
    if (!start || !end || end.getTime() < start.getTime()) return null;
    return (end.getTime() - start.getTime()) / 86400000;
  }

  function getOfferIssueDate(offer: OfferItem) {
    const sentDispatches = documentMailDispatches
      .filter((dispatch) => dispatch.documentKind === "offer")
      .filter((dispatch) => dispatch.status === "sent")
      .filter((dispatch) => dispatch.documentId === offer.id || dispatch.documentNumber === offer.offerNumber)
      .map((dispatch) => dispatch.createdAt)
      .filter(Boolean)
      .sort();
    return sentDispatches[0] || offer.createdAt;
  }

  function isGoalOfferAssignedToUser(owner: UserOption, offer: OfferItem, decisionOwnerName = "") {
    return (
      isGoalItemAssignedToUser(owner, decisionOwnerName || offer.internalContactName) ||
      isGoalItemAssignedToUser(owner, offer.internalContactName)
    );
  }

  function getFirstPlanningDateForOffer(offer: OfferItem, issuedAt: string) {
    const issuedDateKey = normalizeGoalDateValue(issuedAt);
    const matchingEntries = planningEntries
      .filter((entry) => !entry.deletedAt && entry.approvalStatus === "confirmed")
      .filter((entry) => entry.offerId === offer.id || (!entry.offerId && entry.projectId === offer.projectId))
      .filter((entry) => !issuedDateKey || entry.date >= issuedDateKey)
      .sort((first, second) => `${first.date}T${first.startTime}`.localeCompare(`${second.date}T${second.startTime}`));
    const entry = matchingEntries[0];
    return entry ? `${entry.date}T${entry.startTime}` : "";
  }

  function taskBelongsToOffer(task: TaskItem, offer: OfferItem) {
    const linkedOfferId = getOfferIdFromTask(task);
    if (linkedOfferId && linkedOfferId === offer.id) return true;
    if (task.projectId && task.projectId !== offer.projectId) return false;
    return task.titel.toLowerCase().includes("angebot nachfassen") && task.titel.includes(offer.offerNumber);
  }

  function getCompletedFollowUpDateForOffer(offer: OfferItem) {
    const completedTasks = tasks
      .filter((task) => taskBelongsToOffer(task, offer))
      .filter((task) => task.status === "erledigt")
      .map((task) => task.completedAt || task.archiveDueAt || task.createdAt)
      .filter(Boolean)
      .sort();
    return completedTasks[0] || "";
  }

  function averageGoalDays(values: Array<number | null>) {
    const cleanValues = values.filter((value): value is number => value !== null && Number.isFinite(value));
    if (cleanValues.length === 0) return 0;
    return cleanValues.reduce((sum, value) => sum + value, 0) / cleanValues.length;
  }

  function getGoalProgressDetails(goal: SalesGoal, actualValue: number) {
    const targetValue = Math.max(0, Number(goal.targetValue) || 0);
    const isLowerBetter = isLowerBetterGoalMetric(goal.metricKey);
    const reached = targetValue > 0 && (isLowerBetter ? actualValue <= targetValue : actualValue >= targetValue);
    const metric = getGoalMetricOption(goal.metricKey);
    const targetReserveScale = targetValue > 0 ? targetValue / 0.75 : 1;
    const scaleMax =
      metric.unit === "percent"
        ? Math.max(100, targetValue, actualValue)
        : Math.max(targetReserveScale, actualValue, 1);
    const actualPosition = Math.min(100, Math.max(0, (actualValue / scaleMax) * 100));
    const targetPosition = Math.min(100, Math.max(0, (targetValue / scaleMax) * 100));
    const relationPercent = targetValue > 0 ? Math.round((actualValue / targetValue) * 100) : 0;
    const status = reached ? "reached" : isLowerBetter && actualValue > targetValue ? "over" : "open";

    return {
      actualPosition,
      reached,
      relationPercent,
      status,
      targetPosition,
      targetValue,
    };
  }

  function getGoalActualValue(goal: SalesGoal) {
    const owner = users.find((user) => user.id === goal.ownerUserId) ??
      users.find((user) => normalizeGoalPerson(user.name) === normalizeGoalPerson(goal.ownerName));
    if (!owner || !goal.metricKey || !goal.periodStart || !goal.periodEnd) return 0;
    const userProjectStampEntries = stampEntries.filter(
      (entry) =>
        !entry.deletedAt &&
        entry.mode === "project" &&
        entry.userId === owner.id &&
        isGoalDateInPeriod(entry.date, goal.periodStart, goal.periodEnd)
    );
    const userUnproductiveStampEntries = stampEntries.filter(
      (entry) =>
        !entry.deletedAt &&
        entry.mode === "unproductive" &&
        entry.userId === owner.id &&
        isGoalDateInPeriod(entry.date, goal.periodStart, goal.periodEnd)
    );
    const projectHours =
      userProjectStampEntries.reduce((sum, entry) => sum + Math.max(0, Number(entry.durationMs) || 0), 0) / 3600000;
    const unproductiveHours =
      userUnproductiveStampEntries.reduce((sum, entry) => sum + Math.max(0, Number(entry.durationMs) || 0), 0) / 3600000;
    const attendanceHours = projectHours + unproductiveHours;
    const assignedInvoices = invoices.filter(
      (invoice) =>
        isFinanciallyActiveInvoice(invoice) &&
        isGoalDateInPeriod(invoice.serviceDate || invoice.createdAt, goal.periodStart, goal.periodEnd) &&
        isGoalItemAssignedToUser(owner, invoice.internalContactName)
    );
    const soldHours = assignedInvoices.reduce(
      (sum, invoice) =>
        sum +
        invoice.lines.reduce(
          (lineSum, line) =>
            lineSum + line.laborItems.reduce((laborSum, labor) => laborSum + (Number(labor.plannedHours) || 0), 0),
          0
        ),
      0
    );
    const getLineNetValue = (line: OfferLineDraft) => {
      const quantity = Number(line.quantity) || 0;
      const unitPrice = Number(line.unitPrice) || 0;
      const discountPercent = Math.max(0, Math.min(100, Number(line.discountPercent) || 0));
      return quantity * unitPrice * (1 - discountPercent / 100);
    };
    const sumLineValuesByType = (lines: OfferLineDraft[], catalogType: CatalogItemType) =>
      lines
        .filter((line) => line.catalogType === catalogType)
        .reduce((sum, line) => sum + getLineNetValue(line), 0);

    if (goal.metricKey === "offers_count") {
      return offers.filter(
        (offer) =>
          isGoalDateInPeriod(offer.createdAt, goal.periodStart, goal.periodEnd) &&
          isGoalItemAssignedToUser(owner, offer.internalContactName)
      ).length;
    }

    if (goal.metricKey === "offers_value") {
      return offers
        .filter(
          (offer) =>
            isGoalDateInPeriod(offer.createdAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, offer.internalContactName)
        )
        .reduce((sum, offer) => sum + (Number(offer.netTotal) || 0), 0);
    }

    if (goal.metricKey === "offer_service_value") {
      return offers
        .filter(
          (offer) =>
            isGoalDateInPeriod(offer.createdAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, offer.internalContactName)
        )
        .reduce((sum, offer) => sum + sumLineValuesByType(offer.lines, "service"), 0);
    }

    if (goal.metricKey === "offer_material_value") {
      return offers
        .filter(
          (offer) =>
            isGoalDateInPeriod(offer.createdAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, offer.internalContactName)
        )
        .reduce((sum, offer) => sum + sumLineValuesByType(offer.lines, "article"), 0);
    }

    if (goal.metricKey === "offer_package_value") {
      return offers
        .filter(
          (offer) =>
            isGoalDateInPeriod(offer.createdAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, offer.internalContactName)
        )
        .reduce((sum, offer) => sum + sumLineValuesByType(offer.lines, "package"), 0);
    }

    if (goal.metricKey === "won_offers_count") {
      return offers.filter(
        (offer) =>
          Boolean(offer.wonAt) &&
          isGoalDateInPeriod(offer.wonAt || offer.updatedAt, goal.periodStart, goal.periodEnd) &&
          isGoalItemAssignedToUser(owner, offer.wonByName || offer.internalContactName)
      ).length;
    }

    if (goal.metricKey === "won_offers_value") {
      return offers
        .filter(
          (offer) =>
            Boolean(offer.wonAt) &&
            isGoalDateInPeriod(offer.wonAt || offer.updatedAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, offer.wonByName || offer.internalContactName)
        )
        .reduce((sum, offer) => sum + (Number(offer.netTotal) || 0), 0);
    }

    if (goal.metricKey === "offer_win_rate" || goal.metricKey === "offer_loss_rate") {
      const decidedOffers = offers.filter((offer) => {
        if (isDeletedOffer(offer) || offer.status === "Entwurf") return false;
        const decisionDate = offer.wonAt || offer.lostAt || "";
        if (!decisionDate || !isGoalDateInPeriod(decisionDate, goal.periodStart, goal.periodEnd)) return false;
        return isGoalOfferAssignedToUser(owner, offer, offer.wonByName || offer.internalContactName);
      });
      if (decidedOffers.length === 0) return 0;
      const matchingCount = decidedOffers.filter((offer) =>
        goal.metricKey === "offer_win_rate" ? Boolean(offer.wonAt) : Boolean(offer.lostAt)
      ).length;
      return (matchingCount / decidedOffers.length) * 100;
    }

    if (goal.metricKey === "stale_open_offers") {
      const now = new Date();
      const periodEnd = normalizeGoalPeriodEnd(goal.periodEnd);
      return offers.filter((offer) => {
        if (isDeletedOffer(offer) || offer.status === "Entwurf" || isWonOffer(offer) || isLostOffer(offer)) return false;
        if (!isGoalOfferAssignedToUser(owner, offer)) return false;
        const issuedAt = getOfferIssueDate(offer);
        const issuedDateKey = normalizeGoalDateValue(issuedAt);
        if (periodEnd && issuedDateKey && issuedDateKey > periodEnd) return false;
        const issuedDate = getGoalDateTime(issuedAt);
        if (!issuedDate) return false;
        return now.getTime() - issuedDate.getTime() >= 14 * 86400000;
      }).length;
    }

    if (goal.metricKey === "avg_offer_to_win_days") {
      return averageGoalDays(
        offers
          .filter(
            (offer) =>
              !isDeletedOffer(offer) &&
              Boolean(offer.wonAt) &&
              isGoalDateInPeriod(offer.wonAt, goal.periodStart, goal.periodEnd) &&
              isGoalOfferAssignedToUser(owner, offer, offer.wonByName || offer.internalContactName)
          )
          .map((offer) => getGoalDaysBetween(getOfferIssueDate(offer), offer.wonAt))
      );
    }

    if (goal.metricKey === "avg_offer_to_loss_days") {
      return averageGoalDays(
        offers
          .filter(
            (offer) =>
              !isDeletedOffer(offer) &&
              Boolean(offer.lostAt) &&
              isGoalDateInPeriod(offer.lostAt, goal.periodStart, goal.periodEnd) &&
              isGoalOfferAssignedToUser(owner, offer)
          )
          .map((offer) => getGoalDaysBetween(getOfferIssueDate(offer), offer.lostAt))
      );
    }

    if (goal.metricKey === "avg_offer_to_planning_days") {
      return averageGoalDays(
        offers
          .filter(
            (offer) =>
              !isDeletedOffer(offer) &&
              offer.status !== "Entwurf" &&
              isGoalDateInPeriod(getOfferIssueDate(offer), goal.periodStart, goal.periodEnd) &&
              isGoalOfferAssignedToUser(owner, offer)
          )
          .map((offer) => {
            const issuedAt = getOfferIssueDate(offer);
            return getGoalDaysBetween(issuedAt, getFirstPlanningDateForOffer(offer, issuedAt));
          })
      );
    }

    if (goal.metricKey === "avg_offer_to_followup_days") {
      return averageGoalDays(
        offers
          .filter(
            (offer) =>
              !isDeletedOffer(offer) &&
              offer.status !== "Entwurf" &&
              isGoalDateInPeriod(getOfferIssueDate(offer), goal.periodStart, goal.periodEnd) &&
              isGoalOfferAssignedToUser(owner, offer)
          )
          .map((offer) => getGoalDaysBetween(getOfferIssueDate(offer), getCompletedFollowUpDateForOffer(offer)))
      );
    }

    if (goal.metricKey === "lost_offers_count") {
      return offers.filter(
        (offer) =>
          Boolean(offer.lostAt || offer.lostReason) &&
          isGoalDateInPeriod(offer.lostAt || offer.updatedAt, goal.periodStart, goal.periodEnd) &&
          isGoalItemAssignedToUser(owner, offer.internalContactName)
      ).length;
    }

    if (goal.metricKey === "lost_offers_value") {
      return offers
        .filter(
          (offer) =>
            Boolean(offer.lostAt || offer.lostReason) &&
            isGoalDateInPeriod(offer.lostAt || offer.updatedAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, offer.internalContactName)
        )
        .reduce((sum, offer) => sum + (Number(offer.netTotal) || 0), 0);
    }

    if (goal.metricKey === "invoices_count") {
      return assignedInvoices.length;
    }

    if (goal.metricKey === "invoices_value") {
      return assignedInvoices.reduce((sum, invoice) => sum + (Number(invoice.netTotal) || 0), 0);
    }

    if (goal.metricKey === "invoice_service_value") {
      return assignedInvoices.reduce((sum, invoice) => sum + sumLineValuesByType(invoice.lines, "service"), 0);
    }

    if (goal.metricKey === "invoice_material_value") {
      return assignedInvoices.reduce((sum, invoice) => sum + sumLineValuesByType(invoice.lines, "article"), 0);
    }

    if (goal.metricKey === "invoice_package_value") {
      return assignedInvoices.reduce((sum, invoice) => sum + sumLineValuesByType(invoice.lines, "package"), 0);
    }

    if (goal.metricKey === "paid_invoices_count") {
      return assignedInvoices.filter(
        (invoice) => invoice.isPaid && isGoalDateInPeriod(invoice.paidAt || invoice.serviceDate || invoice.createdAt, goal.periodStart, goal.periodEnd)
      ).length;
    }

    if (goal.metricKey === "paid_invoices_value") {
      return assignedInvoices
        .filter((invoice) => invoice.isPaid && isGoalDateInPeriod(invoice.paidAt || invoice.serviceDate || invoice.createdAt, goal.periodStart, goal.periodEnd))
        .reduce((sum, invoice) => sum + (Number(invoice.netTotal) || 0), 0);
    }

    if (goal.metricKey === "open_tasks") {
      return tasks.filter(
        (task) =>
          task.status !== "erledigt" &&
          task.status !== "archiviert" &&
          task.zustaendigId === owner.id &&
          isGoalDateInPeriod(task.createdAt, goal.periodStart, goal.periodEnd)
      ).length;
    }

    if (goal.metricKey === "overdue_tasks") {
      const todayKey = formatDateKey(new Date());
      return tasks.filter(
        (task) =>
          task.status !== "erledigt" &&
          task.status !== "archiviert" &&
          task.zustaendigId === owner.id &&
          normalizeGoalDateValue(task.faelligkeit || "") < todayKey &&
          isGoalDateInPeriod(task.faelligkeit || task.createdAt, goal.periodStart, goal.periodEnd)
      ).length;
    }

    if (goal.metricKey === "tasks_done") {
      return tasks.filter(
        (task) =>
          task.status === "erledigt" &&
          isGoalDateInPeriod(task.completedAt || task.archiveDueAt || task.createdAt, goal.periodStart, goal.periodEnd) &&
          task.zustaendigId === owner.id
      ).length;
    }

    if (goal.metricKey === "sales_opportunities_count") {
      return projectPotentials.filter(
        (potential) =>
          potential.status !== "lost" &&
          isGoalDateInPeriod(potential.createdAt, goal.periodStart, goal.periodEnd) &&
          isGoalItemAssignedToUser(owner, potential.ownerName, potential.ownerUserId)
      ).length;
    }

    if (goal.metricKey === "sales_opportunities_value") {
      return projectPotentials
        .filter(
          (potential) =>
            potential.status !== "lost" &&
            isGoalDateInPeriod(potential.createdAt, goal.periodStart, goal.periodEnd) &&
            isGoalItemAssignedToUser(owner, potential.ownerName, potential.ownerUserId)
        )
        .reduce((sum, potential) => sum + (Number(String(potential.estimatedValue).replace(",", ".")) || 0), 0);
    }

    if (goal.metricKey === "project_hours") return projectHours;
    if (goal.metricKey === "unproductive_hours") return unproductiveHours;
    if (goal.metricKey === "attendance_hours") return attendanceHours;
    if (goal.metricKey === "performance_grade") return projectHours > 0 ? (soldHours / projectHours) * 100 : 0;
    if (goal.metricKey === "productivity_rate") return attendanceHours > 0 ? (soldHours / attendanceHours) * 100 : 0;

    if (goal.metricKey === "logbook_entries") {
      return projectLogbookEntries.filter(
        (entry) =>
          isGoalDateInPeriod(entry.date, goal.periodStart, goal.periodEnd) &&
          (entry.authorUserId === owner.id || normalizeGoalPerson(entry.author) === normalizeGoalPerson(owner.name))
      ).length;
    }

    if (goal.metricKey === "activity_reports_count") {
      return projectLogbookEntries.filter(
        (entry) =>
          isGoalDateInPeriod(entry.date, goal.periodStart, goal.periodEnd) &&
          (entry.authorUserId === owner.id || normalizeGoalPerson(entry.author) === normalizeGoalPerson(owner.name)) &&
          normalizeStampSearchValue(entry.title).includes("tatigkeitsbericht")
      ).length;
    }

    if (goal.metricKey === "customer_feedback_average") {
      const ratings = customerFeedback.filter(
        (feedback) =>
          isGoalDateInPeriod(feedback.createdAt, goal.periodStart, goal.periodEnd) &&
          isGoalItemAssignedToUser(owner, feedback.salesUserName, feedback.salesUserId)
      );
      if (ratings.length === 0) return 0;
      const averageRating = ratings.reduce((sum, feedback) => sum + feedback.rating, 0) / ratings.length;
      return (averageRating / 5) * 100;
    }

    return 0;
  }

  function getGoalBreakdown(goal: SalesGoal) {
    const periodType = getGoalDisplayPeriodType(goal);
    const months = getGoalPeriodMonths(goal.periodStart || goal.targetMonth, goal.periodEnd || goal.targetMonth);
    const targetValue = Math.max(0, Number(goal.targetValue) || 0);
    const usesAverage = isAverageGoalMetric(goal.metricKey);
    const shouldShowMonths = (periodType === "quarter" || periodType === "year") && months.length > 1;
    const monthTarget = shouldShowMonths && !usesAverage ? targetValue / months.length : targetValue;
    const monthRows = shouldShowMonths
      ? months.map((monthKey) => {
          const range = getGoalMonthRange(monthKey);
          const actualValue = getGoalActualValue({
            ...goal,
            periodStart: range.start,
            periodEnd: range.end,
            targetValue: monthTarget,
          });
          const details = getGoalProgressDetails({ ...goal, targetValue: monthTarget }, actualValue);
          return { monthKey, actualValue, details };
        })
      : [];
    const aggregateValue =
      shouldShowMonths && usesAverage && monthRows.length > 0
        ? monthRows.reduce((sum, row) => sum + row.actualValue, 0) / monthRows.length
        : getGoalActualValue(goal);
    const aggregateLabel =
      periodType === "year"
        ? usesAverage
          ? "Jahresschnitt"
          : "Jahressumme"
        : periodType === "quarter"
          ? usesAverage
            ? "Quartalsschnitt"
            : "Quartalssumme"
          : "Stand";

    return {
      aggregateLabel,
      aggregateValue,
      monthRows,
      periodType,
      shouldShowMonths,
    };
  }

  async function saveGoal() {
    if (!activeUser || !["ADMIN", "GESCHAEFTSFUEHRER"].includes(activeUser.role)) return;
    if (!activeUserId) {
      setGoalError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }
    const owner = users.find((user) => user.id === goalDraft.ownerUserId && user.isActive);
    if (!owner) {
      setGoalError("Bitte einen aktiven Mitarbeiter auswählen.");
      return;
    }
    const targetValue = Number(String(goalDraft.targetValue).replace(",", "."));
    if (!Number.isFinite(targetValue) || targetValue <= 0) {
      setGoalError("Bitte einen Zielwert groesser 0 eintragen.");
      return;
    }
    const periodStart = normalizeGoalPeriodStart(goalDraft.periodStart);
    const periodEnd = normalizeGoalPeriodEnd(goalDraft.periodEnd);
    if (!periodStart || !periodEnd || periodEnd < periodStart) {
      setGoalError("Bitte einen gültigen Zeitraum auswählen.");
      return;
    }

    const metric = getGoalMetricOption(goalDraft.metricKey);
    const title = goalDraft.title.trim() || metric.label;
    setIsGoalSaving(true);
    setGoalError("");

    try {
      const res = await fetch("/api/sales-targets", {
        method: editingGoalId ? "PATCH" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          actorId: activeUserId,
          id: editingGoalId || undefined,
          title,
          description: goalDraft.description,
          ownerUserId: owner.id,
          priority: "normal",
          metricKey: goalDraft.metricKey,
          targetValue,
          periodStart,
          periodEnd,
          targetMonth: periodStart.slice(0, 7),
          status: "open",
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setGoalError(data?.error ?? "Ziel konnte nicht gespeichert werden.");
        return;
      }

      await loadSalesGoals();
      resetGoalDraft(owner.id);
      setIsGoalFormOpen(false);
    } finally {
      setIsGoalSaving(false);
    }
  }

  function resetGoalDraft(ownerUserId = goalDraft.ownerUserId) {
    const range = getGoalPeriodRange("month", currentGoalMonthKey, getGoalQuarterForMonth(currentGoalMonthKey), currentGoalYear);
    setEditingGoalId("");
    setGoalPeriodType("month");
    setGoalPeriodMonth(currentGoalMonthKey);
    setGoalPeriodQuarter(getGoalQuarterForMonth(currentGoalMonthKey));
    setGoalPeriodYear(currentGoalYear);
    setGoalDraft({
      ownerUserId,
      metricKey: "offers_count",
      targetValue: "",
      periodStart: formatGoalPeriodLabel(range.start),
      periodEnd: formatGoalPeriodLabel(range.end),
      title: "",
      description: "",
    });
    setGoalError("");
  }

  function openCreateGoalForm() {
    resetGoalDraft(goalDraft.ownerUserId);
    setIsGoalFormOpen(true);
  }

  function openEditGoalForm(goal: SalesGoal) {
    const periodStart = formatGoalPeriodLabel(goal.periodStart || goal.targetMonth);
    const periodEnd = formatGoalPeriodLabel(goal.periodEnd || goal.targetMonth);
    setEditingGoalId(goal.id);
    syncGoalPeriodControls(periodStart, periodEnd);
    setGoalDraft({
      ownerUserId: goal.ownerUserId,
      metricKey: (goal.metricKey || "offers_count") as GoalMetricKey,
      targetValue: String(goal.targetValue || ""),
      periodStart,
      periodEnd,
      title: goal.title || "",
      description: goal.description || "",
    });
    setGoalError("");
    setIsGoalFormOpen(true);
  }

  async function deleteGoal(goal: SalesGoal) {
    if (!activeUser || !["ADMIN", "GESCHAEFTSFUEHRER"].includes(activeUser.role) || !activeUserId) return;
    const confirmed = window.confirm(`Ziel "${goal.title || getGoalMetricOption(goal.metricKey).label}" wirklich entfernen?`);
    if (!confirmed) return;

    setIsGoalSaving(true);
    setGoalError("");
    try {
      const res = await fetch("/api/sales-targets", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ actorId: activeUserId, id: goal.id }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setGoalError(data?.error ?? "Ziel konnte nicht entfernt werden.");
        return;
      }
      await loadSalesGoals();
      if (editingGoalId === goal.id) {
        resetGoalDraft(goalDraft.ownerUserId);
        setIsGoalFormOpen(false);
      }
    } finally {
      setIsGoalSaving(false);
    }
  }

  function openEditAbsenceModal(absence: AbsenceItem) {
    const relatedAbsences = absences
      .filter(
        (currentAbsence) =>
          currentAbsence.userId === absence.userId &&
          currentAbsence.type === absence.type &&
          currentAbsence.representativeUserId === absence.representativeUserId &&
          currentAbsence.note === absence.note
      )
      .sort((first, second) => first.date.localeCompare(second.date));

    setEditingAbsenceId(absence.id);
    setAbsenceUserId(absence.userId);
    setAbsenceType(absence.type);
    setAbsenceDayPart(absence.dayPart);
    setAbsenceDateFrom(relatedAbsences[0]?.date ?? absence.date);
    setAbsenceDateTo(relatedAbsences.at(-1)?.date ?? absence.date);
    setAbsenceRepresentativeUserId(absence.representativeUserId ?? "");
    setAbsenceNote(absence.note);
    setAbsenceHandoverMode(absence.handoverTaskIds.length > 0 ? "open" : "none");
    setAbsenceHandoverTaskIds(absence.handoverTaskIds);
    setAcceptedHandoverTaskIds(
      tasks
        .filter((task) => absence.handoverTaskIds.includes(task.id) && task.acceptanceStatus === "accepted")
        .map((task) => task.id)
    );
    setPendingHandoverTaskIds([]);
    setAbsenceChecklist(vacationHandoverItems.map(() => true));
    setAbsenceHandoverConfirmed(true);
    setAbsenceWarning("");
    setIsAbsenceModalOpen(true);
    setSelectedCalendarActionDate("");
  }

