  function updateProjectDraft<K extends keyof ProjectDraft>(key: K, value: ProjectDraft[K]) {
    setProjectDraft((currentDraft) => ({
      ...currentDraft,
      [key]: value,
      ...(key === "responsibleName" && currentDraft.deputyName === value
        ? { deputyName: "", deputyFrom: "", deputyUntil: "" }
        : {}),
      ...(key === "deputyName" && !value
        ? { deputyFrom: "", deputyUntil: "" }
        : {}),
      ...(key === "contactId"
        ? {
            contactPersonId: "",
            addressContactId: "",
            objectAddressId: "",
          }
        : {}),
      ...(key === "projectType"
        ? {
            branch:
              value === "Projekt OK immocare" ? "OK immocare GmbH" : "OK solutions GmbH",
          }
        : {}),
      ...(key === "projectKind" && value === "einmaliges Projekt"
        ? {
            recurringBillingMode: "" as const,
            forecastBillingType: "monatlich" as const,
            forecastNetAmount: "",
          }
        : {}),
    }));
  }

  function getContactLabel(contact: ContactItem) {
    return (
      [contact.companyName, contact.firstName, contact.lastName].filter(Boolean).join(" - ") ||
      contact.email ||
      contact.customerNumber
    );
  }

  function getContactTypeLabel(contact: Pick<ContactItem, "type">) {
    if (contact.type === "company") return "Firma";
    if (contact.type === "private") return "Privatperson";
    return "Ansprechpartner";
  }

  function getContactDisplayName(contact: ContactItem) {
    if (contact.type === "company") return contact.companyName || contact.customerNumber;

    return (
      [contact.salutation, contact.firstName, contact.lastName].filter(Boolean).join(" ") ||
      contact.email ||
      contact.customerNumber
    );
  }

  function getContactInvoiceEmail(contact?: ContactItem | null) {
    return contact?.invoiceEmail?.trim() || contact?.email?.trim() || "";
  }

  function getContactActivityReportEmail(contact?: ContactItem | null) {
    return contact?.activityReportEmail?.trim() || contact?.email?.trim() || "";
  }

  function getCustomerFileTarget(contact: ContactItem) {
    if (contact.type === "company") return contact;

    return (
      contacts.find((candidate) => candidate.id === contact.parentCompanyId) ||
      contacts.find(
        (candidate) =>
          candidate.type === "company" &&
          candidate.companyName &&
          candidate.companyName === contact.parentCompanyName
      ) ||
      contact
    );
  }

