  function getOfferIdFromTask(task: TaskItem) {
    const linkedOffer = (task.links ?? []).find((link) => link.url.startsWith("offer:"));
    return linkedOffer?.url.replace(/^offer:/, "").trim() || "";
  }

  function getOfferNumberFromTask(task: TaskItem) {
    const source = `${task.titel}\n${task.beschreibung}`;
    const match = source.match(/Angebot\s+(?:nachfassen:\s*)?([A-Z]{1,4}-?\d{3,}|[A-Z]{1,4}\d{3,})/i);
    return match?.[1]?.trim() || "";
  }

  function getOfferForTask(task: TaskItem) {
    const offerId = getOfferIdFromTask(task);
    if (offerId) {
      const byId = offers.find((offer) => offer.id === offerId);
      if (byId) return byId;
    }

    const offerNumber = getOfferNumberFromTask(task);
    if (!offerNumber) return null;
    return offers.find((offer) => offer.offerNumber === offerNumber) ?? null;
  }

  function isOfferFollowUpTask(task: TaskItem) {
    return task.titel.toLowerCase().includes("angebot nachfassen") && Boolean(getOfferForTask(task));
  }

  function openOfferFollowUpDecisionDialog(task: TaskItem, confirmedStatus: TaskStatus) {
    const offer = getOfferForTask(task);
    if (!offer) return false;
    setOfferFollowUpDecision({
      task,
      offer,
      outcome: "won",
      reason: "",
      note: "",
      followUpAt: normalizeDeadlineInput(task.faelligkeit) || getOfferFollowUpDeadline(),
      confirmedStatus,
      error: "",
      isSaving: false,
    });
    setIsTaskStatusConfirmOpen(false);
    return true;
  }

  async function completeOfferFollowUpDecision() {
    if (!offerFollowUpDecision) return;
    const { task, offer, outcome } = offerFollowUpDecision;
    const reason = offerFollowUpDecision.reason.trim();
    const note = offerFollowUpDecision.note.trim();
    const followUpAt = normalizeDeadlineInput(offerFollowUpDecision.followUpAt);

    if (outcome === "won" && !reason) {
      setOfferFollowUpDecision((current) =>
        current ? { ...current, error: "Bitte kurz eintragen, warum das Angebot gewonnen wurde." } : current
      );
      return;
    }
    if (outcome === "lost" && (!reason || !note)) {
      setOfferFollowUpDecision((current) =>
        current ? { ...current, error: "Bitte Grund und Kommentar zum verlorenen Angebot eintragen." } : current
      );
      return;
    }
    if (outcome === "follow_up" && !followUpAt) {
      setOfferFollowUpDecision((current) =>
        current ? { ...current, error: "Bitte ein neues Nachfassdatum eintragen." } : current
      );
      return;
    }

    setOfferFollowUpDecision((current) => (current ? { ...current, error: "", isSaving: true } : current));

    try {
      if (outcome === "won") {
        const markedWon = await markOfferWon(offer, reason, offer.projectId);
        if (!markedWon) {
          setOfferFollowUpDecision((current) => (current ? { ...current, isSaving: false } : current));
          return;
        }
        await updateTaskStatus(task, "erledigt");
      } else if (outcome === "lost") {
        const markedLost = await markOfferLost(offer, reason, note, offer.projectId, (message) => {
          setOfferFollowUpDecision((current) =>
            current ? { ...current, isSaving: false, error: message } : current
          );
        });
        if (!markedLost) return;
        await updateTaskStatus(task, "erledigt");
      } else {
        const updatedTask = await updateOfferFollowUpTaskDeadline(task, followUpAt);
        if (!updatedTask) {
          setOfferFollowUpDecision((current) =>
            current ? { ...current, isSaving: false, error: "Nachfassdatum konnte nicht aktualisiert werden." } : current
          );
          return;
        }
        if (offer.projectId) {
          await addProjectLogbookEntry(
            offer.projectId,
            "Angebot: Nachfassen",
            `Angebot ${offer.offerNumber} wird weiter nachgefasst. Neues Datum: ${formatDeadline(followUpAt)}.${reason ? ` Grund: ${reason}.` : ""}`
          );
        }
      }

      await loadTasks();
      await loadNotifications(true);
      setOfferFollowUpDecision(null);
      setIsModalOpen(false);
      setEditingTask(null);
    } catch (error) {
      setOfferFollowUpDecision((current) =>
        current
          ? {
              ...current,
              isSaving: false,
              error: error instanceof Error ? error.message : "Entscheidung konnte nicht gespeichert werden.",
            }
          : current
      );
    }
  }

  async function createOfferFollowUpTask(
    savedOffer: OfferItem,
    project: HeroProjectPreview,
    potential?: ProjectPotential | null
  ) {
    const existingTask = tasks.find(
      (task) =>
        task.projectId === project.id &&
        task.titel.includes(savedOffer.offerNumber) &&
        task.titel.toLowerCase().includes("angebot nachfassen") &&
        !["erledigt", "archiviert", "abgelehnt"].includes(task.status)
    );

    if (existingTask) return existingTask;

    const deadline = getOfferFollowUpDeadline();
    const title = `Angebot nachfassen: ${savedOffer.offerNumber}`;
    const description = [
      `Angebot ${savedOffer.offerNumber} nachfassen.`,
      `Projekt: ${project.projectNumber || project.id} | ${project.title}`,
      project.customer ? `Kunde: ${project.customer}` : "",
      `Angebotswert: ${formatMoney(savedOffer.grossTotal)} brutto`,
      potential ? `Zusatzverkauf: ${getPotentialNumber(potential)} | ${potential.description}` : "",
    ]
      .filter(Boolean)
      .join("\n");

    const res = await fetch("/api/tasks", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        actorId: activeUserId,
        title,
        description,
        status: "in Bearbeitung",
        priority: "normal",
        tradeId: null,
        ownerId: activeUser?.id || activeUserId,
        deadline,
        customer: project.customer || savedOffer.customerName,
        customerClass: null,
        projectId: project.id,
        autoFeedbackEnabled: false,
        autoFeedbackRecipientId: null,
        recurrenceEnabled: false,
        recurrenceInterval: null,
        estimateMinutes: null,
        planningAllocations: [],
        taskLinks: [
          {
            label: `Angebot ${savedOffer.offerNumber}`,
            url: `offer:${savedOffer.id}`,
          },
        ],
        absenceHandoverTask: false,
      }),
    });

    if (!res.ok) {
      setErrorMessage("Nachfass-Aufgabe zum Angebot konnte nicht automatisch angelegt werden.");
      return null;
    }

    const savedTask = (await res.json()) as TaskItem;
    setTasks((currentTasks) => [savedTask, ...currentTasks.filter((task) => task.id !== savedTask.id)]);
    await addProjectLogbookEntry(
      project.id,
      "Angebot: Nachfass-Aufgabe",
      `Nachfass-Aufgabe für Angebot ${savedOffer.offerNumber} angelegt, fällig am ${formatDeadline(
        savedTask.faelligkeit
      )}.`
    );

    if (potential) {
      const linkedTask = getPotentialLinkedTask(potential);
      const isPotentialFollowUpTask =
        linkedTask &&
        linkedTask.id !== savedTask.id &&
        ["Zusatzverkauf nachfassen", "Potenzial nachfassen"].some((prefix) =>
          linkedTask.titel.toLowerCase().startsWith(prefix.toLowerCase())
        ) &&
        !["erledigt", "archiviert", "abgelehnt"].includes(linkedTask.status);

      if (isPotentialFollowUpTask) {
        await updateTaskStatus(linkedTask, "erledigt");
      }

      await updateProjectPotential(potential, "offered", {
        taskId: savedTask.id,
        followUpAt: savedTask.faelligkeit,
        note: `Angebot ${savedOffer.offerNumber} erstellt. Nachfass-Aufgabe angelegt.`,
      });
    }

    await loadTasks();
    await loadNotifications(true);
    return savedTask;
  }

  async function createProjectPotential(project: HeroProjectPreview, description: string) {
    if (!activeUserId) return null;

    const existingPotential = projectPotentials.find(
      (potential) =>
        potential.projectId === project.id &&
        potential.description === description &&
        ["open", "follow_up"].includes(potential.status)
    );
    if (existingPotential) return existingPotential;

    const res = await fetch("/api/potentials", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        contactId: project.contactId || "",
        customerName: project.customer || "",
        projectId: project.id,
        projectLabel: `${project.projectNumber || project.id} | ${project.title}`,
        description,
        ownerUserId: activeUser?.id || "",
        ownerName: activeUser?.name || "",
        priority: "normal",
        nextStep: "Zusatzverkauf prüfen und nächsten Schritt festlegen.",
        sourceType: "final_inspection",
        actorName: activeUser?.name || "",
      }),
    });

    if (!res.ok) return null;

    const savedPotential = (await res.json()) as ProjectPotential;
    setProjectPotentials((currentPotentials) => [savedPotential, ...currentPotentials]);
    return savedPotential;
  }

