  async function saveManualPotential() {
    const project = heroProjects.find((item) => item.id === manualPotentialProjectId);
    const description = manualPotentialDescription.trim();

    if (!project) {
      setManualPotentialError("Bitte ein vorhandenes Projekt auswählen.");
      return;
    }

    if (!description) {
      setManualPotentialError("Bitte den Zusatzverkauf kurz beschreiben.");
      return;
    }
    if (!activeUserId) {
      setManualPotentialError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }

    const res = await fetch("/api/potentials", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        contactId: project.contactId || "",
        customerName: project.customer || "",
        projectId: project.id,
        projectLabel: `${project.projectNumber || project.id} | ${project.title}`,
        description,
        ownerUserId: activeUser?.id || "",
        ownerName: activeUser?.name || "",
        estimatedValue: manualPotentialEstimatedValue,
        priority: "normal",
        nextStep: "",
        sourceType: "manual",
        actorName: activeUser?.name || "",
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setManualPotentialError(data?.error ?? "Zusatzverkauf konnte nicht angelegt werden.");
      return;
    }

    const savedPotential = (await res.json()) as ProjectPotential;
    setProjectPotentials((currentPotentials) => [savedPotential, ...currentPotentials]);
    await addProjectLogbookEntry(
      project.id,
      "Zusatzverkauf angelegt",
      `Zusatzverkauf ${getPotentialNumber(savedPotential)} manuell angelegt: ${description}.`
    );
    setPotentialStatusFilter("all");
    setIsManualPotentialModalOpen(false);
    openPotentialDetail(savedPotential);
  }

  async function updateProjectPotential(
    potential: ProjectPotential,
    status: ProjectPotentialStatus,
    input: {
      note?: string;
      taskId?: string;
      followUpAt?: string;
      ownerUserId?: string;
      ownerName?: string;
      estimatedValue?: string;
      priority?: ProjectPotentialPriority;
      nextStep?: string;
      lostReason?: string;
      description?: string;
    } = {}
  ) {
    if (!activeUserId) {
      setErrorMessage("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return null;
    }

    const res = await fetch("/api/potentials", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        actorId: activeUserId,
        id: potential.id,
        status,
        note: input.note || "",
        taskId: input.taskId || "",
        followUpAt: input.followUpAt || "",
        ownerUserId: input.ownerUserId,
        ownerName: input.ownerName,
        estimatedValue: input.estimatedValue,
        priority: input.priority,
        nextStep: input.nextStep,
        lostReason: input.lostReason,
        description: input.description,
        actorName: activeUser?.name || "",
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Zusatzverkauf konnte nicht aktualisiert werden.");
      return null;
    }

    const savedPotential = (await res.json()) as ProjectPotential;
    setProjectPotentials((currentPotentials) => [
      savedPotential,
      ...currentPotentials.filter((currentPotential) => currentPotential.id !== savedPotential.id),
    ]);
    return savedPotential;
  }

  function getPotentialProject(potential: ProjectPotential) {
    return heroProjects.find((project) => project.id === potential.projectId) ?? null;
  }

  function getPotentialStatusLabel(potential: ProjectPotential) {
    if (potential.status === "offered") return "Angeboten";
    if (potential.status === "completed") return "Durchgeführt";
    if (potential.status === "lost") return "Aktuell kein Interesse";
    if (potential.status === "follow_up") {
      const followUpTime = potential.followUpAt ? new Date(potential.followUpAt).getTime() : NaN;
      return Number.isFinite(followUpTime) && followUpTime <= Date.now()
        ? "Nachfassen fällig"
        : "Nachfassen geplant";
    }

    return "Festgestellt";
  }

  function getPotentialPriorityLabel(priority: ProjectPotentialPriority) {
    if (priority === "high") return "Hoch";
    if (priority === "low") return "Niedrig";
    return "Normal";
  }

  function getPotentialLinkedTask(potential: ProjectPotential) {
    return potential.taskId ? tasks.find((task) => task.id === potential.taskId) ?? null : null;
  }

  function getPotentialNumber(potential: ProjectPotential) {
    if (potential.number) return potential.number;

    const sortedPotentials = [...projectPotentials].sort((firstPotential, secondPotential) => {
      const firstTime = new Date(firstPotential.createdAt).getTime();
      const secondTime = new Date(secondPotential.createdAt).getTime();
      if (firstTime !== secondTime) return firstTime - secondTime;
      return firstPotential.id.localeCompare(secondPotential.id);
    });
    const index = sortedPotentials.findIndex((item) => item.id === potential.id);
    return `VC-${String(index >= 0 ? 1001 + index : 1000).padStart(4, "0")}`;
  }

  function getPotentialFollowUpInfo(potential: ProjectPotential) {
    const linkedTask = getPotentialLinkedTask(potential);

    if (linkedTask) {
      return {
        title: `${getTaskNumber(linkedTask.id, tasks)} | ${linkedTask.titel}`,
        detail: `${linkedTask.status} - fällig am ${formatDeadline(linkedTask.faelligkeit)}`,
      };
    }

    if (potential.status === "open") {
      return {
        title: "Entscheidung offen",
        detail: "Angebot erstellen, Nachfass-Aufgabe anlegen oder als aktuell kein Interesse mit Grund abschließen.",
      };
    }

    if (potential.status === "lost") {
      return {
        title: "Aktuell kein Interesse",
        detail: potential.lostReason || "Grund wurde nicht hinterlegt.",
      };
    }

    if (potential.status === "offered") {
      return {
        title: "Angebot erstellt",
        detail: "Die Angebotsnachfassung wird über die verknüpfte Angebotsaufgabe gesteuert.",
      };
    }

    if (potential.status === "completed") {
      return {
        title: "Durchgeführt",
        detail: "Der Zusatzverkauf wurde als durchgeführt markiert.",
      };
    }
    if (potential.followUpAt) {
      return {
        title: "Nachfassdatum ohne verknüpfte Aufgabe",
        detail: `${formatDeadline(potential.followUpAt)} - bitte bei Bedarf eine Nachfass-Aufgabe anlegen.`,
      };
    }

    return {
      title: "Keine Nachfass-Aufgabe geplant",
      detail: "Nachfassen wird über das Aufgabenmodul gesteuert.",
    };
  }

  function openPotentialLinkedTask(potential: ProjectPotential) {
    const linkedTask = getPotentialLinkedTask(potential);
    if (!linkedTask) return;

    setEditingPotential(null);
    openEditModal(linkedTask);
  }

  function openPotentialDetail(potential: ProjectPotential) {
    setEditingPotential(potential);
    setPotentialDraft({
      description: potential.description,
      status: potential.status,
      ownerUserId: potential.ownerUserId || "",
      ownerName: potential.ownerName || "",
      estimatedValue: potential.estimatedValue || "",
      priority: potential.priority || "normal",
      nextStep: potential.nextStep || "",
      followUpAt: potential.followUpAt ? potential.followUpAt.slice(0, 10) : "",
      lostReason: potential.lostReason || "",
      note: "",
    });
  }

  function buildPotentialChangeNote(potential: ProjectPotential, ownerName: string) {
    const changes: string[] = [];
    const nextStatusLabel = getPotentialStatusLabel({ ...potential, status: potentialDraft.status, followUpAt: potentialDraft.followUpAt });
    const previousOwner = potential.ownerName || "-";
    const nextOwner = ownerName || "-";
    const previousEstimatedValue = potential.estimatedValue || "-";
    const nextEstimatedValue = potentialDraft.estimatedValue || "-";

    if (potential.description !== potentialDraft.description) changes.push("Beschreibung");
    if (potential.status !== potentialDraft.status) {
      changes.push(`Status: ${getPotentialStatusLabel(potential)} -> ${nextStatusLabel}`);
    }
    if ((potential.ownerUserId || "") !== potentialDraft.ownerUserId || previousOwner !== nextOwner) {
      changes.push(`Verantwortlich: ${previousOwner} -> ${nextOwner}`);
    }
    if ((potential.estimatedValue || "") !== potentialDraft.estimatedValue) {
      changes.push(`Wert: ${previousEstimatedValue} -> ${nextEstimatedValue}`);
    }
    if ((potential.priority || "normal") !== potentialDraft.priority) {
      changes.push(`Prioritaet: ${getPotentialPriorityLabel(potential.priority)} -> ${getPotentialPriorityLabel(potentialDraft.priority)}`);
    }
    if ((potential.nextStep || "") !== potentialDraft.nextStep) changes.push("Naechster Schritt");
    if ((potential.lostReason || "") !== potentialDraft.lostReason) changes.push("Grund bei aktuell kein Interesse");

    if (potentialDraft.note.trim()) {
      changes.push(`Notiz: ${potentialDraft.note.trim()}`);
    }

    return changes.length > 0
      ? `Zusatzverkauf aktualisiert: ${changes.join("; ")}.`
      : "Zusatzverkauf aktualisiert: keine Feldänderung erkannt.";
  }

  function hasPotentialDraftChanges(potential: ProjectPotential, ownerName: string) {
    return (
      potential.description !== potentialDraft.description ||
      potential.status !== potentialDraft.status ||
      (potential.ownerUserId || "") !== potentialDraft.ownerUserId ||
      (potential.ownerName || "") !== (ownerName || "") ||
      (potential.estimatedValue || "") !== potentialDraft.estimatedValue ||
      (potential.priority || "normal") !== potentialDraft.priority ||
      (potential.nextStep || "") !== potentialDraft.nextStep ||
      (potential.lostReason || "") !== potentialDraft.lostReason ||
      potentialDraft.note.trim().length > 0
    );
  }

  async function savePotentialDetail() {
    if (!editingPotential) return;

    const owner = users.find((user) => user.id === potentialDraft.ownerUserId);
    const ownerName = owner?.name || potentialDraft.ownerName;
    const nextStatusLabel = getPotentialStatusLabel({
      ...editingPotential,
      status: potentialDraft.status,
      followUpAt: potentialDraft.followUpAt,
    });
    if (potentialDraft.status === "lost" && !potentialDraft.lostReason.trim()) {
      setErrorMessage("Bitte einen Grund eintragen, bevor der Zusatzverkauf auf aktuell kein Interesse gesetzt wird.");
      return;
    }
    if (potentialDraft.status === "follow_up" && !getPotentialLinkedTask(editingPotential)) {
      setErrorMessage("Bitte zuerst eine Nachfass-Aufgabe anlegen. Der Status Nachfassen braucht eine verknüpfte Aufgabe.");
      return;
    }
    if (potentialDraft.status === "offered" && editingPotential.status !== "offered") {
      setErrorMessage("Bitte das Angebot über \"Angebot erstellen\" anlegen. Der Status wird danach automatisch gesetzt.");
      return;
    }
    if (potentialDraft.status === "completed" && editingPotential.status !== "offered" && editingPotential.status !== "completed") {
      setErrorMessage("Durchgeführt kann erst nach einem erstellten Angebot gesetzt werden.");
      return;
    }
    const confirmed = window.confirm(
      `Der Zusatzverkauf wird mit dem Status "${nextStatusLabel}" gespeichert. Ist das korrekt?`
    );
    if (!confirmed) return;

    if (!hasPotentialDraftChanges(editingPotential, ownerName)) {
      setEditingPotential(null);
      return;
    }

    const savedPotential = await updateProjectPotential(editingPotential, potentialDraft.status, {
      ownerUserId: potentialDraft.ownerUserId,
      ownerName,
      estimatedValue: potentialDraft.estimatedValue,
      priority: potentialDraft.priority,
      nextStep: potentialDraft.nextStep,
      followUpAt: editingPotential.followUpAt || potentialDraft.followUpAt,
      lostReason: potentialDraft.lostReason,
      description: potentialDraft.description,
      note: buildPotentialChangeNote(editingPotential, ownerName),
    });

    if (savedPotential) {
      setEditingPotential(null);
      setPotentialDraft((currentDraft) => ({ ...currentDraft, note: "" }));
    }
  }

  async function offerPotential(potential: ProjectPotential) {
    const project = getPotentialProject(potential);
    if (!project) return;

    setSelectedProjectFileId(project.id);
    setUpsellOfferProjectId(project.id);
    openOfferModal(project, { fromUpsell: true });
  }

  async function schedulePotentialFollowUp(potential: ProjectPotential) {
    const project = getPotentialProject(potential);
    if (!project) return;
    const linkedTask = getPotentialLinkedTask(potential);

    if (linkedTask) {
      setEditingPotential(null);
      openEditModal(linkedTask);
      return;
    }

    setIsQuickCreateOpen(false);
    setEditingTask(null);
    setPendingPotentialFollowUp({ potentialId: potential.id, projectId: project.id });
    setErrorMessage("");
    resetForm();
    setTitel(`Zusatzverkauf nachfassen: ${project.projectNumber || project.id}`);
    setBeschreibung(
      [
        potential.description,
        `Projekt: ${project.projectNumber || project.id} | ${project.title}`,
        project.address ? `Projektanschrift: ${project.address}` : "",
      ]
        .filter(Boolean)
        .join("\n")
    );
    setPrioritaet("normal");
    setKunde(project.customer || potential.customerName);
    setSelectedHeroProjectId(project.id);
    setFaelligkeit(potential.followUpAt || getNextBusinessDayDeadlineValue());

    if (!hasLoadedHeroProjects) void loadHeroProjects();
    setIsModalOpen(true);
    setSelectedCalendarActionDate("");
  }
  async function closePotential(potential: ProjectPotential) {
    const project = getPotentialProject(potential);
    const note = window.prompt("Grund für aktuell kein Interesse");
    if (note === null) return;
    const cleanNote = note.trim();
    if (!cleanNote) {
      setErrorMessage("Bitte einen Grund eintragen, bevor der Zusatzverkauf auf aktuell kein Interesse gesetzt wird.");
      return;
    }

    await updateProjectPotential(potential, "lost", { note: cleanNote, lostReason: cleanNote });
    if (project) {
      await addProjectLogbookEntry(project.id, "Zusatzverkauf: Aktuell kein Interesse", cleanNote);
    }
  }
  async function openAttachmentDataUrl(dataUrl?: string, fileName = "Dokument") {
    if (!dataUrl) return;

    const renderAttachmentPreview = (openedWindow: Window, sourceUrl: string) => {
      const safeTitle = fileName.replaceAll('"', "&quot;");
      const isImage = dataUrl.startsWith("data:image/");
      openedWindow.document.title = fileName;
      openedWindow.document.body.style.margin = "0";
      openedWindow.document.body.style.background = isImage ? "#0f172a" : "";
      openedWindow.document.body.innerHTML = isImage
        ? `
          <img
            src="${sourceUrl}"
            alt="${safeTitle}"
            style="display:block;max-width:100vw;max-height:100vh;margin:auto;object-fit:contain"
          />
        `
        : `
          <iframe
            src="${sourceUrl}"
            title="${safeTitle}"
            style="border:0;height:100vh;width:100vw"
          ></iframe>
        `;
    };

    try {
      const blob = await fetch(dataUrl).then((response) => response.blob());
      const objectUrl = URL.createObjectURL(blob);
      const openedWindow = window.open("", "workpilot-document-viewer", "width=1200,height=900");

      if (!openedWindow) {
        setLogbookError("Dokument konnte nicht geöffnet werden. Bitte Popups für WorkPilot360 erlauben.");
        URL.revokeObjectURL(objectUrl);
        return;
      }

      renderAttachmentPreview(openedWindow, objectUrl);
      window.setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000);
    } catch {
      const openedWindow = window.open("", "workpilot-document-viewer", "width=1200,height=900");
      if (!openedWindow) {
        setLogbookError("Dokument konnte nicht geöffnet werden. Bitte Popups für WorkPilot360 erlauben.");
        return;
      }

      renderAttachmentPreview(openedWindow, dataUrl);
    }
  }

  async function uploadProjectDocumentCategory(category: CustomerDocumentType, files: FileList | null) {
    if (!selectedProjectFile || !files || files.length === 0) return;
    if (!activeUserId) {
      setLogbookError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }

    const createdAt = getProjectKind(selectedProjectFile).startsWith("Dauer")
      ? `${projectComparisonMonth || formatDateKey(new Date()).slice(0, 7)}-01T12:00:00.000Z`
      : "";
    const projectMonth = getProjectKind(selectedProjectFile).startsWith("Dauer")
      ? projectComparisonMonth || formatDateKey(new Date()).slice(0, 7)
      : "";
    let attachments: LogbookAttachment[];
    try {
      attachments = await Promise.all(
        Array.from(files).map((file) => readLogbookAttachment(file, "Dokument"))
      );
      const validationMessage = getLogbookAttachmentsValidationMessage(attachments);
      if (validationMessage) {
        setLogbookError(validationMessage);
        return;
      }
    } catch (error) {
      setLogbookError(error instanceof Error ? error.message : "Dokumente konnten nicht gelesen werden.");
      return;
    }

    const res = await fetch("/api/project-logbook-entries", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        actorId: activeUserId,
        projectId: selectedProjectFile.id,
        title: `Dokumente: ${category}`,
        text: `${category} abgelegt`,
        author: activeUser?.name || "Christian Eid",
        authorUserId: activeUserId,
        colleague: "",
        visibleFor: [
          "Geschaeftsfuehrer",
          "Vertriebler",
          "Niederlassungsleiter",
          "Monteur",
          "Buchhaltung",
        ],
        attachments,
        projectMonth,
        createdAt,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setLogbookError(data?.error ?? "Dokumente konnten nicht gespeichert werden.");
      return;
    }

    const savedEntry = (await res.json()) as ProjectLogbookEntry;
    setProjectLogbookEntries((currentEntries) => [savedEntry, ...currentEntries]);
    setLogbookError("");
  }

  function resetSmokeDetectorInstallationDraft() {
    setSmokeDetectorInstallationDate(formatDateKey(new Date()));
    setSmokeDetectorInstaller(activeUser?.name || "");
    setSmokeDetectorObjectNotes("");
    setSmokeDetectorDeviations("");
    setSmokeDetectorObjectImages([]);
    setSmokeDetectorDevices([createSmokeDetectorDeviceDraft()]);
    setLogbookError("");
  }

  function openSmokeDetectorInstallationChecklist() {
    resetSmokeDetectorInstallationDraft();
    setActiveChecklistView("smokeInstallation");
  }

  function updateSmokeDetectorDevice(
    deviceId: string,
    patch: Partial<Omit<SmokeDetectorDeviceDraft, "id" | "images">>
  ) {
    setSmokeDetectorDevices((currentDevices) =>
      currentDevices.map((device) => (device.id === deviceId ? { ...device, ...patch } : device))
    );
  }

  async function addSmokeDetectorImages(files: FileList | null, targetDeviceId?: string) {
    if (!files || files.length === 0) return;

    try {
      setLogbookError("");
      const attachments = await Promise.all(
        Array.from(files).map((file) => readProjectImageAttachment(file))
      );

      if (targetDeviceId) {
        setSmokeDetectorDevices((currentDevices) =>
          currentDevices.map((device) =>
            device.id === targetDeviceId
              ? { ...device, images: [...device.images, ...attachments] }
              : device
          )
        );
        return;
      }

      setSmokeDetectorObjectImages((currentImages) => [...currentImages, ...attachments]);
    } catch (error) {
      setLogbookError(error instanceof Error ? error.message : "Bilder konnten nicht gelesen werden.");
    }
  }

  function removeSmokeDetectorImage(targetDeviceId: string | undefined, imageIndex: number) {
    if (targetDeviceId) {
      setSmokeDetectorDevices((currentDevices) =>
        currentDevices.map((device) =>
          device.id === targetDeviceId
            ? { ...device, images: device.images.filter((_, index) => index !== imageIndex) }
            : device
        )
      );
      return;
    }

    setSmokeDetectorObjectImages((currentImages) => currentImages.filter((_, index) => index !== imageIndex));
  }

  async function saveSmokeDetectorInstallationReport() {
    if (!selectedProjectFile || isSavingSmokeDetectorReport || !activeUserId) return;

    setIsSavingSmokeDetectorReport(true);
    setLogbookError("");

    try {
      const res = await fetch("/api/smoke-detector-reports", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          actorId: activeUserId,
          projectId: selectedProjectFile.id,
          installationDate: smokeDetectorInstallationDate,
          installer: smokeDetectorInstaller.trim() || activeUser?.name || "",
          objectNotes: smokeDetectorObjectNotes.trim(),
          deviations: smokeDetectorDeviations.trim(),
          objectImages: smokeDetectorObjectImages,
          devices: smokeDetectorDevices,
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setLogbookError(data?.error ?? "Rauchmelder-Installationsnachweis konnte nicht erstellt werden.");
        return;
      }

      const savedEntry = (await res.json()) as ProjectLogbookEntry;
      setProjectLogbookEntries((currentEntries) => {
        const exists = currentEntries.some((entry) => entry.id === savedEntry.id);
        return exists
          ? currentEntries.map((entry) => (entry.id === savedEntry.id ? savedEntry : entry))
          : [savedEntry, ...currentEntries];
      });
      setSelectedProjectDocumentType("Checklisten");
      setActiveChecklistView("overview");
      resetSmokeDetectorInstallationDraft();
    } catch (error) {
      setLogbookError(
        error instanceof Error ? error.message : "Rauchmelder-Installationsnachweis konnte nicht erstellt werden."
      );
    } finally {
      setIsSavingSmokeDetectorReport(false);
    }
  }

  async function createActivityReportForSelectedProject() {
    if (!selectedProjectFile || isCreatingActivityReport || isCreatingActivityReportRef.current) return;

    isCreatingActivityReportRef.current = true;
    setIsCreatingActivityReport(true);
    setLogbookError("");

    try {
      const isRecurringProject = getProjectKind(selectedProjectFile).startsWith("Dauer");
      const reportMonth = isRecurringProject
        ? projectComparisonMonth || formatDateKey(new Date()).slice(0, 7)
        : "";
      const getProjectLogEntryMonthForReport = (entry: ProjectLogbookEntry) => {
        if (/^\d{4}-\d{2}$/.test(entry.projectMonth || "")) return entry.projectMonth || "";
        const rawDate = entry.date || "";
        const isoMatch = rawDate.match(/^(\d{4})-(\d{2})/);
        if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}`;
        const germanMatch = rawDate.match(/^(\d{2})\.(\d{2})\.(\d{4}|\d{2})/);
        if (germanMatch) {
          const year = germanMatch[3].length === 2 ? `20${germanMatch[3]}` : germanMatch[3];
          return `${year}-${germanMatch[2]}`;
        }

        const parsedDate = parseAppDateTime(rawDate);
        return Number.isNaN(parsedDate.getTime()) ? "" : formatDateKey(parsedDate).slice(0, 7);
      };
      const getVisibleReportImageKeys = (category: "Vorherbilder" | "Nachherbilder") =>
        projectLogbookEntries
          .filter((entry) => String(entry.projectId) === String(selectedProjectFile.id))
          .filter((entry) => entry.title === `Bilder: ${category}`)
          .filter((entry) => !isRecurringProject || getProjectLogEntryMonthForReport(entry) === reportMonth)
          .flatMap((entry) =>
            entry.attachments.flatMap((attachment, attachmentIndex) =>
              attachment.type === "Bild" && attachment.dataUrl
                ? [`${entry.id}:${attachmentIndex}:${attachment.name}`]
                : []
            )
          );

      const res = await fetch("/api/activity-reports", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          actorId: activeUserId,
          projectId: selectedProjectFile.id,
          month: reportMonth,
          beforeImageKeys: getVisibleReportImageKeys("Vorherbilder"),
          afterImageKeys: getVisibleReportImageKeys("Nachherbilder"),
        }),
      });

      const data = await res.json().catch(() => null);
      if (!res.ok) {
        setLogbookError(data?.error ?? "Tätigkeitsbericht konnte nicht erstellt werden.");
        return;
      }

      const savedEntry = data as ProjectLogbookEntry;
      setProjectLogbookEntries((currentEntries) => [
        savedEntry,
        ...currentEntries.filter((entry) => entry.id !== savedEntry.id),
      ]);
      setSelectedProjectDocumentType("Tätigkeitsberichte");
      setLogbookError("");
    } finally {
      isCreatingActivityReportRef.current = false;
      setIsCreatingActivityReport(false);
    }
  }

  function getContactAddressLine(contact: ContactItem) {
    return [contact.street, [contact.postalCode, contact.city].filter(Boolean).join(" ")]
      .filter(Boolean)
      .join(", ");
  }

  function hasCompleteContactAddress(contact?: ContactItem | null) {
    return Boolean(contact?.street.trim() && contact?.postalCode.trim() && contact?.city.trim());
  }

  function getProjectPlanningAddress(project?: HeroProjectPreview | null) {
    if (!project) return "";
    if (project.address?.trim()) return project.address.trim();

    const linkedObjectAddress = objectAddresses.find(
      (address) => address.id === project.objectAddressId && address.isActive
    );
    if (linkedObjectAddress) return formatObjectAddress(linkedObjectAddress);

    const addressContact = contacts.find((contact) => contact.id === project.addressContactId);
    if (hasCompleteContactAddress(addressContact)) return getContactAddressLine(addressContact!);

    const projectCustomer = contacts.find((contact) => contact.id === project.contactId);
    return hasCompleteContactAddress(projectCustomer) ? getContactAddressLine(projectCustomer!) : "";
  }

  function formatObjectAddress(address: ObjectAddress) {
    return `${address.name} | ${address.street}, ${address.postalCode} ${address.city}`;
  }

  function getActiveObjectAddresses(customerId?: string | null) {
    return objectAddresses
      .filter((address) => address.isActive && address.customerId === customerId)
      .sort((first, second) => first.name.localeCompare(second.name, "de"));
  }

  function openObjectAddressModal(customerId: string, address?: ObjectAddress) {
    setEditingObjectAddressId(address?.id ?? "");
    setObjectAddressDraft(
      address
        ? {
            customerId: address.customerId,
            name: address.name,
            street: address.street,
            postalCode: address.postalCode,
            city: address.city,
            country: address.country,
            isActive: address.isActive,
          }
        : { ...emptyObjectAddressDraft, customerId }
    );
    setObjectAddressError("");
    setIsObjectAddressModalOpen(true);
  }

  async function saveObjectAddress() {
    if (!activeUserId) return;
    setObjectAddressError("");
    const res = await fetch("/api/object-addresses", {
      method: editingObjectAddressId ? "PATCH" : "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...objectAddressDraft, id: editingObjectAddressId, actorId: activeUserId }),
    });
    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setObjectAddressError(data?.error ?? "Objektadresse konnte nicht gespeichert werden.");
      return;
    }
    await loadObjectAddresses();
    setIsObjectAddressModalOpen(false);
    setEditingObjectAddressId("");
  }

  async function deactivateObjectAddress(address: ObjectAddress) {
    if (!activeUserId || !window.confirm(`Objektadresse „${address.name}“ deaktivieren?`)) return;
    const params = new URLSearchParams({ id: address.id, actorId: activeUserId });
    const res = await fetch(`/api/object-addresses?${params.toString()}`, { method: "DELETE" });
    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setObjectAddressError(data?.error ?? "Objektadresse konnte nicht deaktiviert werden.");
      return;
    }
    await loadObjectAddresses();
  }

  async function persistProject(project: HeroProjectPreview) {
    if (!activeUserId) {
      throw new Error("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
    }

    const res = await fetch("/api/hero/projects", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ ...project, actorId: activeUserId }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      throw new Error(data?.error ?? "Projekt konnte nicht gespeichert werden.");
    }

    return (await res.json()) as HeroProjectPreview;
  }

  async function applyProjectStatus(input: {
    project?: HeroProjectPreview | null;
    nextStatus: string;
    reason: string;
    logPrefix?: string;
  }) {
    const project = input.project;
    if (
      !project ||
      !input.nextStatus ||
      normalizeProjectPipelineStatus(project.status) === normalizeProjectPipelineStatus(input.nextStatus)
    ) {
      return null;
    }

    const previousStatus = project.status || "-";
    const updatedProject = { ...project, status: input.nextStatus };
    try {
      const savedProject = await persistProject(updatedProject);
      setHeroProjects((currentProjects) =>
        currentProjects.map((currentProject) =>
          currentProject.id === savedProject.id ? savedProject : currentProject
        )
      );
      if (selectedProjectFileId === savedProject.id) {
        setSelectedProjectPipelineStatus(savedProject.status);
        setSelectedHeroDetailId(savedProject.id);
      }
      await addProjectLogbookEntry(
        savedProject.id,
        "Projektstatus",
        `${input.logPrefix || "Projektstatus per Automatik geändert"}: ${previousStatus} -> ${savedProject.status}. Auslöser: ${input.reason}.`
      );
      return savedProject;
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Projektstatus konnte nicht gespeichert werden.");
      return null;
    }
  }

  async function confirmAndApplyProjectStatus(input: {
    project?: HeroProjectPreview | null;
    nextStatus: string;
    reason: string;
    question: string;
  }) {
    const project = input.project;
    if (!project || !input.nextStatus || normalizeProjectPipelineStatus(project.status) === input.nextStatus) {
      return false;
    }
    if (shouldPreserveCriticalProjectStatus(project.status, input.nextStatus)) {
      return false;
    }

    const confirmed = window.confirm(input.question);
    if (!confirmed) return false;

    const previousStatus = project.status || "-";
    const updatedProject = { ...project, status: input.nextStatus };
    try {
      const savedProject = await persistProject(updatedProject);
      setHeroProjects((currentProjects) =>
        currentProjects.map((currentProject) =>
          currentProject.id === savedProject.id ? savedProject : currentProject
        )
      );
      if (selectedProjectFileId === savedProject.id) {
        setSelectedProjectPipelineStatus(savedProject.status);
        setSelectedHeroDetailId(savedProject.id);
      }
      await addProjectLogbookEntry(
        savedProject.id,
        "Projektstatus",
        `Projektstatus per bestätigter Automatik geändert: ${previousStatus} -> ${savedProject.status}. Auslöser: ${input.reason}.`
      );
      return true;
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Projektstatus konnte nicht gespeichert werden.");
      return false;
    }
  }

  async function confirmImplementationStatus(project?: HeroProjectPreview | null, reason = "Echte Ausfuehrung erkannt") {
    return confirmAndApplyProjectStatus({
      project,
      nextStatus: "Umsetzung",
      reason,
      question: `Für das Projekt "${project?.projectNumber || project?.title || "ohne Nummer"}" wurde eine echte Ausführung erkannt. Soll der Projektstatus auf "In Umsetzung" gesetzt werden?`,
    });
  }

  async function applyBillingCheckStatus(
    project?: HeroProjectPreview | null,
    monthKey = getCurrentMonthKey(),
    options: { assumeFinalInspection?: boolean } = {}
  ) {
    if (!project) return null;

    const state = getProjectBillingReadyState(project, monthKey, options);
    const nextStatus = state.ready ? "Zur Abrechnung bereit" : "Abrechnungsprüfung";
    const reason = state.ready
      ? "Abrechnungsprüfung vollständig"
      : `Abrechnungsprüfung offen: ${state.reason}`;

    return applyProjectStatus({
      project,
      nextStatus,
      reason,
      logPrefix: "Projektstatus per Abrechnungsprüfung geändert",
    });
  }

  async function confirmFinalInspectionStatus(
    project?: HeroProjectPreview | null,
    monthKey = getCurrentMonthKey(),
    options: { assumeFinalInspection?: boolean } = {}
  ) {
    return applyBillingCheckStatus(project, monthKey, options);
  }

  async function saveProjectDraft() {
    const selectedContact = contacts.find((contact) => contact.id === projectDraft.contactId);
    const selectedPrimaryAddress =
      selectedContact &&
      !projectDraft.objectAddressId &&
      projectDraft.addressContactId === selectedContact.id &&
      hasCompleteContactAddress(selectedContact)
        ? selectedContact
        : null;
    const selectedObjectAddress = objectAddresses.find(
      (address) => address.id === projectDraft.objectAddressId && address.isActive
    );
    const selectedContactPerson = contacts.find(
      (contact) => contact.id === projectDraft.contactPersonId
    );
    const editingProject = heroProjects.find((project) => project.id === editingProjectDataId);
    const targetPipeline =
      projectDraft.projectType === "Projekt OK immocare" ? projectPipelines[1] : projectPipelines[0];
    const prefix = getProjectTradePrefix(projectDraft.trade, trades);
    const projectNumber =
      editingProject?.projectNumber || `${prefix}-${getNextProjectSequence(heroProjects)}`;
    const projectTitle =
      projectDraft.name ||
      [`Projekt ${projectNumber}`, projectDraft.trade].filter(Boolean).join(" - ") ||
      "Neues Projekt";
    const recurringBillingMode = isRecurringProjectKindValue(projectDraft.projectKind)
      ? normalizeRecurringBillingMode(projectDraft.recurringBillingMode)
      : "";

    if (isRecurringProjectKindValue(projectDraft.projectKind) && !recurringBillingMode) {
      const message = "Bitte wähle das Abrechnungsmodell für diesen Dauerläufer aus.";
      setErrorMessage(message);
      return;
    }

    if (projectDraft.projectType === "Projekt OK immocare" && !selectedPrimaryAddress && !selectedObjectAddress) {
      setErrorMessage("Bitte wähle für das Immocare-Projekt eine Objektadresse aus.");
      return;
    }

    const projectAddress = selectedObjectAddress
      ? `${selectedObjectAddress.street}, ${selectedObjectAddress.postalCode} ${selectedObjectAddress.city}`
      : selectedPrimaryAddress
        ? getContactAddressLine(selectedPrimaryAddress)
        : editingProject?.address || "";
    const projectDescription = [
      projectDraft.projectType,
      normalizeProjectKindValue(projectDraft.projectKind),
      projectDraft.trade,
      projectDraft.projectRuntimeFrom ? `Start: ${projectDraft.projectRuntimeFrom}` : "",
      isRecurringProjectKindValue(projectDraft.projectKind) && projectDraft.projectRuntimeUntil
        ? `Laufzeit bis: ${projectDraft.projectRuntimeUntil}`
        : "",
      isRecurringProjectKindValue(projectDraft.projectKind)
        ? `Abrechnungsmodell: ${formatRecurringBillingModeLabel(recurringBillingMode)}`
        : "",
      isRecurringProjectKindValue(projectDraft.projectKind)
        ? `Fakturierung: ${projectDraft.billingInterval}`
        : "",
      recurringBillingMode === RECURRING_BILLING_MONTHLY_FLAT && projectDraft.forecastNetAmount
        ? `Forecast: ${projectDraft.forecastNetAmount} EUR (${projectDraft.forecastBillingType})`
        : "",
      projectDraft.volume ? `Volumen: ${projectDraft.volume} EUR` : "",
      projectDraft.timeBudgetHours ? `Zeitkontingent: ${projectDraft.timeBudgetHours} Std.` : "",
      projectDraft.source ? `Quelle: ${projectDraft.source}` : "",
      selectedContactPerson ? `Ansprechpartner/in: ${getContactDisplayName(selectedContactPerson)}` : "",
    ]
      .filter(Boolean)
      .join(" | ");

    if (editingProject) {
      const previousBudget = editingProject.timeBudgetHours || "";
      const nextBudget = projectDraft.timeBudgetHours || "";
      const budgetChanged = parseHoursInput(previousBudget) !== parseHoursInput(nextBudget);
      const updatedProject: HeroProjectPreview = {
        ...editingProject,
        projectNumber,
        title: projectTitle,
        customer: selectedContact ? getContactLabel(selectedContact) : editingProject.customer,
        contactId: selectedContact?.id || "",
        contactPersonId: selectedContactPerson?.id || "",
        addressContactId: selectedPrimaryAddress?.id || "",
        objectAddressId: selectedObjectAddress?.id || "",
        projectType: projectDraft.projectType,
        projectKind: normalizeProjectKindValue(projectDraft.projectKind),
        projectRuntimeFrom: projectDraft.projectRuntimeFrom,
        projectRuntimeUntil:
          isRecurringProjectKindValue(projectDraft.projectKind) ? projectDraft.projectRuntimeUntil : "",
        billingInterval:
          isRecurringProjectKindValue(projectDraft.projectKind) ? projectDraft.billingInterval : "",
        recurringBillingMode,
        forecastBillingType:
          recurringBillingMode === RECURRING_BILLING_MONTHLY_FLAT ? projectDraft.forecastBillingType : "",
        forecastNetAmount:
          recurringBillingMode === RECURRING_BILLING_MONTHLY_FLAT ? projectDraft.forecastNetAmount : "",
        trade: projectDraft.trade,
        branch: projectDraft.branch,
        volume: projectDraft.volume,
        timeBudgetEnabled: editingProject.timeBudgetEnabled ?? false,
        timeBudgetHours: nextBudget,
        timeBudgetHistory: budgetChanged
          ? [
              {
                id: `budget-${Date.now()}`,
                changedAt: new Intl.DateTimeFormat(APP_LOCALE, {
                  day: "2-digit",
                  month: "2-digit",
                  year: "2-digit",
                  hour: "2-digit",
                  minute: "2-digit",
                  timeZone: APP_TIME_ZONE,
                }).format(new Date()),
                changedBy: activeUser?.name || "Aktueller Mitarbeiter",
                previousHours: previousBudget || "0",
                nextHours: nextBudget || "0",
              },
              ...(editingProject.timeBudgetHistory || []),
            ]
          : editingProject.timeBudgetHistory,
        source: projectDraft.source,
        address: projectAddress,
        participants: projectDraft.participants,
        responsibleName: projectDraft.responsibleName || activeUser?.name || "Christian Eid",
        deputyName: projectDraft.deputyName,
        deputyFrom: projectDraft.deputyFrom,
        deputyUntil: projectDraft.deputyUntil,
        description: projectDescription,
      };

      let savedProject: HeroProjectPreview;
      try {
        savedProject = await persistProject(updatedProject);
      } catch (error) {
        setErrorMessage(error instanceof Error ? error.message : "Projekt konnte nicht gespeichert werden.");
        return;
      }

      setHeroProjects((currentProjects) =>
        currentProjects.map((project) =>
          project.id === editingProject.id ? savedProject : project
        )
      );
      setSelectedHeroDetailId(savedProject.id);
      openProjectFile(savedProject, { activeTab: targetPipeline.tab });
      setSelectedProjectPipelineStatus(savedProject.status || "Alle Offenen");
      setSelectedProjectKindFilter(normalizeProjectKindValue(projectDraft.projectKind));
await addProjectLogbookEntry(
  savedProject.id,
  "Projekt",
  `Projektdaten geändert: ${savedProject.projectNumber || savedProject.id} | ${savedProject.title}.`
);
      closeProjectModal();
      return;
    }

    const createdProject: HeroProjectPreview = {
      id: `${targetPipeline.id}-${Date.now()}`,
      projectNumber,
      title: projectTitle,
      customer: selectedContact ? getContactLabel(selectedContact) : "",
      status: "Lead / Klärung",
      statusCode: "lead",
      contactId: selectedContact?.id,
      contactPersonId: selectedContactPerson?.id,
      addressContactId: selectedPrimaryAddress?.id || "",
      objectAddressId: selectedObjectAddress?.id,
      projectType: projectDraft.projectType,
      projectKind: normalizeProjectKindValue(projectDraft.projectKind),
      projectRuntimeFrom: projectDraft.projectRuntimeFrom,
      projectRuntimeUntil: isRecurringProjectKindValue(projectDraft.projectKind) ? projectDraft.projectRuntimeUntil : "",
      billingInterval: isRecurringProjectKindValue(projectDraft.projectKind) ? projectDraft.billingInterval : "",
      recurringBillingMode,
      forecastBillingType:
        recurringBillingMode === RECURRING_BILLING_MONTHLY_FLAT ? projectDraft.forecastBillingType : "",
      forecastNetAmount:
        recurringBillingMode === RECURRING_BILLING_MONTHLY_FLAT ? projectDraft.forecastNetAmount : "",
      trade: projectDraft.trade,
      branch: projectDraft.branch,
      volume: projectDraft.volume,
      timeBudgetEnabled: false,
      timeBudgetHours: projectDraft.timeBudgetHours,
      timeBudgetHistory: projectDraft.timeBudgetHours
        ? [
            {
              id: `budget-${Date.now()}`,
              changedAt: new Intl.DateTimeFormat(APP_LOCALE, {
                day: "2-digit",
                month: "2-digit",
                year: "2-digit",
                hour: "2-digit",
                minute: "2-digit",
                timeZone: APP_TIME_ZONE,
              }).format(new Date()),
              changedBy: activeUser?.name || "Aktueller Mitarbeiter",
              previousHours: "0",
              nextHours: projectDraft.timeBudgetHours,
            },
          ]
        : [],
      source: projectDraft.source,
      address: projectAddress,
      participants: projectDraft.participants,
      responsibleName: projectDraft.responsibleName || activeUser?.name || "Christian Eid",
      deputyName: projectDraft.deputyName,
      deputyFrom: projectDraft.deputyFrom,
      deputyUntil: projectDraft.deputyUntil,
      createdAt: new Intl.DateTimeFormat(APP_LOCALE, {
        day: "2-digit",
        month: "2-digit",
        year: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        timeZone: APP_TIME_ZONE,
      }).format(new Date()),
      description: projectDescription,
    };

    let savedProject: HeroProjectPreview;
    try {
      savedProject = await persistProject(createdProject);
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Projekt konnte nicht gespeichert werden.");
      return;
    }

    setHeroProjects((currentProjects) => [savedProject, ...currentProjects]);
    setSelectedHeroDetailId(savedProject.id);
    openProjectFile(savedProject, { activeTab: targetPipeline.tab });
    setSelectedProjectPipelineStatus("Lead / Klärung");
    setSelectedProjectKindFilter(normalizeProjectKindValue(projectDraft.projectKind));
    await addProjectLogbookEntry(
      savedProject.id,
      "Projekt",
      `Projekt angelegt: ${savedProject.projectNumber || savedProject.id} | ${savedProject.title}.`
    );
    const projectCreateNotes = await loadCustomerProjectNotes({
      customerId: selectedContact?.id || savedProject.contactId || "",
      projectId: savedProject.id,
      context: "projectCreate",
      userId: activeUserId,
    });
    if (projectCreateNotes.length > 0) {
      setIsPendingNoteConfirmed(false);
      setPendingProjectCreateNoteConfirm({
        notes: projectCreateNotes,
        projectId: savedProject.id,
        customerId: selectedContact?.id || savedProject.contactId || "",
      });
    }
    closeProjectModal();
  }

