    setPlanningEntryTrade(isHourlyRecurringProject(project) ? project.trade || "" : "");
    setPlanningEntryBillingCatalogItemId("");
    setPlanningEntryHasAdditionalEmployees(isHourlyRecurringProject(project) ? "" : "no");
