      const riskScore =
        row.overdueInvoiceCount * 3 +
        row.highestReminderLevel * 2 +
        hotAlertCount * 2 +
        (row.openRevenue > 0 && row.revenue > 0 && row.openRevenue / row.revenue > 0.5 ? 1 : 0);

