  const overviewOpenTotal = reportInvoices
    .filter((invoice) => !isInvoicePaid(invoice))
    .reduce((sum, invoice) => sum + invoice.netTotal, 0);
  const previousOverviewOpenTotal = previousReportInvoices
    .filter((invoice) => !isInvoicePaid(invoice))
